// Per-toy materials for Hands-on (lane Hands engine A): bounce, weight,
// friction, rolling resistance, spin, air drag and lift, so a thrown toy
// moves like the real thing. Pure JavaScript, no DOM.
//
// A recipe asks for one with `hands.material`: a preset's name (below) or
// an object of the same keys (a preset's keys can be overridden:
// `{ preset: "baseball", magnus: 0.06 }`). Toys without one play exactly
// as before.
//
// The keys (real units where they are real):
// - mass (kg) and r (m, the radius, or half the longest side): the air
//   drag's strength comes from these with cd (the drag coefficient), as
//   the fall-to-top-speed distance in toy radii, Fr = 2 m / (rho cd pi r^3).
//   That number has no units, so it holds whatever the toy's size on
//   screen and Hands-on's gravity.
// - bounce: the coefficient of restitution on a hard floor (the floor
//   takes the same, so a basketball keeps about 0.8 of its speed).
// - friction (sliding, 0..1), roll (rolling resistance, as a fraction of
//   gravity: a pool ball on cloth 0.01, a soccer ball on grass 0.06).
// - spin: how much a throw spins it (1: the spin a hand gives where it
//   holds it, from the hold point's offset and the throw's speed; a low
//   grab gives backspin, a side grab sidespin). spinDecay: per second, in
//   the air. magnus: the curve a spin gives (toy units).
// - lift: a flat flier's lift (a disc, a paper plane, a cap), along its
//   own up (`up`, local) and growing with speed squared; gyro: a spinning
//   disc holds its tilt; fade: how fast it banks as its spin dies.
//
// Drag is the real thing, scaled (Fr has no units). Lift and the Magnus
// curve are not: Hands-on throws at most 4 toy radii per second, a hundred
// times slower than a real pitch, so `lift` and `magnus` are set so the
// glide and the curve show in a toy's short flight, in the real direction
// and in the real order (a disc glides more than a cap; a baseball curves
// more than a soccer ball).
// - nose (local axis): it turns to fly nose first (a shuttlecock's cork, a
//   paper plane's nose, a bolt), as strongly as `vane`.
// - heavy: how a heavy thing can't be thrown fast (from the mass: a throw's
//   top speed scales by (0.6 kg / mass)^0.2, between 0.45 and 1.25).
// - drift: a light ball wanders sideways on the air as it falls (times
//   gravity; a beach ball 0.06).
// - fingertip: true for a ball that spins on a fingertip (an upward flick
//   while holding it). warm: [first, top] bounce for a squash ball that
//   gets livelier each throw.
//
// Real numbers: the regulation sizes and masses of each sport's governing
// body (FIBA, FIFA, ITF, MLB, World Rugby, FIVB, World Aquatics, ITTF, the
// R&A, ICC, USBC, WPA, USA Pickleball, World Squash, World Lacrosse, the
// IIHF and BWF), the restitution each rule book asks for where it asks
// (a basketball dropped from 1.8 m bounces to 1.2-1.4 m: 0.82-0.88; a
// tennis ball from 254 cm to 135-147 cm: 0.73-0.76; a ping-pong ball from
// 30 cm to 23 cm: 0.88), and the textbook drag coefficient of a sphere,
// 0.47 (0.25-0.3 for a golf ball's dimples at speed). Codex task 11 is
// gathering them, with links, into tools/hands-on-materials.json; until it
// lands these are the well-known values.

export const AIR = 1.2; // kg per cubic meter

export const MATERIALS = {
  basketball: { mass: 0.62, r: 0.12, bounce: 0.82, friction: 0.7, roll: 0.02, cd: 0.47, spin: 0.6, magnus: 0.02, spinDecay: 0.12, fingertip: true }, // prettier-ignore
  "soccer-ball": { mass: 0.43, r: 0.11, bounce: 0.75, friction: 0.6, roll: 0.06, cd: 0.47, spin: 0.7, magnus: 0.03 }, // prettier-ignore
  "american-football": { mass: 0.41, r: 0.14, bounce: 0.55, friction: 0.6, roll: 0.08, cd: 0.15, spin: 0.4, spiral: 14 }, // prettier-ignore
  "tennis-ball": { mass: 0.058, r: 0.0335, bounce: 0.75, friction: 0.6, roll: 0.03, cd: 0.55, spin: 0.8, magnus: 0.03 }, // prettier-ignore
  baseball: { mass: 0.145, r: 0.0366, bounce: 0.55, friction: 0.5, roll: 0.04, cd: 0.35, spin: 1, magnus: 0.06 }, // prettier-ignore
  softball: { mass: 0.18, r: 0.0485, bounce: 0.45, friction: 0.5, roll: 0.05, cd: 0.4, spin: 0.8, magnus: 0.04 }, // prettier-ignore
  "beach-ball": { mass: 0.06, r: 0.3, bounce: 0.6, friction: 0.5, roll: 0.05, cd: 0.47, spin: 0.5, magnus: 0.04, spinDecay: 0.4, drift: 0.06 }, // prettier-ignore
  "golf-ball": { mass: 0.0459, r: 0.02135, bounce: 0.78, friction: 0.5, roll: 0.03, cd: 0.27, spin: 1.2, magnus: 0.07 }, // prettier-ignore
  "rugby-ball": { mass: 0.44, r: 0.15, bounce: 0.5, friction: 0.6, roll: 0.1, cd: 0.2, spin: 0.6, tumble: 9 }, // prettier-ignore
  volleyball: { mass: 0.27, r: 0.105, bounce: 0.7, friction: 0.6, roll: 0.04, cd: 0.47, spin: 0.6, magnus: 0.03 }, // prettier-ignore
  "water-polo-ball": { mass: 0.43, r: 0.11, bounce: 0.6, friction: 0.8, roll: 0.05, cd: 0.47, spin: 0.5 }, // prettier-ignore
  "ping-pong-ball": { mass: 0.0027, r: 0.02, bounce: 0.88, friction: 0.4, roll: 0.02, cd: 0.47, spin: 1, magnus: 0.06 }, // prettier-ignore
  "cricket-ball": { mass: 0.16, r: 0.036, bounce: 0.5, friction: 0.35, roll: 0.05, cd: 0.4, spin: 0.8, magnus: 0.03 }, // prettier-ignore
  "bowling-ball": { mass: 7.26, r: 0.109, bounce: 0.12, friction: 0.12, roll: 0.01, cd: 0.47, spin: 0.8, hook: 0.6 }, // prettier-ignore
  "pool-ball": { mass: 0.17, r: 0.0286, bounce: 0.5, friction: 0.2, roll: 0.01, cd: 0.47, spin: 1.2 }, // prettier-ignore
  pickleball: { mass: 0.026, r: 0.037, bounce: 0.5, friction: 0.5, roll: 0.05, cd: 0.6, spin: 0.6, magnus: 0.03 }, // prettier-ignore
  dodgeball: { mass: 0.3, r: 0.105, bounce: 0.6, friction: 0.6, roll: 0.06, cd: 0.47, spin: 0.5 }, // prettier-ignore
  "medicine-ball": { mass: 4, r: 0.14, bounce: 0.08, friction: 0.8, roll: 0.15, cd: 0.47, spin: 0.3 }, // prettier-ignore
  "lacrosse-ball": { mass: 0.145, r: 0.032, bounce: 0.68, friction: 0.7, roll: 0.03, cd: 0.47, spin: 0.7, magnus: 0.03 }, // prettier-ignore
  "squash-ball": { mass: 0.024, r: 0.02, bounce: 0.3, friction: 0.6, roll: 0.05, cd: 0.47, spin: 0.6, warm: [0.25, 0.5] }, // prettier-ignore
  "bouncy-ball": { mass: 0.02, r: 0.0135, bounce: 0.9, friction: 0.8, roll: 0.02, cd: 0.47, spin: 1 }, // prettier-ignore
  marble: { mass: 0.005, r: 0.008, bounce: 0.55, friction: 0.3, roll: 0.006, cd: 0.47, spin: 0.8 }, // prettier-ignore
  "hockey-puck": { mass: 0.17, r: 0.038, bounce: 0.2, friction: 0.04, roll: 0, cd: 0.8, spin: 0.6 }, // prettier-ignore
  shuttlecock: { mass: 0.0052, r: 0.04, bounce: 0.2, friction: 0.6, roll: 0.2, cd: 0.6, spin: 0.3, nose: [0, -1, 0], vane: 30 }, // prettier-ignore
  "flying-disc": { mass: 0.175, r: 0.1365, bounce: 0.25, friction: 0.5, roll: 0.3, cd: 0.08, spin: 1, lift: 0.9, up: [0, 1, 0], gyro: 6, fade: 0.6 }, // prettier-ignore
  "paper-plane": { mass: 0.005, r: 0.12, bounce: 0.1, friction: 0.7, roll: 0.5, cd: 0.25, spin: 0.2, lift: 1.4, up: [0, 1, 0], nose: [1, 0, 0], vane: 6 }, // prettier-ignore
  "baseball-cap": { mass: 0.1, r: 0.13, bounce: 0.15, friction: 0.8, roll: 0.5, cd: 0.4, spin: 0.8, lift: 0.5, up: [0, 1, 0], gyro: 2, fade: 1 }, // prettier-ignore
};

// The material a recipe's hands block asks for, filled in; null when it
// asks for none.
export function materialFor(hands) {
  const m = hands?.material;
  if (!m) return null;
  const base = typeof m === "string" ? MATERIALS[m] : m.preset ? MATERIALS[m.preset] : null;
  const out = { mass: 0.5, r: 0.1, bounce: 0.4, friction: 0.6, roll: 0.05, cd: 0.47, spin: 0.5, magnus: 0, spinDecay: 0.2, ...(base || {}), ...(typeof m === "object" ? m : {}) }; // prettier-ignore
  // The fall-to-top-speed distance, in toy radii.
  out.fr = (2 * out.mass) / (AIR * out.cd * Math.PI * out.r ** 3);
  out.throwScale = Math.max(0.45, Math.min(1.25, (0.6 / out.mass) ** 0.2));
  return out;
}

// Sets a body's contact numbers from its material (and the floor's, so the
// bounce on it is the material's own).
export function applyMaterial(body, mat, floor) {
  body.restitution = mat.bounce;
  body.friction = mat.friction;
  // The air's drag is worked out by airForce below; this is only what a
  // body loses anyway (a little, so nothing drifts for ever).
  body.damping = 0.02;
  body.angDamping = mat.spinDecay;
  if (floor) {
    floor.restitution = mat.bounce;
    floor.friction = Math.max(floor.friction, mat.friction);
  }
}

// The air on one body, for one substep h: quadratic drag, the Magnus curve
// of a spin, a flat flier's lift and a nose that turns into the wind. G is
// the world's gravity (toy units), R the toy's radius (the body's units).
export function airForce(b, mat, G, R, h, touching = false) {
  if (b.fixed || b.held) return;
  const v = b.vel;
  const sp = Math.hypot(v[0], v[1], v[2]);
  if (sp < 1e-6) return;
  // Drag: a = v^2 / (Fr R), so the top speed falling is sqrt(Fr G R).
  const k = (sp / (mat.fr * R)) * h;
  const f = 1 / (1 + k); // (implicit, so it never overshoots)
  const w = b.omega;
  const dv = [v[0] * (f - 1), v[1] * (f - 1), v[2] * (f - 1)];
  if (mat.magnus) {
    // a = magnus (w x v), the curve a spinning ball takes.
    const c = [w[1] * v[2] - w[2] * v[1], w[2] * v[0] - w[0] * v[2], w[0] * v[1] - w[1] * v[0]];
    for (let i = 0; i < 3; i++) dv[i] += mat.magnus * c[i] * h;
  }
  if (mat.lift) {
    // Lift along the flier's own up, growing with the square of its speed
    // across that up (full at a brisk throw, 3 toy radii per second), and
    // with its tilt into the wind (a disc's lift coefficient, 0.15 + 1.4
    // times the angle of attack, scaled so a throw shows its glide).
    const up = rotate(b.q, mat.up || [0, 1, 0]);
    const vn = up[0] * v[0] + up[1] * v[1] + up[2] * v[2];
    const vt2 = Math.max(0, sp * sp - vn * vn);
    const aoa = Math.max(-0.5, Math.min(0.5, -vn / sp));
    const cl = Math.max(-0.6, Math.min(0.9, (0.15 + 1.4 * aoa) / 0.4));
    const L = mat.lift * G * Math.min(1.5, vt2 / (9 * R * R)) * cl;
    // (Capped at twice gravity: lift never throws it up.)
    const a = Math.max(-2 * G, Math.min(2 * G, L));
    for (let i = 0; i < 3; i++) dv[i] += up[i] * a * h;
    // A spinning disc holds its tilt (only its spin about its up stays);
    // as the spin dies it banks (fades).
    if (mat.gyro) {
      const s = w[0] * up[0] + w[1] * up[1] + w[2] * up[2];
      const keep = Math.exp(-mat.gyro * Math.min(1, Math.abs(s) / 8) * h);
      for (let i = 0; i < 3; i++) w[i] = up[i] * s + (w[i] - up[i] * s) * keep;
      if (mat.fade) {
        const dir = [v[0] / sp, v[1] / sp, v[2] / sp];
        const bank = (mat.fade * Math.sign(s || 1)) / (1 + Math.abs(s) / 4);
        for (let i = 0; i < 3; i++) w[i] += dir[i] * bank * h;
      }
    }
  }
  if (mat.nose && !touching) {
    // A weathervane: the nose turns into its flight (a shuttlecock flips
    // cork first), more strongly the faster it goes; only in the air (on
    // the ground it would flip over and over as it slides).
    const n = rotate(b.q, mat.nose);
    const d = [v[0] / sp, v[1] / sp, v[2] / sp];
    const t = [n[1] * d[2] - n[2] * d[1], n[2] * d[0] - n[0] * d[2], n[0] * d[1] - n[1] * d[0]];
    // Its swing round is damped near critically (the air's damping grows
    // with the vane's pull), so it turns nose first without swinging past
    // over and over; its spin about the nose itself lasts. The pull grows
    // with the speed squared (full at a brisk 2 toy radii per second), as
    // the air's does, so a slow hop after a landing barely turns it.
    const k = (mat.vane ?? 10) * 20 * Math.min(1, (sp / (2 * R)) ** 2);
    const s = n[0] * w[0] + n[1] * w[1] + n[2] * w[2];
    const keep = Math.exp(-1.6 * Math.sqrt(k) * h);
    const axial = Math.exp(-Math.min(1, sp / (0.5 * R)) * h);
    for (let i = 0; i < 3; i++) w[i] = n[i] * s * axial + (w[i] - n[i] * s + t[i] * k * h) * keep;
  }
  for (let i = 0; i < 3; i++) v[i] += dv[i];
}

// A light ball drifts on the air as it falls: a slow, wandering sideways
// push (what a breath of wind and its own wake do to a beach ball), as
// strong as `drift` times gravity, while it is off the ground.
export function driftForce(b, mat, G, h) {
  if (b.fixed || b.held || !mat.drift) return;
  const t = (b.driftT = (b.driftT ?? b.id * 1.7) + h);
  const a = mat.drift * G;
  b.vel[0] += a * Math.sin(t * 1.3 + Math.sin(t * 0.47) * 2) * h;
  b.vel[2] += a * Math.cos(t * 0.9 + Math.sin(t * 0.61) * 2) * h;
  // (And it turns lazily as it goes.)
  b.omega[1] += 0.6 * a * Math.sin(t * 0.7) * h;
}

// Rolling resistance on the ground: the roll slows by `roll` times gravity
// (and a sliding puck by its friction alone). `touching` is true while it
// rests on something.
export function rollForce(b, mat, G, h) {
  if (b.fixed || b.held || !mat.roll) return;
  // A twist on the spot (spin about the floor's normal) is stopped by the
  // friction across the small patch it rests on: a steady slowing,
  // friction x gravity x the patch's radius (a tenth of the ball's) over
  // the ball's inertia (a hollow ball: 2/3 of r^2), so a basketball spun on
  // the floor stops within a second or two. (Rolling friction alone never
  // touched it, and a ball left twisting never slept.)
  const r = b.solid?.r ?? b.bound ?? 1;
  const twist = Math.min(Math.abs(b.omega[1]), ((mat.friction * G * 0.1 * r) / ((2 / 3) * r * r)) * h); // prettier-ignore
  b.omega[1] -= Math.sign(b.omega[1]) * twist;
  const v = b.vel;
  const hs = Math.hypot(v[0], v[2]);
  if (hs < 1e-6) return;
  const dec = Math.min(hs, mat.roll * G * h);
  v[0] -= (v[0] / hs) * dec;
  v[2] -= (v[2] / hs) * dec;
  // The spin about the upright dies on the ground slowly (a ball spinning on
  // the spot); its rolling follows the contact's friction.
  const s = 1 - Math.min(1, mat.roll * 2 * h);
  b.omega[0] *= s;
  b.omega[2] *= s;
}

// The spin a throw gives: what the hand gives where it holds the ball (r,
// the hold point's offset in the world) moving at v, scaled by `spin`; a
// football spirals about its long axis, a rugby ball tumbles end over end,
// a bowling ball hooks.
export function throwSpin(mat, r, v, longAxis) {
  const r2 = r[0] * r[0] + r[1] * r[1] + r[2] * r[2];
  if (r2 < 1e-12) return [0, 0, 0];
  const c = [r[1] * v[2] - r[2] * v[1], r[2] * v[0] - r[0] * v[2], r[0] * v[1] - r[1] * v[0]];
  const out = c.map((x) => (x * mat.spin) / r2);
  const sp = Math.hypot(v[0], v[1], v[2]);
  if (mat.spiral && longAxis && sp > 1e-6) {
    const s = Math.sign(longAxis[0] * v[0] + longAxis[1] * v[1] + longAxis[2] * v[2]) || 1;
    for (let i = 0; i < 3; i++) out[i] += longAxis[i] * s * mat.spiral;
  }
  if (mat.tumble && sp > 1e-6) {
    const t = [-v[2] / sp, 0, v[0] / sp];
    for (let i = 0; i < 3; i++) out[i] += t[i] * mat.tumble;
  }
  if (mat.hook && sp > 1e-6) out[1] += mat.hook * 4 * (Math.sign(c[1]) || 1);
  return out;
}

function rotate(q, v) {
  const [x, y, z, w] = q;
  const cx = y * v[2] - z * v[1] + w * v[0];
  const cy = z * v[0] - x * v[2] + w * v[1];
  const cz = x * v[1] - y * v[0] + w * v[2];
  return [v[0] + 2 * (y * cz - z * cy), v[1] + 2 * (z * cx - x * cz), v[2] + 2 * (x * cy - y * cx)];
}

src/physics/fields.js:
// Fields and bodies for Hands-on (lane Hands engine A): a water line toys
// float on, buoyancy in air, gravity wells, wheels that roll, shake
// detection, fish that flee the finger (or eyes that follow it) and
// projectiles that stick in targets; with the per-toy materials of
// ./materials.js. Pure JavaScript, no DOM (the water's surface is drawn by
// ./water-view.js, loaded only when a toy has one).
//
// A recipe asks for these in its `hands` block (docs/PACKS.md, "Hands-on:
// bodies and fields"); toys that ask for none play exactly as before:
//
// - material: "basketball" | { ...keys } (./materials.js)
// - water: { density, level, depth, drag, size, color } | true
// - air: { hover, spring, drag, floor, upright } | true
// - well: { at: [x, y, z], pull, soft, capture, floor }
// - wheels: { axle: [x, y, z], r, parts: [names], sign, grip, roll }
// - shake: { key, gap } | true
// - strings: { list: [{ a, b, name }], reach, normal } (lane Hands-on H3)
// - flee: { radius, push, back, max } | true; follow: true
// - pieces' own `material`, `projectile: { nose, vane, fr }` and `target`
// - force: (body, h, ctx) => {} each substep, watch: true, and carry:
//   { key: [keys] } (lane Hands-on H4)
//
// src/physics/hands-on.js calls an Extras (made by extrasFor) at a few
// points: attach, the world built, a press, a move, a let-go, each frame
// and each hit; the world calls its force once per substep (World.force).
// What a recipe's drive() reads comes as info.hands (src/motion.js):
// { on, shake, finger, point, rolled, moved, flee(key, pos), piece(key),
// plucked }.

import { quat, v3, surfacePoints } from "./world.js";
import { materialFor, applyMaterial, airForce, rollForce, throwSpin, driftForce } from "./materials.js"; // prettier-ignore

// ---- Water --------------------------------------------------------------

// The part of a ball of radius r under water, its middle `depth` below the
// line (negative: above).
export function sphereSubmerged(depth, r) {
  const d = Math.max(0, Math.min(2 * r, depth + r));
  return (d * d * (3 * r - d)) / (4 * r * r * r);
}

// The part of a body's sample points under water at a line `level` (each
// point counts by how deep it is, within a band, so the change is smooth).
export function pointsSubmerged(b, pts, level, band) {
  let s = 0;
  for (const p of pts) {
    const y = b.pos[1] + quat.rotate(b.q, p)[1];
    s += Math.max(0, Math.min(1, (level - y) / band + 0.5));
  }
  return s / pts.length;
}

// Where the water line must be for a body at rest to float as it is (its
// density, relative to the water's): the level that keeps that part under.
export function restLevel(b, fl, density) {
  const want = Math.max(0.02, Math.min(0.98, density));
  let lo = b.pos[1] - b.bound * 1.5;
  let hi = b.pos[1] + b.bound * 1.5;
  for (let i = 0; i < 40; i++) {
    const mid = (lo + hi) / 2;
    if (submerged(b, fl, mid) < want) lo = mid;
    else hi = mid;
  }
  return (lo + hi) / 2;
}

function submerged(b, fl, level) {
  if (fl.sphere) return sphereSubmerged(level - b.pos[1], fl.sphere);
  return pointsSubmerged(b, fl.points, level, fl.band);
}

// How a body floats: a ball by its radius; anything else by points on its
// outside.
export function floatShape(b, R) {
  if (b.solid?.type === "sphere" && !b.points.length) return { sphere: b.solid.r };
  const pts = b.points.length ? b.points : b.solid ? surfacePoints(b.solid, 1) : [[0, 0, 0]];
  return { points: pts, band: 0.25 * R };
}

// Buoyancy and the water's drag on one body for a substep h. water:
// { level, density, drag, G, R }. The water a body pushes aside moves with
// it (its added mass, half the water it displaces, for a ball), so a light
// ball bobs a few times and settles instead of bouncing on the line. A
// ball is lifted at its middle; anything else at each point under water,
// so a boat rights itself and rocks.
export function waterForce(b, fl, water, h) {
  if (b.fixed || b.held) return 0;
  const { G, density, drag, R } = water;
  if (fl.sphere) {
    const s = sphereSubmerged(water.level - b.pos[1], fl.sphere);
    if (s <= 0) return 0;
    const m = density + 0.5 * s; // the ball and the water moving with it
    const v = b.vel;
    const sp = Math.hypot(v[0], v[1], v[2]);
    // Lift, and drag: quadratic (a ball's, Cd 0.47) and a little linear
    // (the waves it makes), both on the part under water.
    // (The waves a bobbing ball makes take its bob away: the linear part
    // is full strength once it floats as deep as it rests.)
    const wet = Math.min(1, s / Math.max(0.05, density));
    const k = 1 / (1 + ((0.18 * sp) / R) * (s / m) * h + 0.5 * drag * wet * h);
    // (Gravity is the world's; the water's mass moving with it slows the
    // ball's answer to the difference without moving where it rests.)
    b.vel[1] += (G + (G * (s - density)) / m) * h;
    for (let i = 0; i < 3; i++) {
      v[i] *= k;
      b.omega[i] *= Math.exp(-0.5 * drag * wet * h);
    }
    return s;
  }
  const n = fl.points.length;
  const mass = 1 / (b.invMass || 1);
  const sub = [];
  let total = 0;
  for (const p of fl.points) {
    const r = quat.rotate(b.q, p);
    const y = b.pos[1] + r[1];
    const s = Math.max(0, Math.min(1, (water.level - y) / fl.band + 0.5));
    sub.push([r, s]);
    total += s;
  }
  if (total <= 0) return 0;
  const S = total / n;
  const m = density + 0.5 * S;
  const lift = G + (G * (S - density)) / m;
  for (const [r, s] of sub) {
    if (s <= 0) continue;
    const v = b.velAt(r);
    const w = (s / total) * mass * h;
    const d = (drag * S * density) / m;
    // Up, and against the point's motion (the water's drag).
    b.applyVel([-d * v[0] * w, (lift - d * v[1]) * w, -d * v[2] * w], r, 1);
  }
  return total / n;
}

// ---- Air, wells and wheels ---------------------------------------------

// Hot air: lift that fades with height, so the balloon settles at `hover`
// (world y) and floats back there when pulled down or pushed up; its
// basket hangs under it.
export function airBuoyancy(b, air, h) {
  if (b.fixed || b.held) return;
  const G = air.G;
  const a = G + Math.max(-0.6 * G, Math.min(0.6 * G, (air.spring * G * (air.hover - b.pos[1])) / air.R)); // prettier-ignore
  b.vel[1] += a * h;
  const k = Math.exp(-air.drag * h);
  for (let i = 0; i < 3; i++) b.vel[i] *= k;
  if (air.upright) {
    const up = quat.rotate(b.q, [0, 1, 0]);
    const t = v3.cross(up, [0, 1, 0]);
    for (let i = 0; i < 3; i++) b.omega[i] = (b.omega[i] + t[i] * air.upright * h) * Math.exp(-1.5 * h); // prettier-ignore
  }
}

// A pull toward a point instead of the floor: pull is the gravity's
// strength one toy radius away, falling off with the square of the
// distance (softened within `soft`); inside `capture` it is swallowed and
// held there.
export function wellForce(b, well, h) {
  if (b.fixed || b.held) return;
  const d = v3.sub(well.at, b.pos);
  const r2 = v3.dot(d, d);
  const r = Math.sqrt(r2);
  if (well.capture && r < well.capture) {
    b.captured = true;
  }
  if (b.captured) {
    b.pos = b.pos.map((v, i) => v + (well.at[i] - v) * Math.min(1, 8 * h));
    b.vel = [0, 0, 0];
    b.omega = b.omega.map((w) => w * Math.exp(-2 * h));
    return;
  }
  const s2 = well.soft * well.soft;
  const a = (well.pull * well.R * well.R) / (r2 + s2);
  if (r < 1e-9) return;
  for (let i = 0; i < 3; i++) b.vel[i] += (d[i] / r) * a * h;
}

// Wheels on the ground: they roll along their way and grip sideways (a
// car pushed side-on doesn't slide), and slow only by rolling resistance.
// `axle` is the body's local axle; returns nothing.
export function wheelForce(b, wheels, G, h, onGround) {
  if (b.fixed || b.held || !onGround) return;
  const ax = quat.rotate(b.q, wheels.axle);
  const a = v3.norm([ax[0], 0, ax[2]]);
  const v = b.vel;
  const lat = v[0] * a[0] + v[2] * a[2];
  const k = 1 - Math.exp(-wheels.grip * h);
  v[0] -= a[0] * lat * k;
  v[2] -= a[2] * lat * k;
  const hs = Math.hypot(v[0], v[2]);
  if (hs > 1e-9) {
    const dec = Math.min(hs, wheels.roll * G * h);
    v[0] -= (v[0] / hs) * dec;
    v[2] -= (v[2] / hs) * dec;
  }
  // It turns only as its wheels let it (a little, about the upright).
  b.omega[1] *= Math.exp(-wheels.yaw * h);
}

// ---- Shake --------------------------------------------------------------

// A quick back-and-forth drag: each turn of the finger's way (after a
// stroke of at least `min` CSS pixels, quicker than `slow` seconds) adds to
// the level; two turns close together fire the toy's shake.
export class ShakeMeter {
  constructor(o = {}) {
    this.min = o.min ?? 14;
    this.slow = o.slow ?? 0.4;
    this.gap = o.gap ?? 0.5;
    this.level = 0;
    this.last = null; // { t, x, y }
    this.dir = null; // [dx, dy] of the stroke so far
    this.from = null; // { t, x, y }: where the stroke began
    this.turns = []; // times of turns
    this.fired = -Infinity;
    this.t = 0;
  }

  // The finger at (x, y) at time t. Returns true when the shake fires.
  add(t, x, y) {
    this.decay(t);
    const last = this.last;
    this.last = { t, x, y };
    if (!last) {
      this.from = { t, x, y };
      return false;
    }
    const d = [x - last.x, y - last.y];
    if (Math.hypot(d[0], d[1]) < 1.5) return false;
    if (this.dir && d[0] * this.dir[0] + d[1] * this.dir[1] < 0) {
      // A turn: was the stroke before it long and quick enough?
      const len = Math.hypot(last.x - this.from.x, last.y - this.from.y);
      const quick = t - this.from.t < this.slow;
      this.from = { t: last.t, x: last.x, y: last.y };
      this.dir = d;
      if (len >= this.min && quick) {
        this.turns.push(t);
        this.level = Math.min(1, this.level + 0.22 + Math.min(0.2, len / 400));
        this.turns = this.turns.filter((s) => t - s < 0.9);
        if (this.turns.length >= 2 && t - this.fired > this.gap) {
          this.fired = t;
          return true;
        }
      }
      return false;
    }
    this.dir = this.dir ? [this.dir[0] * 0.5 + d[0], this.dir[1] * 0.5 + d[1]] : d;
    return false;
  }

  decay(t) {
    const dt = Math.max(0, t - this.t);
    this.t = t;
    this.level *= Math.exp(-1.1 * dt);
    return this.level;
  }

  end() {
    this.last = null;
    this.dir = null;
    this.from = null;
  }
}

// ---- Follow and flee ----------------------------------------------------

// Things that dart away from the finger's line (a fish), each on a spring
// back to its place. Items are keyed; flee(key, pos) returns its offset and
// speed (recipe units), worked out each frame by step().
export class FleeField {
  constructor(o = {}) {
    this.radius = o.radius ?? 0.45;
    this.push = o.push ?? 1;
    this.back = o.back ?? 2.2; // the spring's rate (per second)
    this.max = o.max ?? 0.6;
    this.items = new Map();
    this.ray = null; // { origin, dir } in recipe units, or null
  }

  get(key, pos) {
    let it = this.items.get(key);
    if (!it) this.items.set(key, (it = { pos: pos.slice(), d: [0, 0, 0], v: [0, 0, 0] }));
    else it.pos = pos;
    return it;
  }

  // Moves every item on by dt; true while any is still off its place.
  step(dt) {
    const ray = this.ray;
    const k = this.back * this.back;
    const c = 2 * 0.85 * this.back;
    let busy = false;
    const n = Math.max(1, Math.ceil(dt / (1 / 120)));
    const h = Math.min(dt, 0.1) / n;
    for (const it of this.items.values()) {
      for (let s = 0; s < n; s++) {
        const a = [0, 0, 0];
        if (ray) {
          const p = v3.add(it.pos, it.d);
          const rel = v3.sub(p, ray.origin);
          const along = v3.dot(rel, ray.dir);
          const perp = v3.sub(rel, v3.scale(ray.dir, along));
          const dist = v3.len(perp);
          if (dist < this.radius) {
            const f = (1 - dist / this.radius) ** 2 * this.push * 60;
            const dir = dist > 1e-6 ? v3.scale(perp, 1 / dist) : [0, 1, 0];
            for (let i = 0; i < 3; i++) a[i] += dir[i] * f;
          }
        }
        for (let i = 0; i < 3; i++) {
          a[i] += -k * it.d[i] - c * it.v[i];
          it.v[i] += a[i] * h;
          it.d[i] += it.v[i] * h;
        }
        const l = v3.len(it.d);
        if (l > this.max) {
          it.d = v3.scale(it.d, this.max / l);
          const out = v3.dot(it.v, it.d) / this.max;
          if (out > 0) it.v = v3.sub(it.v, v3.scale(it.d, out / this.max));
        }
      }
      if (v3.len(it.d) > 1e-3 || v3.len(it.v) > 1e-2) busy = true;
      else if (!ray) {
        it.d = [0, 0, 0];
        it.v = [0, 0, 0];
      }
    }
    return busy;
  }
}

// ---- The glue to Hands-on -------------------------------------------------

// (touch: lane Hands-on H5; force, watch and carry: lane Hands-on H4;
// strings: lane Hands-on H3)
const KEYS = ["material", "water", "air", "well", "wheels", "shake", "flee", "follow", "touch", "force", "watch", "carry", "strings"]; // prettier-ignore

// An Extras for a toy whose hands block asks for any of these pieces (or
// whose pieces are projectiles, targets or have materials); null else.
export function extrasFor(handsOn, info) {
  const hands = info?.recipe?.hands;
  const motion = handsOn.player?.motion;
  const any = hands && (KEYS.some((k) => hands[k]) || hands.projectiles);
  if (!any) {
    if (motion) motion.hands = null;
    return null;
  }
  const x = new Extras(handsOn, hands);
  if (motion) motion.hands = x.about;
  return x;
}

export class Extras {
  constructor(handsOn, hands) {
    this.ho = handsOn;
    this.hands = hands;
    this.mat = materialFor(hands);
    this.shake = hands.shake ? new ShakeMeter(typeof hands.shake === "object" ? hands.shake : {}) : null; // prettier-ignore
    const fo = hands.flee || hands.follow;
    this.flee = fo ? new FleeField(typeof fo === "object" ? fo : {}) : null;
    this.fingerDown = false;
    this.rolled = 0;
    this.spin = null; // a ball spinning on the fingertip
    this.samples = []; // the finger's recent screen points { t, x, y }
    this.water = null;
    this.view = null; // the water's surface (./water-view.js)
    this.throws = 0;
    // Strings plucked by a drag across them (lane Hands-on H3).
    this.strings = hands.strings ? stringsOf(hands.strings) : null;
    this.strum = null; // a drag across the strings: { last } (the finger's point on them)
    this.pluckT = this.strings ? this.strings.list.map(() => -Infinity) : null;
    // What a recipe's drive() reads, as info.hands.
    const self = this;
    this.about = {
      on: false,
      shake: 0,
      finger: null,
      point: null,
      rolled: 0,
      slosh: [0, 0, 0],
      plucked: this.strings ? this.strings.list.map(() => Infinity) : [], // seconds since each string was plucked
      // Lane Hands-on H2: whether anything is off home (or on its way back),
      // so a drive can show what Hands-on uncovered (a kiwi half's face).
      get moved() {
        return !!(self.ho.moved || self.ho.homing);
      },
      flee(key, pos) {
        if (!self.flee) return { offset: [0, 0, 0], vel: [0, 0, 0] };
        const it = self.flee.get(key, pos);
        return { offset: it.d, vel: it.v };
      },
      // Lane Hands-on H5 (`hands.touch`): the finger, for a drive. `pressed`
      // while a finger is down on the toy (a press, a push or a hold), `held`
      // while it (or a piece) is up in the hand, `speed` how fast the whole
      // toy (or the held piece) moves, in toy radii per second, `joint(name)`
      // a joint's value (null without one) and `piece(i)` where piece i is.
      pressed: false,
      get held() {
        return !!self.ho.hold;
      },
      get speed() {
        const ho = self.ho;
        const b = ho.hold?.body || (ho.mode === "toy" ? ho.body : null);
        return b && ho.world ? v3.len(b.vel) / ho.R() : 0;
      },
      joint(name) {
        const j = self.ho.joints?.byName?.get(name);
        return j && Number.isFinite(j.v) ? j.v : null;
      },
      // Where a piece is, by its number (lane Hands-on H5), its part name
      // (lane Hands-on H2), token or `name` (lane Hands-on H4): see
      // pieceState().
      piece(key) {
        return self.pieceState(key);
      },
    };
  }

  get player() {
    return this.ho.player;
  }

  // The world is built: the materials go on, and the fields join in.
  build(w) {
    const ho = this.ho;
    const hands = this.hands;
    const R = ho.R();
    const G = Math.abs(w.gravity[1]) || 26 * R;
    this.G = G;
    const bodies = ho.mode === "toy" ? [ho.body] : ho.pieces.map((p) => p.body);
    const floor = w.planes[0];
    this.mats = new Map();
    if (ho.mode === "toy" && this.mat) {
      applyMaterial(ho.body, this.mat, floor);
      this.mats.set(ho.body, this.mat);
      // The floor's own friction, when the recipe says (ice for a puck).
      if (hands.friction != null) floor.friction = hands.friction;
    }
    if (ho.mode === "pieces")
      for (const pc of ho.pieces) {
        const m = pc.def.material ? materialFor({ material: pc.def.material }) : null;
        const pr = pc.def.projectile;
        if (m) {
          applyMaterial(pc.body, m, null);
          this.mats.set(pc.body, m);
        } else if (pr) {
          // A projectile flies nose first and sticks in a target.
          const pm = { fr: pr.fr ?? 200, nose: pr.nose || [0, 0, 1], vane: pr.vane ?? 20, roll: 0 };
          this.mats.set(pc.body, pm);
        }
        if (pr) pc.body.projectile = pr;
        if (pc.def.target) pc.body.target = true;
      }
    // The water line: where the toy at home floats as it stands, unless the
    // recipe says.
    if (hands.water) {
      const wo = typeof hands.water === "object" ? hands.water : {};
      const density = wo.density ?? (this.mat ? densityOf(this.mat) : 0.5);
      const b0 = bodies[0];
      this.floats = new Map(bodies.map((b) => [b, floatShape(b, R)]));
      const ref = ho.mode === "toy" ? b0.home.pos[1] : 0;
      const level = wo.level != null ? ref + wo.level * R : restLevel(b0, this.floats.get(b0), density); // prettier-ignore
      this.water = { level, density, drag: wo.drag ?? 6, G, R, size: (wo.size ?? 3.2) * R, color: wo.color }; // prettier-ignore
      // The pool's floor, below the line.
      floor.d = Math.min(floor.d, level - (wo.depth ?? 2.2) * R);
      floor.restitution = 0.1;
    }
    if (hands.air) {
      const ao = typeof hands.air === "object" ? hands.air : {};
      const b0 = bodies[0];
      this.air = { hover: (ho.mode === "toy" ? b0.home.pos[1] : 0) + (ao.hover ?? 0) * R, spring: ao.spring ?? 0.3, drag: ao.drag ?? 3.2, upright: ao.upright ?? 6, G, R }; // prettier-ignore
      floor.d -= (ao.floor ?? 1.5) * R;
    }
    if (hands.well) {
      const wo = hands.well;
      const at = wo.at ? (ho.mode === "toy" ? this.player.fromRecipe(wo.at) : wo.at.slice()) : bodies[0].home.pos.slice(); // prettier-ignore
      this.well = { at, pull: (wo.pull ?? 1) * G, soft: (wo.soft ?? 0.3) * R, capture: (wo.capture ?? 0) * R, R }; // prettier-ignore
      w.gravity = [0, 0, 0];
      // (No air in space: an orbit keeps its speed.)
      for (const b of bodies) b.damping = 0;
      // Nothing to fall onto: only the walls hold it in.
      if (wo.floor !== true) w.planes = w.planes.filter((p) => Math.abs(p.n[1]) < 0.5);
    }
    if (hands.wheels && ho.mode === "toy") {
      const wh = hands.wheels;
      const b = ho.body;
      // The axle and the wheels' radius, from the recipe's units to the
      // world's (the toy is home now).
      const o = this.player.fromRecipe([0, 0, 0]);
      const ax = v3.sub(this.player.fromRecipe(wh.axle || [0, 0, 1]), o);
      const unit = v3.len(ax) || 1;
      this.wheels = { axle: quat.rotate(quat.conj(b.q), v3.scale(ax, 1 / unit)), r: (wh.r ?? 0.15) * unit, parts: wh.parts || [], sign: wh.sign ?? 1, grip: wh.grip ?? 14, roll: wh.roll ?? 0.015, yaw: wh.yaw ?? 6 }; // prettier-ignore
      // The wheels roll; the body itself barely slides.
      b.friction = 0.002;
      // (A car coasts to a stop on its wheels: the world's calming of slow
      // resting bodies would stop it short.)
      b.coasts = true;
      b.damping = 0.02;
      this.lastPos = b.pos.slice();
      // Room to roll: the walls of the play area move out to `area` toy
      // radii from home (the view drifts after it).
      const A = (wh.area ?? 2.4) * R;
      const c = b.home.pos;
      for (const p of w.planes) if (Math.abs(p.n[1]) < 0.5) p.d = v3.dot(p.n, c) - A;
    } else if (hands.area != null && ho.mode === "toy") {
      // Room for a whole toy to roll or slide (a ball, a puck): the walls
      // move out to `area` toy radii from home, as for wheels.
      const A = hands.area * R;
      const c = ho.body.home.pos;
      for (const p of w.planes) if (Math.abs(p.n[1]) < 0.5) p.d = v3.dot(p.n, c) - A;
    }
    if (
      this.mats.size ||
      this.water ||
      this.air ||
      this.well ||
      this.wheels ||
      hands.force ||
      hands.carry ||
      ho.pieces.some((p) => p.body.projectile)
    )
      // prettier-ignore
      w.force = (h) => this.force(w, h);
  }

  // Once per substep, before the world moves anything.
  force(w, h) {
    const ho = this.ho;
    const bodies = ho.mode === "toy" ? [ho.body] : ho.pieces.map((p) => p.body);
    const G = this.G;
    const R = ho.R();
    if (this.hands.carry) this.carryStep();
    for (const b of bodies) {
      if (b.stuck) {
        if (b.held) {
          b.invMass = b.invMassFree ?? b.invMass;
          b.invI = (b.invIFree ?? b.invI).slice();
          b.stuck = false;
        } else continue;
      }
      if (b.held) b.captured = false;
      const touching = b.touchTick >= w.tick - 1;
      const m = this.mats.get(b);
      if (m) {
        // (Drag, lift and spin in the air, not under water.)
        const wet = this.water && b.pos[1] - b.bound < this.water.level;
        if (!wet) airForce(b, m, G, R, h, touching);
        if (!wet && !touching) driftForce(b, m, G, h);
        if (touching && m.roll != null) rollForce(b, m, G, h);
      }
      if (this.water) waterForce(b, this.floats.get(b), this.water, h);
      if (this.air) airBuoyancy(b, this.air, h);
      if (this.well) wellForce(b, this.well, h);
      if (this.wheels) wheelForce(b, this.wheels, G, h, touching);
      // Lane Hands-on H4: the recipe's own push (a flying saucer's beam).
      if (this.hands.force) this.hands.force(b, h, this.forceCtx(b, G, R));
    }
  }

  // What a recipe's `hands.force(body, h, ctx)` gets with each body: the
  // piece it is (its def, part and token; null for a whole toy), the toy's
  // eased controls, the build's data, gravity and a toy radius, whether
  // the body touched anything in the last step, and free() to let a piece
  // that is resting at home go.
  forceCtx(b, G, R) {
    const ho = this.ho;
    const w = ho.world;
    const pc = ho.mode === "pieces" ? ho.pieces.find((p) => p.body === b) || null : null;
    return { piece: pc, c: this.player.motion?.state || {}, data: this.player.proc?.ctx?.kit?.data, G, R, touching: !!w && b.touchTick >= w.tick - 1, free: () => ho.free(b) }; // prettier-ignore
  }

  // Lane Hands-on H4: `hands.carry` ({ key: [keys] }, by part name or
  // token): while the piece `key` is held, the others come loose and go with
  // it as they were built beside it (Galileo's two balls in one hand); let
  // go, they fly on with its speed and then each goes its own way.
  carryStep() {
    const ho = this.ho;
    const find = (k) => ho.pieces.find((p) => p.part === k || (p.token !== undefined && p.token === k)); // prettier-ignore
    for (const [key, list] of Object.entries(this.hands.carry)) {
      const pc = find(isNaN(key) ? key : Number(key)) || find(key);
      if (!pc?.body.held) continue;
      const b = pc.body;
      // Only its turn about the upright: they stay side by side, level,
      // however the held one swings in the hand.
      const f = quat.rotate(quat.mul(b.q, quat.conj(pc.home.q)), [1, 0, 0]);
      const dq = quat.axisAngle([0, 1, 0], Math.atan2(-f[2], f[0]));
      for (const k2 of list) {
        const o = find(k2);
        if (!o || o === pc || o.body.held) continue;
        const b2 = o.body;
        if (b2.pinned) ho.free(b2);
        b2.pos = v3.add(b.pos, quat.rotate(dq, v3.sub(o.home.pos, pc.home.pos)));
        b2.q = quat.norm(quat.mul(dq, o.home.q));
        b2.prevPos = b2.pos.slice();
        b2.prevQ = b2.q.slice();
        b2.vel = b.vel.slice();
        b2.omega = [0, 0, 0];
        b2.carriedBy = b;
      }
    }
  }

  // Where a piece is, for a drive (info.hands.piece): by its number in
  // `hands.pieces` (lane Hands-on H5), or by its part name, token or `name`
  // (lane Hands-on H4; a piece with no part of its own, drawn by the drive).
  // { pos, vel, quat (its turn in the world), turn (its turn from home),
  // home, held, pinned (resting at home), off (picked up or knocked loose,
  // = !pinned) }, recipe units in pieces mode; null before the world is
  // built or for a piece it doesn't have.
  pieceState(key) {
    const ho = this.ho;
    if (!ho.world || !ho.pieces) return null;
    const pc = typeof key === "number" ? ho.pieces[key] : ho.pieces.find((p) => p.part === key || p.def?.name === key || (p.token !== undefined && p.token === key)); // prettier-ignore
    if (!pc) return null;
    const b = pc.body;
    const turn = quat.mul(b.q, quat.conj(pc.home.q));
    return { pos: b.pos.slice(), vel: b.vel.slice(), quat: b.q.slice(), turn, home: pc.home.pos.slice(), held: !!b.held, pinned: !!b.pinned, off: !b.pinned }; // prettier-ignore
  }

  // ---- The finger ----

  // A press: a toy that flees (or follows) the finger takes the drag.
  pressAt(hit, x, y) {
    this.samples = [{ t: this.ho.time, x, y }];
    this.spin = null;
    if (this.hands.touch) this.touched(); // lane Hands-on H5
    if (this.strings && this.strumAt(x, y)) return true;
    if (!this.flee) return false;
    // Lane Hands-on H5: `at(p)` (recipe units) limits where a press is
    // followed (an owl's head); a press elsewhere picks the toy up as usual.
    const fo = this.hands.flee || this.hands.follow;
    if (typeof fo === "object" && fo.at && !fo.at(this.player.toRecipe(hit))) return false;
    this.fingerDown = true;
    this.fingerAt(x, y);
    return true;
  }

  moveTo(x, y) {
    const t = this.ho.time;
    if (this.strum) {
      this.strumTo(x, y);
      return true;
    }
    this.samples.push({ t, x, y });
    while (this.samples.length > 2 && this.samples[0].t < t - 0.2) this.samples.shift();
    if (this.shake && this.shake.add(t, x, y)) this.fireShake();
    if (this.flee && this.fingerDown) {
      this.fingerAt(x, y);
      return true;
    }
    // Wheels: a drag on the toy pushes it along (never lifts it). With
    // `lift` (lane Hands-on H4), a drag that starts straight up the screen
    // picks it up instead, as any toy is.
    const pr = this.ho.press;
    if (this.hands.wheels && pr && !this.ho.hold && this.ho.mode !== "pieces") {
      if (this.hands.wheels.lift) {
        const dx = x - pr.x;
        const dy = pr.y - y;
        if (pr.up === undefined && Math.hypot(dx, dy) >= 7) pr.up = dy > 1.2 * Math.abs(dx);
        if (pr.up) return false;
      }
      this.ho.pushTo(pr, x, y);
      return true;
    }
    return false;
  }

  // Lets go; true when the drag was ours.
  release() {
    if (this.strum) {
      this.strum = null;
      return true;
    }
    this.shake?.end();
    this.about.pressed = false; // lane Hands-on H5
    if (this.flee && this.fingerDown) {
      this.fingerDown = false;
      this.flee.ray = null;
      this.about.finger = null;
      this.about.point = null;
      return true;
    }
    return false;
  }

  // ---- Strings (lane Hands-on H3) ----

  // Where the finger's line meets the strings' plane, or null.
  strumPoint(x, y) {
    const S = this.strings;
    // (In the recipe's frame, which follows a toy picked up and set down
    // elsewhere: it still plucks where it lies.)
    const ray = this.player.recipeRay(x, y);
    const den = v3.dot(ray.dir, S.n);
    if (Math.abs(den) < 1e-4) return null;
    const t = v3.dot(v3.sub(S.list[0].a, ray.origin), S.n) / den;
    return t < 0 ? null : v3.add(ray.origin, v3.scale(ray.dir, t));
  }

  // A press within reach of a string starts a strum (the toy isn't picked
  // up); anywhere else on the toy picks it up as before.
  strumAt(x, y) {
    if (this.ho.mode === "toy") this.ho.ensure();
    const p = this.strumPoint(x, y);
    if (!p) return false;
    const S = this.strings;
    const near = S.list.some((s) => {
      const q = v3.sub(p, s.a);
      const al = v3.dot(q, s.u) / s.L;
      return al > -0.02 && al < 1.02 && Math.abs(v3.dot(q, s.m)) < S.reach;
    });
    if (!near) return false;
    this.strum = { last: p, t: this.ho.time };
    return true;
  }

  // The finger moves on: each string it crossed (within its length) is
  // plucked, sounding by the recipe's hands.sound(hit) with hit.pluck its
  // index, and info.hands.plucked[i] starts again from 0.
  strumTo(x, y) {
    const p = this.strumPoint(x, y);
    if (!p) return;
    const st = this.strum;
    const t = this.ho.time;
    const p0 = st.last;
    const speed = v3.len(v3.sub(p, p0)) / Math.max(1 / 120, t - st.t) / this.ho.R();
    this.strings.list.forEach((s, i) => {
      const s0 = v3.dot(v3.sub(p0, s.a), s.m);
      const s1 = v3.dot(v3.sub(p, s.a), s.m);
      if (s0 === s1 || Math.sign(s0) === Math.sign(s1)) return;
      const q = v3.add(p0, v3.scale(v3.sub(p, p0), s0 / (s0 - s1)));
      const al = v3.dot(v3.sub(q, s.a), s.u) / s.L;
      if (al < -0.02 || al > 1.02) return;
      this.pluckT[i] = t;
      this.about.plucked[i] = 0;
      this.ho.sounds.push({ speed, soft: 0, piece: false, pluck: i, name: s.name ?? null, point: q }); // prettier-ignore
    });
    st.last = p;
    st.t = t;
    this.player.stage?.requestRender();
  }

  fingerAt(x, y) {
    const ray = this.player.recipeRay(x, y);
    this.flee.ray = ray;
    this.about.finger = ray;
    // The point on the finger's line nearest the toy's middle.
    const c = this.hands.flee?.center || this.hands.follow?.center || [0, 0, 0];
    const t = v3.dot(v3.sub(c, ray.origin), ray.dir);
    this.about.point = v3.add(ray.origin, v3.scale(ray.dir, t));
  }

  // A thrown body: the material's weight, spin and drag.
  thrown(h) {
    const b = h.body;
    // What it carried flies on with it (lane Hands-on H4).
    if (this.hands.carry)
      for (const pc of this.ho.pieces)
        if (pc.body.carriedBy === b) {
          pc.body.vel = b.vel.slice();
          pc.body.damping = b.damping; // the same air on both
          pc.body.carriedBy = null;
        }
    const m = this.mats?.get(b);
    if (!m) return;
    b.damping = 0.02;
    if (h.place) return;
    b.vel = v3.scale(b.vel, m.throwScale ?? 1);
    if (this.spin) {
      // Off the fingertip it keeps spinning about the upright.
      b.omega = [this.spin.tilt[0], this.spin.rate, this.spin.tilt[2]];
      this.spin = null;
      return;
    }
    const r = v3.sub(b.toWorld(h.joint.la), b.pos);
    const long = m.spiral ? longAxis(b) : null;
    b.omega = throwSpin(m, r, b.vel, long);
    const ws = v3.len(b.omega);
    if (ws > 24) b.omega = v3.scale(b.omega, 24 / ws);
    // A squash ball warms up: livelier with every throw.
    if (m.warm) {
      this.throws++;
      const [a, top] = m.warm;
      const e = Math.min(top, a + ((top - a) * this.throws) / 6);
      b.restitution = e;
      if (this.ho.world?.planes[0]) this.ho.world.planes[0].restitution = e;
    }
  }

  // A hit: a projectile sticks in a target.
  onHit(hit) {
    const a = hit.body;
    const o = hit.other;
    const R = this.ho.R();
    if (!a || !o || hit.speed < 0.8 * R) return;
    const p = a.projectile ? a : o.projectile ? o : null;
    const t = p === a ? o : a;
    if (!p || !t?.target || p.held || p.projectile.stick === false) return;
    p.stuck = true;
    p.vel = [0, 0, 0];
    p.omega = [0, 0, 0];
    p.invMassFree ??= p.invMass;
    p.invIFree ??= p.invI.slice();
    p.invMass = 0;
    p.invI = [0, 0, 0];
  }

  // Lane Hands-on H5: a press on a toy with `hands.touch` (info.hands.pressed).
  // With `key`, a press held `after` seconds (0.15), or one that becomes a
  // push or a pick-up, fires that action too (a poke), at most every `gap`
  // seconds (0.5); a quick tap is left to the toy's own tap.
  touched() {
    this.about.pressed = true;
    this.touchT = this.ho.time;
    this.touchFired = false;
  }

  touchStep() {
    const t = this.hands.touch;
    const ho = this.ho;
    if (!this.about.pressed || this.touchFired || typeof t !== "object" || !t.key) return;
    if (ho.time - this.touchT < (t.after ?? 0.15) && !ho.hold && !ho.press?.local) return;
    this.touchFired = true;
    if (ho.time - (this.lastTouch ?? -Infinity) < (t.gap ?? 0.5)) return;
    this.lastTouch = ho.time;
    const player = this.player;
    if (!player.motion?.act) return;
    const r = player.motion.act(player.time, null, { key: t.key });
    player.stage?.requestRender?.();
    player.emit?.("action", r);
  }

  fireShake() {
    const player = this.player;
    const s = this.hands.shake;
    // (`fire: false`: the shake only reads as info.hands.shake; lane Hands-on H3.)
    if (typeof s === "object" && s.fire === false) return;
    const key = (typeof s === "object" && s.key) || player.toyInfo?.recipe?.action?.key;
    if (!key || !player.motion?.act) return;
    const r = player.motion.act(player.time, null, { key });
    player.stage?.requestRender?.();
    player.emit?.("action", r);
  }

  // ---- Each frame ----

  // Returns true while anything of ours moves.
  step(dt) {
    const ho = this.ho;
    const ab = this.about;
    ab.on = ho.on;
    let busy = false;
    if (this.shake) {
      ab.shake = this.shake.decay(ho.time);
      if (ab.shake > 0.01) busy = true;
    }
    if (this.strings) {
      this.pluckT.forEach((t0, i) => {
        const age = ho.time - t0;
        ab.plucked[i] = age;
        if (age < 4) busy = true;
      });
      if (this.strum) busy = true;
    }
    if (this.flee) {
      if (this.flee.step(dt)) busy = true;
      if (this.fingerDown) busy = true;
    }
    if (ab.pressed) {
      this.touchStep(); // lane Hands-on H5
      busy = true;
    }
    // A water toy shows its water line as soon as Hands-on is on.
    if (this.hands.water) {
      if (ho.on && !ho.world && ho.player.stage?.toy) ho.ensure();
      this.showWater(ho.on && !!this.water);
    }
    const w = ho.world;
    if (!w) return busy;
    if (this.mat?.fingertip) this.fingertip(dt);
    if (this.wheels && ho.mode === "toy") {
      const b = ho.body;
      const fwd = v3.norm(v3.cross([0, 1, 0], quat.rotate(b.q, this.wheels.axle)));
      const d = v3.sub(b.pos, this.lastPos);
      this.lastPos = b.pos.slice();
      this.rolled += (this.wheels.sign * v3.dot(d, fwd)) / this.wheels.r;
      ab.rolled = this.rolled;
      if (this.wheels.parts.length) {
        let parts = null;
        if (ho.on) {
          parts = {};
          for (const name of this.wheels.parts) parts[name] = { angle: -this.rolled };
        }
        ho.player.motion.handsParts = parts;
      }
    }
    if (this.hands.slosh && ho.mode === "toy") this.sloshStep(dt);
    if (ho.homing) {
      for (const b of ho.mode === "toy" ? [ho.body] : ho.pieces.map((p) => p.body)) {
        b.captured = false;
        if (b.stuck) b.stuck = false;
      }
    }
    return busy;
  }

  // Contents that lag behind the toy as it moves (a snow globe's snow, a
  // glass's water): a damped spring driven by the toy's acceleration, in the
  // toy's own frame and the recipe's units, at most `slosh` from its place
  // and only across (never down through a floor). info.hands.slosh.
  sloshStep(dt) {
    const b = this.ho.body;
    if (!b || dt <= 0) return;
    const v = b.vel.slice();
    const a = this.lastVel ? v3.scale(v3.sub(v, this.lastVel), 1 / dt) : [0, 0, 0];
    this.lastVel = v;
    const tf = this.player.motion?.ctx?.transform;
    const unit = tf?.scale || 1;
    // Into the toy's frame (undoing its turn from home), in recipe units.
    const local = quat.rotate(quat.conj(quat.mul(b.q, quat.conj(b.home.q))), a).map((x) => x / unit); // prettier-ignore
    const st = (this.slosh ||= { x: [0, 0, 0], v: [0, 0, 0] });
    const w = 2 * Math.PI * 1.3;
    const max = this.hands.slosh;
    const h = Math.min(dt, 1 / 30);
    for (const i of [0, 2]) {
      st.v[i] += (-Math.max(-200, Math.min(200, local[i])) - w * w * st.x[i] - 2 * 0.3 * w * st.v[i]) * h; // prettier-ignore
      st.x[i] += st.v[i] * h;
    }
    const l = Math.hypot(st.x[0], st.x[2]);
    if (l > max) {
      st.x[0] *= max / l;
      st.x[2] *= max / l;
      st.v[0] *= 0.5;
      st.v[2] *= 0.5;
    }
    this.about.slosh = [st.x[0], 0, st.x[2]];
  }

  // An upward flick while holding a ball that spins on a fingertip: it
  // hops onto the fingertip and spins there, with a slight wobble.
  fingertip(dt) {
    const h = this.ho.hold;
    if (!h) return;
    const b = h.body;
    const s = this.samples;
    if (!this.spin && s.length >= 2) {
      // The finger's speed over its last moves (about 0.12 s).
      const z = s[s.length - 1];
      let a = s[0];
      for (const e of s)
        if (z.t - e.t <= 0.12 + 1e-6) {
          a = e;
          break;
        }
      const t = z.t - a.t;
      if (t > 0.02) {
        const vy = (a.y - z.y) / t; // up the screen
        const vx = (z.x - a.x) / t;
        if (vy > 500 && vy > 1.5 * Math.abs(vx)) {
          const bottom = b.toLocal(v3.add(b.pos, [0, -(b.solid?.r ?? b.bound), 0]));
          this.spin = { rate: Math.min(22, vy / 70), from: h.joint.la.slice(), to: bottom, t: 0, q: b.q.slice(), tilt: [0, 0, 0] }; // prettier-ignore
        }
      }
    }
    const sp = this.spin;
    if (!sp) return;
    sp.t += dt;
    const e = Math.min(1, sp.t / 0.25);
    const k = e * e * (3 - 2 * e);
    h.joint.la = sp.from.map((v, i) => v + (sp.to[i] - v) * k);
    sp.rate *= Math.exp(-0.12 * dt);
    sp.q = quat.norm(quat.mul(quat.axisAngle([0, 1, 0], sp.rate * dt), sp.q));
    const wob = 0.05 * Math.min(1, sp.t);
    const ta = [Math.cos(sp.t * 2.3), 0, Math.sin(sp.t * 2.3)];
    sp.tilt = v3.scale(ta, wob * 2.3);
    b.holdQ = quat.mul(quat.axisAngle(ta, wob), sp.q);
    b.holdK = 40;
  }

  showWater(on) {
    if (!on) {
      this.view?.hide();
      return;
    }
    if (this.view) {
      this.view.show(this.waterPose());
      return;
    }
    if (this.loadingView) return;
    this.loadingView = true;
    import("./water-view.js")
      .then(({ WaterView }) => {
        this.view = new WaterView(this.player);
        if (this.ho.on && this.water) this.view.show(this.waterPose());
      })
      .catch(() => {});
  }

  // The water's surface in the world: its middle, radius and color.
  waterPose() {
    const ho = this.ho;
    const wt = this.water;
    if (ho.mode === "toy") {
      const c = ho.body.home.pos;
      return { center: [c[0], wt.level, c[2]], radius: wt.size, color: wt.color };
    }
    const p = this.player;
    const c = p.fromRecipe([0, wt.level, 0]);
    const e = p.fromRecipe([wt.size, wt.level, 0]);
    return { center: c, radius: v3.len(v3.sub(e, c)), color: wt.color };
  }

  dispose() {
    this.view?.dispose();
    this.view = null;
  }
}

// A kit toy moved whole by Level 1 (its entity posed: x' = Q (x - c) + c + t)
// still has its parts and tokens turning about where they were built: the
// kit shader turns them in the world, about pivots made for the toy at home
// (where its entity is the identity). This moves those pivots, turns and
// offsets through the same pose, in place, so a tossed car's wheels stay on
// and keep turning. pose: { pivot: c, q: Q, t }.
export function poseKitUniforms(u, pose) {
  const Q = pose.q;
  const Qc = quat.conj(Q);
  const c = pose.pivot;
  const t = pose.t;
  const conj = (q) => quat.mul(quat.mul(Q, q), Qc);
  const parts = u["uSpParts[0]"];
  if (parts)
    for (let o = 0; o + 12 <= parts.length; o += 12) {
      const q = [parts[o], parts[o + 1], parts[o + 2], parts[o + 3]];
      if (q[3] === 0 && q[0] === 0 && q[1] === 0 && q[2] === 0) q[3] = 1;
      const pv = [parts[o + 4], parts[o + 5], parts[o + 6]];
      const ofs = [parts[o + 8], parts[o + 9], parts[o + 10]];
      parts.set(conj(q), o);
      parts.set(v3.add(v3.add(quat.rotate(Q, v3.sub(pv, c)), c), t), o + 4);
      parts.set(quat.rotate(Q, ofs), o + 8);
    }
  const tokens = u["uSpTokens[0]"];
  if (tokens)
    for (let o = 0; o + 8 <= tokens.length; o += 8) {
      const to = [tokens[o], tokens[o + 1], tokens[o + 2]];
      const tq = [tokens[o + 4], tokens[o + 5], tokens[o + 6], tokens[o + 7]];
      if (tq[3] === 0 && tq[0] === 0 && tq[1] === 0 && tq[2] === 0) tq[3] = 1;
      const tw = conj(tq);
      const ct = v3.add(c, t);
      // to' = Q (tq c + to - c) + c + t - tq' (c + t)
      const a = quat.rotate(Q, v3.sub(v3.add(quat.rotate(tq, c), to), c));
      tokens.set(v3.sub(v3.add(a, ct), quat.rotate(tw, ct)), o);
      tokens.set(tw, o + 4);
    }
}

// A material's density relative to water (a ball of its mass and radius).
export function densityOf(m) {
  return m.mass / ((4 / 3) * Math.PI * m.r ** 3 * 1000);
}

// A body's longest local axis, in the world (a football's).
function longAxis(b) {
  const s = b.solid;
  let ax = [1, 0, 0];
  if (s?.type === "ellipsoid") {
    const k = s.r.indexOf(Math.max(...s.r));
    ax = [0, 0, 0];
    ax[k] = 1;
  } else if (b.points.length) {
    let best = 0;
    for (const p of b.points) {
      const l = v3.len(p);
      if (l > best) {
        best = l;
        ax = v3.scale(p, 1 / l);
      }
    }
  }
  return quat.rotate(b.q, ax);
}

// A hands block's strings, ready to pluck (lane Hands-on H3): each string's
// way along (u, its length L) and across it in their plane (m).
function stringsOf(spec) {
  const list0 = Array.isArray(spec) ? spec : spec.list;
  const a0 = list0[0];
  const z = list0[list0.length - 1];
  let n = spec.normal || v3.cross(v3.sub(a0.b, a0.a), v3.sub(z.a, a0.a));
  n = v3.scale(n, 1 / (v3.len(n) || 1));
  const list = list0.map((s) => {
    const d = v3.sub(s.b, s.a);
    const L = v3.len(d) || 1;
    const u = v3.scale(d, 1 / L);
    const m = v3.cross(n, u);
    return { ...s, u, L, m: v3.scale(m, 1 / (v3.len(m) || 1)) };
  });
  return { list, n, reach: spec.reach ?? 0.05 };
}

src/physics/soft.js:
// Soft parts for Hands-on (lane Hands engine C): ropes and chains that hang,
// swing and can be pulled; cloth that hangs, drapes and flutters, pinned at
// its edge; and soft stretch (pull a soft body; let go and it wobbles back).
// Pure JavaScript, no DOM. src/physics/hands-on.js builds it from a recipe's
// `hands` block and steps it with the rigid world (docs/PACKS.md,
// "Hands-on: soft parts", has every key with an example).
//
// - Ropes and cloth are nodes (particles) held by distance links, solved
//   with XPBD in small substeps (as src/physics/world.js does for bodies,
//   with a solver of its own so the rigid world stays as it is). A node is
//   pinned where it was built, rides a piece (an octopus's arm on its body),
//   follows the finger, or hangs free under gravity, air drag and wind.
//   Links can be slack (a rope folds, it doesn't push), resist bending, pull
//   back toward the shape the rope was built in (`keep`: arms that curl
//   back) and snap when stretched too far (`breakAt`: cheese strings).
// - What moves on screen: a node can move a token, and the recipe's splats
//   follow those tokens as skin (kind "skin" between two nodes of a rope,
//   ropeSkin(); kind "skin4" across a cell of cloth, clothSkin()), so a
//   rope bends smoothly and a sheet drapes without seams. Or a rope carries
//   rigid pieces (a token or a part per node or link: a chime, a bead, the
//   yo-yo), each turning with the rope, so solid things stay solid.
// - Stretch drives the toy's grab (the gummy bear's pull: the splats near
//   the finger follow it, fading with distance) from a damped spring, so
//   each soft toy wobbles back at its own pace.
//
// Units are the recipe's (pieces mode in hands-on.js); speeds and forces
// given per toy radius (R) are scaled here.

import { quat, v3 } from "./world.js";

const ID = [0, 0, 0, 1];
const HOME_SECS = 0.45;
const SUBSTEPS = 10;

// Whether a recipe's `hands` asks for soft parts.
export function hasSoft(hands) {
  return !!(hands && (hands.ropes || hands.cloth || hands.stretch));
}

// Stiffness 0..1 as an XPBD compliance (1: rigid; 0: no link at all).
function compliance(k) {
  if (k >= 1) return 0;
  return 1e-7 * Math.pow(10, 5 * (1 - Math.max(0, k)));
}

// The shortest turn taking unit vector a to unit vector b.
function fromTo(a, b) {
  const d = v3.dot(a, b);
  if (d < -0.999999) {
    const ax = Math.abs(a[0]) < 0.9 ? [1, 0, 0] : [0, 1, 0];
    return quat.axisAngle(v3.cross(a, ax), Math.PI);
  }
  const c = v3.cross(a, b);
  return quat.norm([c[0], c[1], c[2], 1 + d]);
}

// A smooth, repeatable flutter in -1..1 (for wind gusts).
function flutter(t, i) {
  return (
    0.55 * Math.sin(t * 7.1 + i * 1.7) +
    0.3 * Math.sin(t * 12.9 + i * 0.6 + 1.3) +
    0.15 * Math.sin(t * 23.3 + i * 2.9)
  );
}

// ---- Skin helpers (for a recipe's build) ------------------------------------

// For splats along a rope: the two nodes a point lies between and how far
// along (kit's `skin: (c) => [a, b, s]`, with `tokens` the rope's tokens).
export function ropeSkin(points, tokens) {
  return (p) => {
    let best = [tokens[0], tokens[0], 0];
    let bd = Infinity;
    for (let i = 0; i + 1 < points.length; i++) {
      const a = points[i];
      const ab = v3.sub(points[i + 1], a);
      const L = v3.dot(ab, ab) || 1e-12;
      const s = Math.max(0, Math.min(1, v3.dot(v3.sub(p, a), ab) / L));
      const d = v3.len(v3.sub(p, v3.add(a, v3.scale(ab, s))));
      if (d < bd - 1e-9) {
        bd = d;
        best = [tokens[i], tokens[i + 1], s];
      }
    }
    return best;
  };
}

// For splats on a sheet: the cell of the cloth's grid a point lies over and
// where in it (kit's `skin: (c) => [a, b, c, d, s, t]`: the cell's corners,
// row by row, and the blend across and down). `points` are the cloth's
// nodes row by row (rows x cols), `tokens` one per node.
export function clothSkin({ rows, cols, points, tokens }) {
  const at = (r, c) => points[r * cols + c];
  return (p) => {
    let best = null;
    let bd = Infinity;
    for (let r = 0; r + 1 < rows; r++)
      for (let c = 0; c + 1 < cols; c++) {
        const o = at(r, c);
        const u = v3.sub(at(r, c + 1), o);
        const v = v3.sub(at(r + 1, c), o);
        // Least squares for p ~ o + s u + t v.
        const d = v3.sub(p, o);
        const uu = v3.dot(u, u);
        const uv = v3.dot(u, v);
        const vv = v3.dot(v, v);
        const du = v3.dot(d, u);
        const dv = v3.dot(d, v);
        const den = uu * vv - uv * uv || 1e-12;
        const s = Math.max(0, Math.min(1, (du * vv - dv * uv) / den));
        const t = Math.max(0, Math.min(1, (dv * uu - du * uv) / den));
        // How far off the cell (bilinear, so a curved sheet fits too).
        const q = v3.add(
          v3.scale(v3.add(v3.scale(o, 1 - s), v3.scale(at(r, c + 1), s)), 1 - t),
          v3.scale(v3.add(v3.scale(at(r + 1, c), 1 - s), v3.scale(at(r + 1, c + 1), s)), t),
        );
        const e = v3.len(v3.sub(p, q));
        if (e < bd - 1e-9) {
          bd = e;
          const k = (rr, cc) => tokens[rr * cols + cc];
          best = [k(r, c), k(r, c + 1), k(r + 1, c), k(r + 1, c + 1), s, t];
        }
      }
    return best;
  };
}

// ---- The soft parts -----------------------------------------------------------

// host: the HandsOn (R(), world, pieces, player).
export class SoftParts {
  constructor(host) {
    this.host = host;
    this.nodes = []; // { x, p, v, w, w0, home, r, strand, lift, ride }
    this.strands = []; // ropes and cloths
    this.stretch = null;
    this.hold = null; // { node } | { stretch }
    this.homing = null;
    this.moved = false;
    this.asleep = true;
    this.still = 0; // seconds everything has been still
    this.t = 0;
    this.events = []; // { speed, snap } for sounds
  }

  // Builds the soft parts a recipe's `hands` names (data: the kit's data).
  build(hands, data, info) {
    const R = this.host.R();
    this.R = R;
    this.gravity = (hands.gravity ?? 26) * R;
    this.floor = (typeof hands.floor === "function" ? hands.floor(data, info) : hands.floor) ?? 0;
    for (const def of hands.ropes?.(data, info) || []) this.addStrand("rope", def);
    for (const def of hands.cloth?.(data, info) || []) this.addStrand("cloth", def);
    const st = typeof hands.stretch === "function" ? hands.stretch(data, info) : hands.stretch;
    if (st) this.stretch = { def: st, pull: [0, 0, 0], vel: [0, 0, 0], on: false };
    return this;
  }

  addStrand(kind, def) {
    const R = this.R;
    const pts = def.points;
    const first = this.nodes.length;
    const n = pts.length;
    const mass = (i) => (Array.isArray(def.mass) ? def.mass[i] : def.mass) ?? 1;
    const s = { kind, def, first, n, links: [], rest: [], scale: 1, pieces: def.pieces || [] };
    s.name = def.name ?? `${kind}${this.strands.length}`;
    for (let i = 0; i < n; i++) {
      const m = mass(i);
      const w = m > 0 ? 1 / m : 0;
      // `home`: as built (the skin's places); `rest`: where it starts and
      // goes back to (def.start, else home).
      const rest = (def.start?.[i] ?? pts[i]).slice();
      this.nodes.push({ x: rest.slice(), p: rest.slice(), v: [0, 0, 0], w, w0: w, home: pts[i].slice(), rest, r: def.radius ?? 0.02 * R, strand: s, i, lift: null, ride: null }); // prettier-ignore
    }
    const N = (i) => this.nodes[first + i];
    for (const [i, a] of def.lift || []) N(i).lift = a.map((v) => v * R);
    // Pinned where built (a rope's first node unless it rides a piece).
    const pins = def.pin ?? (def.attach || kind === "cloth" ? [] : [0]);
    for (const i of pins) N(i).w = N(i).w0 = 0;
    // Riding a piece (or a node of a rope built before it, turning with
    // that rope: a kite's tail): those nodes go where it takes them.
    const on = def.attach?.rope !== undefined ? this.strands[def.attach.rope] : null;
    if (on) {
      const j = def.attach.node ?? on.n - 1;
      const at = this.nodes[on.first + j];
      for (const i of def.attach.nodes ?? [0]) {
        const nd = N(i);
        nd.ride = { strand: on, node: j, local: v3.sub(nd.home, at.home), by: def.attach.turnBy };
        nd.w = nd.w0 = 0;
      }
      s.rides = on;
    } else if (def.attach) {
      const pc = this.host.pieces[def.attach.piece];
      if (pc) {
        const b = pc.body;
        (def.attach.nodes ?? [0]).forEach((i, k) => {
          const nd = N(i);
          // Tied to the node's rest, or to the piece's point `at[k]`.
          const at = def.attach.at?.[k] ?? nd.rest;
          const l = quat.rotate(quat.conj(b.home.q), v3.sub(at, b.home.pos));
          nd.ride = { body: b, local: l };
          nd.w = nd.w0 = 0;
        });
        s.body = b;
      }
    }
    const stiff = compliance(def.stiff ?? 1);
    const slack = def.slack ?? kind === "rope";
    const brk = def.breakAt ?? 0;
    const link = (a, b, c, o = {}) => {
      if (c === null) return;
      const L = v3.len(v3.sub(N(a).home, N(b).home));
      s.links.push({ a: first + a, b: first + b, L, L0: L, c, slack: !!o.slack, brk: o.brk ?? 0, broken: false, main: !!o.main }); // prettier-ignore
    };
    const bendC = (def.bend ?? 0.2) > 0 ? compliance(def.bend ?? 0.2) : null;
    if (kind === "rope") {
      for (let i = 0; i + 1 < n; i++) link(i, i + 1, stiff, { slack, brk, main: true });
      for (let i = 0; i + 2 < n; i++) link(i, i + 2, bendC, { slack: false });
    } else {
      const { rows, cols } = def;
      const id = (r, c) => r * cols + c;
      const shear = (def.shear ?? 0.6) > 0 ? compliance(def.shear ?? 0.6) : null;
      for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++) {
          if (c + 1 < cols) link(id(r, c), id(r, c + 1), stiff, { brk, main: true });
          if (r + 1 < rows) link(id(r, c), id(r + 1, c), stiff, { brk, main: true });
          if (r + 1 < rows && c + 1 < cols) {
            link(id(r, c), id(r + 1, c + 1), shear);
            link(id(r, c + 1), id(r + 1, c), shear);
          }
          if (c + 2 < cols) link(id(r, c), id(r, c + 2), bendC);
          if (r + 2 < rows) link(id(r, c), id(r + 2, c), bendC);
        }
    }
    this.strands.push(s);
    // The parts it carries need their pivots (recipe coordinates).
    for (const pc of s.pieces) if (pc.part && !pc.pivot) pc.pivot = this.partPivot(pc.part);
    return s;
  }

  partPivot(name) {
    const m = this.host.player?.motion;
    const def = (m?.ctx?.parts || []).find((p) => p.name === name);
    const tf = m?.ctx?.transform;
    if (!def) return [0, 0, 0];
    if (!tf) return def.pivot.slice();
    return def.pivot.map((v, i) => v / tf.scale + tf.center[i]);
  }

  get busy() {
    return !!(this.hold || this.homing || !this.asleep);
  }

  // ---- The finger ----

  // The node nearest a recipe point, if within its reach: { node, d } with
  // d in units of that reach (under 1: on it).
  pick(p) {
    let best = null;
    let bd = Infinity;
    for (const nd of this.nodes) {
      const def = nd.strand.def;
      if (def.grab === false || nd.ride || (nd.w0 === 0 && !def.grabPinned)) continue;
      if (Array.isArray(def.grab) && !def.grab.includes(nd.i)) continue;
      const reach = def.pick ?? Math.max(2.5 * nd.r, 0.12 * this.R);
      const d = v3.len(v3.sub(nd.x, p)) / reach;
      if (d < bd) [bd, best] = [d, nd];
    }
    return best ? { node: best, d: bd } : null;
  }

  // Takes a node (from pick) or the stretch (world: the pressed point in
  // the world, for the toy's grab).
  grab(what, world) {
    this.homing = null;
    if (what === "stretch") {
      const st = this.stretch;
      const g = this.driver();
      if (!st || !g) return false;
      const r = (st.def.radius ?? 0.5) * this.host.info.radius;
      st.on = true;
      st.anchor = world.slice();
      st.anchorRecipe = this.host.player.toRecipe(world);
      st.goal = [0, 0, 0];
      st.vel = [0, 0, 0];
      st.pull = [0, 0, 0];
      Object.assign(g, { on: true, held: true, anchor: world.slice(), radius: r, pull: [0, 0, 0], goal: [0, 0, 0] }); // prettier-ignore
      this.hold = { stretch: true };
    } else {
      const nd = what.node;
      nd.w = 0;
      nd.v = [0, 0, 0];
      this.hold = { node: nd, target: nd.x.slice(), from: nd.x.slice() };
    }
    this.moved = true;
    this.asleep = false;
    return true;
  }

  // The finger's point (recipe coordinates).
  drag(p) {
    const h = this.hold;
    if (!h) return;
    if (h.stretch) {
      const st = this.stretch;
      const world = this.host.player.fromRecipe(p);
      let pull = v3.sub(world, st.anchor);
      // A soft cap: it stretches less the further it goes.
      const max = (st.def.max ?? 0.8) * this.host.info.radius;
      const L = v3.len(pull);
      if (L > 1e-9) pull = v3.scale(pull, (max * Math.tanh(L / max)) / L);
      st.goal = pull;
      return;
    }
    // Never further from where the rope is held than the rope reaches (a
    // breakable rope a little past its breaking point).
    const nd = h.node;
    h.target = this.reachable(nd, p);
    // A recipe's `maxPull`: never further than that from where it rests.
    const mp = nd.strand.def.maxPull;
    if (mp) {
      const d = v3.sub(h.target, nd.rest);
      const l = v3.len(d);
      if (l > mp) h.target = v3.add(nd.rest, v3.scale(d, mp / l));
    }
  }

  reachable(nd, p) {
    const s = nd.strand;
    if (s.kind !== "rope") return p;
    const def = s.def;
    // The nearest held node along the rope, toward the start.
    let L = 0;
    let anchor = null;
    for (let i = nd.i - 1; i >= 0; i--) {
      const a = this.nodes[s.first + i];
      const b = this.nodes[s.first + i + 1];
      L += v3.len(v3.sub(a.home, b.home)) * s.scale;
      if (a.w === 0) {
        anchor = a;
        break;
      }
    }
    if (!anchor) return p;
    const over = def.breakAt ? def.breakAt * 1.15 : (def.reach ?? 1.04);
    const d = v3.sub(p, anchor.x);
    const l = v3.len(d);
    return l > L * over ? v3.add(anchor.x, v3.scale(d, (L * over) / l)) : p;
  }

  // Lets go, with the finger's speed (recipe units per second).
  release(vel = [0, 0, 0]) {
    const h = this.hold;
    this.hold = null;
    if (!h) return;
    if (h.stretch) {
      const st = this.stretch;
      const g = this.driver();
      st.on = "spring";
      if (g) g.held = true; // driven from here, not the driver's own spring
      return;
    }
    const nd = h.node;
    nd.w = nd.w0;
    if (nd.w > 0) nd.v = vel.slice();
    this.asleep = false;
  }

  driver() {
    return this.host.player?.driver?.grab ?? null;
  }

  // ↺: everything glides home (and broken links mend).
  reset() {
    if (this.hold) this.release();
    this.stretchHome();
    if (!this.moved) return false;
    this.homing = { el: 0, from: this.nodes.map((nd) => nd.x.slice()) };
    return true;
  }

  stretchHome() {
    const st = this.stretch;
    if (!st?.on) return;
    st.on = false;
    st.pull = [0, 0, 0];
    const g = this.driver();
    if (g) Object.assign(g, { on: false, held: false, pull: [0, 0, 0], goal: [0, 0, 0] });
  }

  // ---- Each step ----

  // Advances by dt (the host's fixed step) at host time `time`. Returns
  // true while anything moves.
  step(dt, time) {
    this.t = time;
    this.pose();
    let busy = this.stepStretch(dt);
    if (this.homing) {
      this.homing.el += dt;
      const f = Math.min(1, this.homing.el / HOME_SECS);
      const e = f * f * (3 - 2 * f);
      this.nodes.forEach((nd, k) => {
        const to = nd.ride ? this.rideAt(nd) : nd.rest;
        nd.x = this.homing.from[k].map((v, i) => v + (to[i] - v) * e);
        nd.p = nd.x.slice();
        nd.v = [0, 0, 0];
      });
      if (f >= 1) {
        this.homing = null;
        this.mend();
        this.moved = this.nodes.some((nd) => nd.ride && v3.len(v3.sub(nd.x, nd.rest)) > 1e-4);
        this.asleep = true;
      }
      return true;
    }
    if (!this.strands.length) return busy;
    // Wake when a piece a rope rides moves.
    const riding = this.strands.some((s) => s.body && !this.host.world?.asleep);
    const wind = this.strands.some((s) => s.def.wind);
    if (this.asleep && !riding && !wind && !this.hold) return busy;
    if (riding || wind) this.moved = true;
    this.asleep = false;
    for (const s of this.strands) s.def.update?.(s, dt, this);
    const h = dt / SUBSTEPS;
    const hold = this.hold?.node ? this.hold : null;
    for (let k = 1; k <= SUBSTEPS; k++) {
      if (hold) {
        const f = k / SUBSTEPS;
        hold.node.x = hold.from.map((v, i) => v + (hold.target[i] - v) * f);
      }
      this.substep(h);
    }
    if (hold) hold.from = hold.target.slice();
    // Asleep after a moment of stillness; home once it is still at home.
    let vmax = 0;
    let off = 0;
    for (const nd of this.nodes) {
      vmax = Math.max(vmax, v3.len(nd.v));
      off = Math.max(off, v3.len(v3.sub(nd.x, nd.rest)));
    }
    this.still = vmax < 0.02 * this.R && !hold && !wind && !riding ? this.still + dt : 0;
    if (this.still > 0.4) {
      this.asleep = true;
      if (off < 0.01 * this.R) {
        for (const nd of this.nodes) {
          nd.x = nd.rest.slice();
          nd.v = [0, 0, 0];
        }
        this.moved = this.strands.some((s) => s.links.some((l) => l.broken));
      }
    }
    return true;
  }

  // The toy's pose: gravity, wind and lift act along the world's own axes
  // even when the toy lies on its side or upside down (`turn`: the world's
  // up taken into recipe coordinates, as a turn from the recipe's own up).
  // The floor holds only while the toy stands upright.
  pose() {
    const p = this.host.player;
    let up = [0, 1, 0];
    if (p?.toRecipe) {
      const a = p.toRecipe([0, 0, 0]);
      up = v3.norm(v3.sub(p.toRecipe([0, 1, 0]), a));
    }
    this.turn = fromTo([0, 1, 0], up);
    this.upright = up[1] > 0.985;
  }

  rideAt(nd) {
    const r = nd.ride;
    if (r.strand) {
      const at = this.nodes[r.strand.first + r.node];
      let q = this.turnAt(r.strand, r.node);
      if (r.by !== undefined) q = quat.slerp(ID, q, r.by);
      return v3.add(at.x, quat.rotate(q, r.local));
    }
    return v3.add(r.body.pos, quat.rotate(r.body.q, r.local));
  }

  // How strand s has turned at node i: the turn of the link from i to `to`
  // (default the next node, or the link before the last node).
  turnAt(s, i, to) {
    const N = (k) => this.nodes[s.first + k];
    const j = to ?? (i + 1 < s.n ? i + 1 : i - 1);
    if (j < 0 || j >= s.n || j === i) return ID;
    const d0 = v3.sub(N(j).home, N(i).home);
    const d1 = v3.sub(N(j).x, N(i).x);
    return fromTo(v3.norm(d0), v3.norm(d1));
  }

  substep(h) {
    const g = this.gravity;
    const R = this.R;
    const t = this.t;
    // Shape memory (`keep`, per second): free nodes are drawn back toward
    // the shape the strand was built in, carried by the piece it rides.
    for (const s of this.strands)
      if (s.def.keep) s.dq = s.body ? quat.mul(s.body.q, quat.conj(s.body.home.q)) : ID;
    for (const nd of this.nodes) {
      nd.p = nd.x.slice();
      if (nd.ride) {
        nd.x = this.rideAt(nd);
        continue;
      }
      if (nd.w === 0) continue;
      const def = nd.strand.def;
      const a = [0, -g * (def.weight ?? 1), 0];
      if (nd.lift) for (let i = 0; i < 3; i++) a[i] += nd.lift[i];
      const turned = !this.upright;
      if (turned) a.splice(0, 3, ...quat.rotate(this.turn, a));
      const keep = def.keep ?? 0;
      if (keep) {
        const b = nd.strand.body;
        const to = b ? v3.add(b.pos, quat.rotate(nd.strand.dq, v3.sub(nd.home, b.home.pos))) : nd.home; // prettier-ignore
        for (let i = 0; i < 3; i++) a[i] += keep * keep * (to[i] - nd.x[i]);
      }
      const wd = def.wind;
      if (wd) {
        // Air moving past: the node is pulled toward the wind's speed, which
        // gusts and flutters along the rope.
        const f = flutter(t, nd.i);
        const W = (wd.vel || [1, 0, 0]).map((v) => v * R * (1 + (wd.gust ?? 0.4) * f));
        const side = wd.flap ?? 0.5;
        W[1] += side * R * flutter(t * 1.3 + 5, nd.i + 3);
        if (turned) W.splice(0, 3, ...quat.rotate(this.turn, W));
        const k = wd.k ?? 3;
        for (let i = 0; i < 3; i++) a[i] += k * (W[i] - nd.v[i]);
      }
      const drag = Math.exp(-(def.drag ?? 1.2) * h);
      for (let i = 0; i < 3; i++) {
        nd.v[i] = (nd.v[i] + a[i] * h) * drag;
        nd.x[i] += nd.v[i] * h;
      }
    }
    const h2 = h * h;
    for (const s of this.strands) {
      for (const l of s.links) {
        if (l.broken) continue;
        const A = this.nodes[l.a];
        const B = this.nodes[l.b];
        const wsum = A.w + B.w;
        if (wsum === 0) continue;
        const d = v3.sub(B.x, A.x);
        const len = v3.len(d);
        if (len < 1e-12) continue;
        const L = l.L * (l.main ? s.scale : 1);
        const C = len - L;
        if (l.slack && C < 0) continue;
        if (l.brk && len > L * l.brk) {
          l.broken = true;
          this.events.push({ snap: true, speed: v3.len(v3.sub(B.v, A.v)) / R, strand: s.name });
          continue;
        }
        const dl = -C / (wsum + l.c / h2);
        const n = v3.scale(d, 1 / len);
        for (let i = 0; i < 3; i++) {
          A.x[i] -= n[i] * dl * A.w;
          B.x[i] += n[i] * dl * B.w;
        }
      }
    }
    // The floor and anything the strand keeps clear of.
    const fl = this.floor;
    for (const nd of this.nodes) {
      if (nd.w === 0) continue;
      const def = nd.strand.def;
      if (this.upright && nd.x[1] < fl + nd.r) {
        const depth = fl + nd.r - nd.x[1];
        nd.x[1] = fl + nd.r;
        // Friction (as in PBD): the slide along the floor this substep is
        // undone up to `friction` times how far the floor pushed it out.
        const fr = (def.friction ?? 0.6) * depth;
        const dx = nd.x[0] - nd.p[0];
        const dz = nd.x[2] - nd.p[2];
        const slide = Math.hypot(dx, dz);
        const k = slide > 1e-12 ? Math.min(1, fr / slide) : 0;
        nd.x[0] -= dx * k;
        nd.x[2] -= dz * k;
      }
      for (const sp of def.avoid || []) {
        const c = sp.piece !== undefined ? this.host.pieces[sp.piece]?.body?.toWorld(sp.at) ?? sp.at : sp.at; // prettier-ignore
        const d = v3.sub(nd.x, c);
        const l = v3.len(d);
        const r = sp.r + nd.r;
        if (l < r && l > 1e-9) nd.x = v3.add(c, v3.scale(d, r / l));
      }
    }
    for (const nd of this.nodes) for (let i = 0; i < 3; i++) nd.v[i] = (nd.x[i] - nd.p[i]) / h;
  }

  // Stretch: held, the pull follows the finger closely; let go, it swings
  // back through rest on a damped spring and settles.
  stepStretch(dt) {
    const st = this.stretch;
    if (!st?.on) return false;
    const g = this.driver();
    if (st.on === true) {
      const k = 1 - Math.exp(-dt / 0.04);
      st.pull = st.pull.map((v, i) => v + (st.goal[i] - v) * k);
    } else {
      const w = 2 * Math.PI * (st.def.hz ?? 3);
      const z = st.def.damping ?? 0.2;
      for (let i = 0; i < 3; i++) {
        st.vel[i] += (-w * w * st.pull[i] - 2 * z * w * st.vel[i]) * dt;
        st.pull[i] += st.vel[i] * dt;
      }
      const R = this.host.info.radius;
      if (v3.len(st.pull) < 0.002 * R && v3.len(st.vel) < 0.02 * R) {
        this.stretchHome();
        return true;
      }
    }
    if (g) {
      g.on = true;
      g.held = true;
      g.pull = st.pull.slice();
      g.goal = st.pull.slice();
    }
    return true;
  }

  mend() {
    for (const s of this.strands) {
      s.scale = 1;
      for (const l of s.links) l.broken = false;
      s.def.reset?.(s, this);
    }
  }

  // ---- Output ----

  // What the soft parts move: tokens ([{ index, token }]) and parts.
  output() {
    if (!this.moved && !this.homing) return null;
    const tokens = [];
    const parts = {};
    // Rigid riders first (a strand's tokens may be in a rider part's frame).
    for (const s of this.strands) {
      for (const pc of s.pieces) {
        const i = pc.from ?? pc.node ?? 0;
        const a = this.nodes[s.first + i];
        let q = pc.turn === false ? ID : this.turnAt(s, i, pc.to);
        if (pc.turnBy !== undefined) q = quat.slerp(ID, q, pc.turnBy);
        const sp = pc.spin?.(s, this);
        if (sp) q = quat.mul(q, quat.axisAngle(pc.axis || [0, 0, 1], sp));
        // The built point that sits on the node (default the node's home).
        const base = pc.at || a.home;
        const to = v3.add(a.x, v3.sub(base, a.home));
        if (pc.token !== undefined) {
          tokens.push({ index: pc.token, token: { base, offset: v3.sub(to, base), quat: q } });
        } else if (pc.part) {
          const pv = pc.pivot;
          const off = v3.sub(v3.sub(to, pv), quat.rotate(q, v3.sub(base, pv)));
          parts[pc.part] = { quat: q, offset: off, pivot: pv };
        }
      }
    }
    for (const s of this.strands) {
      const fr = s.def.frame ? parts[s.def.frame] : null;
      const vis = s.def.visible?.(s, this) ?? 1;
      (s.def.tokens || []).forEach((tk, i) => {
        if (tk === null || tk === undefined) return;
        const nd = this.nodes[s.first + i];
        // In a moving part's frame: where the part's own move would put
        // the node's home, taken back out (the shader moves skin, then part).
        let x = nd.x;
        if (fr) x = v3.add(fr.pivot, quat.rotate(quat.conj(fr.quat), v3.sub(v3.sub(x, fr.offset), fr.pivot))); // prettier-ignore
        tokens.push({ index: tk, token: { base: nd.home, offset: v3.sub(x, nd.home), quat: ID, visible: vis } }); // prettier-ignore
      });
    }
    for (const k in parts) delete parts[k].pivot;
    return { tokens, parts };
  }

  takeEvents() {
    const e = this.events;
    this.events = [];
    return e;
  }

  // For tests and clips.
  state() {
    return {
      moved: this.moved,
      asleep: this.asleep,
      holding: !!this.hold,
      stretch: this.stretch ? { on: this.stretch.on, pull: this.stretch.pull.slice() } : null,
      strands: this.strands.map((s) => ({
        name: s.name,
        kind: s.kind,
        nodes: Array.from({ length: s.n }, (_, i) => this.nodes[s.first + i].x.slice()),
        home: Array.from({ length: s.n }, (_, i) => this.nodes[s.first + i].home.slice()),
        broken: s.links.filter((l) => l.broken).length,
      })),
    };
  }
}

src/physics/joints.js:
// Joints for Hands-on (lane Hands engine B): parts that move the way the
// real thing's parts do, in a recipe's `hands.joints`.
//
// - hinge: a part swings on an axis between two angles, with an optional
//   spring home; it falls by its own weight (a chest lid, a visor).
// - slider: a part moves along one line between two stops (a sword drawn
//   out of a stone, a telescope's tube, a cork).
// - dial: drag to turn a part about its axis, with optional clicks
//   (detents) and coasting after a flick (a crank, a rotor, a key).
// - socket: a loose piece clicks back into its place when brought close
//   (an orange's wedge, a gift box's lid).
// - break: a piece holds fast until pulled hard, then snaps off; ↺ Reset
//   mends it (a candy cane's top, a grape, a petal). With `reseat`, a
//   broken piece brought back clicks into its place, or another seat, and
//   holds fast there again (a cork, a pen's cap; lane Hands-on H3).
// - hands.upright: a whole toy (Level 1) rights itself after a tip (a
//   sailboat, a roly-poly penguin).
//
// Hinges, sliders and dials are driven parts: one number each (an angle or
// a distance), moved by the finger, gravity, a spring and their stops, and
// posed exactly from it, so a part never wobbles off its axis or jitters.
// Loose pieces (sockets, broken-off pieces) are ordinary bodies of the
// world (src/physics/world.js). Everything is solid: parts move whole, and
// ↺ sends each home (a broken one mended). Pure JavaScript, no DOM.
//
// Coordinates are the recipe's own (a kit toy's build space; a scan rig's
// world), as for the rest of Hands-on (src/physics/hands-on.js). docs/PACKS.md,
// "Hands-on: joints", describes every key with an example.

import { Body, boundOf, surfacePoints, quat, v3 } from "./world.js";

const TAU = Math.PI * 2;
const FOLLOW = 16; // per second: how fast a driven part catches the finger
const STILL = 0.02; // a driven part slower than this (per second) can rest
const GLIDE = 0.22; // seconds a piece takes to click into its socket
const ID = [0, 0, 0, 1];

// Transforms x -> q x + t (q a quaternion).
const tf = (q = ID, t = [0, 0, 0]) => ({ q, t });
const tfApply = (T, x) => v3.add(quat.rotate(T.q, x), T.t);
const tfMul = (A, B) => tf(quat.mul(A.q, B.q), v3.add(quat.rotate(A.q, B.t), A.t));
const tfInv = (T) => {
  const qi = quat.conj(T.q);
  return tf(qi, v3.scale(quat.rotate(qi, T.t), -1));
};
const tfDir = (T, d) => quat.rotate(T.q, d);
// A turn of `angle` about the line through p along unit axis a.
const turnAbout = (p, a, angle) => {
  const q = quat.axisAngle(a, angle);
  return tf(q, v3.sub(p, quat.rotate(q, p)));
};
const perp = (v, a) => v3.sub(v, v3.scale(a, v3.dot(v, a)));
const clamp = (x, a, b) => Math.max(a, Math.min(b, x));

// The pieces of a scan's rig (src/rigs.js) as Hands-on pieces, each a body
// of its own (rigid: a hard-edged part moves whole, never bent). names: the
// parts to use (default all); o: { solid (a function of the part's first
// region { at, r } giving a solid), mass, friction, restitution, ... } is
// copied onto every piece. Each piece's middle is its first region's
// center, and it turns about that.
export function rigPieces(rig, names = null, o = {}) {
  const out = [];
  for (const p of rig.parts || []) {
    if (names && !names.includes(p.name)) continue;
    const reg = p.regions?.[0];
    if (!reg) continue;
    const r = Array.isArray(reg.r) ? reg.r : [reg.r, reg.r, reg.r];
    const solid = o.solid ? o.solid(reg, p) : { type: "ellipsoid", r: r.slice() };
    const { solid: _s, ...rest } = o;
    out.push({
      part: p.name,
      pivot: reg.at.slice(),
      pos: reg.at.slice(),
      solid,
      points: surfacePoints(solid, 1),
      pick: r.map((v) => v * 1.1),
      ...rest,
    });
  }
  return out;
}

// The joints of a toy, or null when its recipe has none. Called by Hands-on
// when it builds its world (pieces mode, or Level 1 for `upright`).
export function makeJoints(hands, world) {
  const def = hands.info?.recipe?.hands;
  if (!def?.joints && !def?.upright && !def?.swap) return null;
  return new Joints(hands, world, def);
}

export class Joints {
  constructor(hands, world, def) {
    this.hands = hands;
    this.world = world;
    this.def = def;
    this.events = []; // for tests and clips: { kind, joint, speed, t }
    this.list = [];
    this.byName = new Map();
    this.time = 0;
    if (hands.mode === "toy") {
      this.upright = def.upright
        ? {
            k: def.upright.k ?? def.upright,
            damping: def.upright.damping ?? 3,
            rest: def.upright.rest ?? 0,
          }
        : null; // prettier-ignore (rest: lane Hands-on H5)
      return;
    }
    const data = hands.player.proc?.ctx?.kit?.data;
    const defs = typeof def.joints === "function" ? def.joints(data, hands.info) : def.joints;
    for (const d of defs || []) this.add(d);
    this.link();
    this.refresh();
    // Glued pieces (a piece not yet broken off, and the one it hangs on)
    // never push each other.
    const base = world.pairs;
    world.pairs = (a, b) => (base ? base(a, b) : true) && !this.glued(a, b);
  }

  // ---- Building ----

  add(d) {
    const hands = this.hands;
    const name = d.name ?? d.part ?? (d.token !== undefined ? `token${d.token}` : `j${this.list.length}`); // prettier-ignore
    // The piece it moves: one of the recipe's pieces, else a new one.
    let pc = hands.pieces.find((p) => (d.part !== undefined && p.part === d.part) || (d.token !== undefined && p.token === d.token)); // prettier-ignore
    const driven = d.type === "hinge" || d.type === "slider" || d.type === "dial";
    if (!pc) {
      const pos = (d.pos || d.pivot || [0, 0, 0]).slice();
      const pick = d.pick || [0.3, 0.3, 0.3];
      const solid = d.solid || null;
      const body = this.world.add(new Body({ pos, mass: d.mass ?? 1, solid, points: d.points || (solid ? surfacePoints(solid, 1) : []), friction: d.friction ?? 0.8, restitution: d.restitution ?? 0.15, damping: d.damping ?? 0.3, angDamping: d.angDamping ?? 1.5 })); // prettier-ignore
      body.invMassFree = body.invMass;
      body.invIFree = body.invI.slice();
      body.pinned = true;
      body.invMass = 0;
      body.invI = [0, 0, 0];
      pc = { body, token: d.token, part: d.part, home: { pos: pos.slice(), q: ID.slice() }, def: { pivot: d.pivot, pick, solid } }; // prettier-ignore
      hands.pieces.push(pc);
    }
    const j = { d, name, type: d.type, pc, body: pc.body, v: 0, w: 0, held: null, broken: false, moving: false, parent: null, children: [] }; // prettier-ignore
    if (driven) {
      // A driven part is posed, never pushed: other pieces bump into it.
      j.body.invMass = 0;
      j.body.invI = [0, 0, 0];
      j.body.invMassFree = 0;
      j.body.invIFree = [0, 0, 0];
      j.axis = v3.norm(d.axis || [1, 0, 0]);
      j.pivot = (d.pivot || pc.home.pos).slice();
      j.min = d.min ?? (d.type === "dial" ? -Infinity : 0);
      j.max = d.max ?? (d.type === "dial" ? Infinity : d.type === "hinge" ? Math.PI / 2 : 0.5);
      j.stuck = !!d.stick;
      j.latched = this.atLatch(j); // (lane Hands-on H3: built on its latch)
      j.body.pinned = false; // posed, so always shown where it is
    }
    if (d.type === "socket") j.armed = false;
    if (d.type === "break") j.at = (d.at || pc.home.pos).slice();
    this.list.push(j);
    this.byName.set(name, j);
    if (d.part !== undefined) this.byName.set(d.part, j);
    return j;
  }

  // Where each driven part is now as the recipe shows it (`start`, from
  // its controls: a music box's lid built shut but shown open). Read
  // whenever nothing has been moved by hand.
  refresh() {
    const c = this.hands.player.motion?.state || {};
    for (const j of this.list) {
      if (!j.d.start || j.held || j.v === undefined || j.type === "break" || j.type === "socket") continue; // prettier-ignore
      j.homeV = j.d.start(c, this.hands.info) || 0;
      j.v = j.homeV;
      j.w = 0;
      j.stuck = !!j.d.stick && Math.abs(j.v) < 1e-6;
      j.latched = this.atLatch(j); // (lane Hands-on H3)
      this.pose(j);
    }
  }

  link() {
    if (this.linked) return;
    this.linked = true;
    for (const j of this.list) {
      const to = j.d.parent ?? j.d.to;
      if (to === undefined || to === null) continue;
      const p = this.byName.get(to) || this.pieceJoint(to);
      if (p && p !== j) {
        j.parent = p;
        p.children.push(j);
      }
    }
    this.list.sort((a, b) => depth(a) - depth(b));
  }

  // A plain piece (not one of the joints) named as a parent: a stand-in
  // joint, so a part can hang on a loose piece and ride with it.
  pieceJoint(name) {
    const pc = this.hands.pieces.find((p) => p.part === name || p.token === name || `token${p.token}` === name); // prettier-ignore
    if (!pc) return null;
    const j = { d: {}, name, type: "piece", pc, body: pc.body, children: [], parent: null };
    this.byName.set(name, j);
    return j;
  }

  // ---- Where things are ----

  // The joint's own move (driven parts), in its parent's home frame.
  delta(j) {
    if (j.type === "slider") {
      let T = tf(ID, v3.scale(j.axis, j.v));
      if (j.wig) T = tfMul(T, turnAbout(j.pivot, v3.norm(j.d.wiggle), j.wig));
      return T;
    }
    if (j.type === "hinge" || j.type === "dial") return turnAbout(j.pivot, j.axis, j.v);
    return tf();
  }

  // The move from a joint's home frame to where it is now (its parents'
  // moves and its own).
  full(j) {
    if (j.type === "piece" || (j.type === "break" && !j.broken) || j.type === "socket") {
      // (A reseated piece holds fast at its seat: lane Hands-on H3.)
      const own = j.seatT ? tfMul(j.seatT, j.tug || tf()) : j.tug || tf();
      if (j.type === "break" && !j.broken && j.parent) return tfMul(this.full(j.parent), own);
      if (j.type === "break" && !j.broken) return own;
      const b = j.body;
      const dq = quat.mul(b.q, quat.conj(j.pc.home.q));
      return tf(dq, v3.sub(b.pos, quat.rotate(dq, j.pc.home.pos)));
    }
    const own = this.delta(j);
    return j.parent ? tfMul(this.full(j.parent), own) : own;
  }

  // Puts a posed piece's body where its joint says.
  pose(j) {
    const T = this.full(j);
    const b = j.body;
    b.pos = tfApply(T, j.pc.home.pos);
    b.q = quat.norm(quat.mul(T.q, j.pc.home.q));
    b.prevPos = b.pos.slice();
    b.prevQ = b.q.slice();
  }

  posed(j) {
    if (j.type === "hinge" || j.type === "slider" || j.type === "dial") return true;
    return j.type === "break" && !j.broken;
  }

  glued(a, b) {
    for (const j of this.list) {
      if (j.type !== "break" || j.broken) continue;
      if ((j.body === a || j.body === b) && j.parent && (j.parent.body === a || j.parent.body === b)) return true; // prettier-ignore
    }
    return false;
  }

  joint(body) {
    return this.list.find((j) => j.body === body) || null;
  }

  // ---- The finger ----

  // A press picked `body` at recipe point hit (screen x, y). Returns true
  // when a joint takes the hold (Hands-on then leaves it to us).
  grab(body, hit, x, y) {
    this.link();
    if (!this.hands.moved) this.refresh();
    const j = this.joint(body);
    if (!j) return false;
    if (j.type === "socket") {
      j.armed = false; // it clicks back only once it has been taken out
      j.gliding = null;
      j.inDoor = !!(j.d.out && body.pinned); // lane Hands-on H2: taken from its place
      return false;
    }
    if (j.type === "break" && j.broken) return false;
    if (!this.posed(j)) return false;
    const hands = this.hands;
    const T = this.full(j);
    const local = tfApply(tfInv(T), hit); // the grabbed point, at home
    const h = { body, ctl: j, x0: x, y0: y, travel: 0, trail: [], local, hit: hit.slice(), target: hit.slice() }; // prettier-ignore
    j.held = h;
    j.awake = true;
    j.start = j.v;
    if (j.type === "break") {
      j.pull = 0;
      j.tug = tf();
    }
    hands.hold = h;
    hands.homing = null;
    hands.press = null;
    hands.moved = true;
    this.world.wake();
    this.move(h, hands.ray(x, y));
    return true;
  }

  // The finger moved along `ray` (recipe coordinates). Returns true when
  // the hold is a joint's (the move is ours).
  move(h, ray) {
    const j = h.ctl;
    if (!j) {
      // A loose piece near its socket clicks in as the finger brings it.
      const sj = this.joint(h.body);
      if (sj?.type === "socket") {
        if (this.door(sj, h, ray)) return true; // lane Hands-on H2: still sliding out
        this.nearSocket(sj, h, ray);
      }
      if (sj?.type === "break" && sj.broken && sj.d.reseat) this.nearSeat(sj, h, ray);
      return false;
    }
    if (j.type === "break") {
      this.tugTo(j, h, ray);
      return true;
    }
    const P = j.parent ? this.full(j.parent) : tf();
    const Pi = tfInv(P);
    const o = tfApply(Pi, ray.origin);
    const dir = tfDir(Pi, ray.dir);
    const cur = tfApply(this.delta(j), h.local); // the grabbed point now
    if (j.type === "slider") {
      // The point on the slider's line nearest the finger's ray.
      const a = j.axis;
      const w0 = v3.sub(cur, o);
      const b = v3.dot(a, dir);
      const den = 1 - b * b;
      if (den < 1e-4) return true;
      const s = (b * v3.dot(dir, w0) - v3.dot(a, w0)) / den;
      j.target = j.v + s;
      return true;
    }
    // Hinge and dial: the angle that brings the grabbed point nearest the
    // finger. Across the turning plane unless it is seen almost edge-on (a
    // crank on a box's side: a circle drawn round it still turns it), else
    // on the plane facing the view through the grabbed point.
    const a = j.axis;
    const n = Math.abs(v3.dot(dir, a)) > 0.12 ? a : dir;
    const den = v3.dot(dir, n);
    if (Math.abs(den) < 1e-4) return true;
    const t = v3.dot(v3.sub(cur, o), n) / den;
    if (t <= 0) return true;
    const f = perp(v3.sub(v3.add(o, v3.scale(dir, t)), j.pivot), a);
    const g = perp(v3.sub(h.local, j.pivot), a);
    const lf = v3.len(f);
    const lg = v3.len(g);
    if (lf < 0.15 * lg || lg < 1e-6) return true;
    let ang = Math.atan2(v3.dot(v3.cross(g, f), a), v3.dot(g, f));
    // The same angle, nearest where the part is (a dial turns on and on).
    ang += TAU * Math.round((j.v - ang) / TAU);
    j.target = ang;
    return true;
  }

  // A piece not yet broken off: it bends a little toward the finger, as a
  // whole, about where it is fixed, and snaps off when pulled far enough.
  tugTo(j, h, ray) {
    const R = this.hands.R();
    let T0 = j.parent ? this.full(j.parent) : tf();
    if (j.seatT) T0 = tfMul(T0, j.seatT); // reseated elsewhere (lane Hands-on H3)
    const at = tfApply(T0, j.at);
    const grab = tfApply(T0, h.local);
    // The finger's point, on the plane facing the view through the grab.
    const n = ray.dir;
    const den = v3.dot(ray.dir, n);
    const t = v3.dot(v3.sub(grab, ray.origin), n) / den;
    const f = v3.add(ray.origin, v3.scale(ray.dir, Math.max(t, 0)));
    const pull = v3.sub(f, grab);
    const strength = (j.d.pull ?? 0.35) * R;
    j.pull = v3.len(pull) / strength;
    if (j.pull >= 1) {
      this.snap(j, h, f, ray.dir, ray);
      return;
    }
    // Bend: about `at`, turning the grab toward the finger, up to `give`.
    const arm = v3.sub(grab, at);
    const ax = v3.cross(arm, pull);
    const la = v3.len(ax);
    const give = (j.d.give ?? 0.12) * Math.min(1, j.pull) ** 1.5;
    if (la < 1e-9) {
      j.tug = tf();
      return;
    }
    const axisHome = quat.rotate(quat.conj(T0.q), v3.scale(ax, 1 / la));
    j.tug = turnAbout(j.at, axisHome, give);
    this.world.wake();
  }

  // It snaps off: a loose body now, held by the finger the usual way.
  snap(j, h, f, dir, ray) {
    const hands = this.hands;
    // (Its pose before it is marked broken: bent, and at its seat; lane Hands-on H3.)
    const T = this.full(j);
    j.broken = true;
    j.tug = null;
    const b = j.body;
    // Its pose as it was when it snapped (bent), then free.
    b.pos = tfApply(T, j.pc.home.pos);
    b.q = quat.norm(quat.mul(T.q, j.pc.home.q));
    b.prevPos = b.pos.slice();
    b.prevQ = b.q.slice();
    this.unglue(j);
    hands.free(b);
    b.invMass = b.invMassFree || 1;
    b.invI = (b.invIFree || [1, 1, 1]).slice();
    j.held = null;
    j.armed = false; // (with `reseat`: it clicks back only once taken away)
    b.seated = false;
    this.cue(j, "snap", 1.5);
    // The finger holds it where it grabbed it, as a pick-up does.
    const at = tfApply(T, h.local);
    const w = this.world;
    const joint = w.joint(b, b.toLocal(at), null, at, { compliance: 2e-6, damping: 0 });
    b.held = true;
    // (`steady`: held at its turn, as a piece picked up is, not hanging and
    // swinging from the finger, and carried where the finger holds it (not
    // hovering, as `place` is): a pen's cap carried over its pen to the back
    // end stays clear of the paper and of its place; lane Hands-on H3.)
    b.holdQ = j.d.steady ? b.q.slice() : null;
    if (j.d.steady) b.holdK = 80; // (firm: the finger holds it off its middle)
    b.angDampingFree ??= b.angDamping;
    b.angDamping = j.d.steady ? 7 : 1.2;
    hands.hold = { body: b, joint, place: false, plane: { point: at.slice(), normal: dir.slice() }, target: f.slice(), follow: at.slice(), followV: [0, 0, 0], trail: [], x0: h.x0, y0: h.y0, travel: h.travel, minY: -Infinity, raise: 0 }; // prettier-ignore
    // Lane Hands-on H2: `place: true` holds it as a picked piece is held
    // instead: by its middle, level, hovering over whatever is under the
    // finger (a stone dropped into the half under the finger).
    if (j.d.place && ray) {
      joint.la = [0, 0, 0];
      joint.lb = b.pos.slice();
      const fw = quat.rotate(b.q, [1, 0, 0]);
      b.holdQ = quat.axisAngle([0, 1, 0], Math.atan2(-fw[2], fw[0]));
      b.holdK = 10;
      b.angDamping = 7;
      Object.assign(hands.hold, { place: true, target: b.pos.slice(), follow: b.pos.slice(), lift: hands.time }); // prettier-ignore
      hands.placeAt(hands.hold, ray);
    }
    w.wake();
  }

  // Release a joint's hold. Returns true when the hold was ours.
  release(h) {
    const j = h.ctl;
    if (!j) {
      const sj = this.joint(h.body);
      // (Let go while still in its doorway, it slides back in.)
      if (
        sj?.type === "socket" &&
        (sj.inDoor || (sj.armed && this.socketNear(sj, h.body.pos, null)))
      ) {
        this.dropHold(h);
        this.glide(sj);
        return true;
      }
      const seat = sj?.type === "break" && sj.broken && sj.armed ? this.seatNear(sj, h.body.pos, null) : -1; // prettier-ignore
      if (seat >= 0) {
        this.dropHold(h);
        this.glideSeat(sj, seat);
        return true;
      }
      return false;
    }
    j.held = null;
    if (j.type === "break") {
      // Not pulled hard enough: it springs back.
      j.springBack = { t0: this.time, from: j.tug || tf() };
      j.pull = 0;
    }
    // A flick sets a dial (or a lid) going: the finger's last speed.
    if (j.type === "dial" && j.d.coast === false) j.w = 0;
    this.hands.hold = null;
    this.world.wake();
    return true;
  }

  dropHold(h) {
    const b = h.body;
    if (h.joint) this.world.removeJoint(h.joint);
    b.held = false;
    b.holdQ = null;
    b.angDamping = b.angDampingFree ?? b.angDamping;
    this.hands.hold = null;
  }

  // ---- Sockets ----

  socketNear(j, pos, ray) {
    const R = this.hands.R();
    const snap = (j.d.snap ?? 0.3) * R;
    let d = Infinity;
    // Its place, or (lane Hands-on H2) the mouth of its doorway.
    for (const home of j.d.out
      ? [j.pc.home.pos, v3.add(j.pc.home.pos, j.d.out)]
      : [j.pc.home.pos]) {
      d = Math.min(d, v3.len(v3.sub(pos, home)));
      if (ray) {
        // Or the finger points at its place.
        const t = Math.max(0, v3.dot(v3.sub(home, ray.origin), ray.dir));
        d = Math.min(d, v3.len(v3.sub(v3.add(ray.origin, v3.scale(ray.dir, t)), home)));
      }
    }
    return d < snap;
  }

  // Lane Hands-on H2: a socket's `out` (recipe units) is the way its piece
  // comes out and goes in (a melon's slice, straight up out of its slot).
  // Taken from its place, the piece slides along it, held as built, to
  // where the finger points along that line; past its end, it is free.
  // Returns true while it is still in the doorway.
  door(j, h, ray) {
    if (!j.inDoor) return false;
    const home = j.pc.home.pos;
    const L = v3.len(j.d.out);
    const u = v3.scale(j.d.out, 1 / L);
    // The point on the doorway's line nearest the finger's ray.
    const w0 = v3.sub(home, ray.origin);
    const b = v3.dot(u, ray.dir);
    const c = v3.dot(ray.dir, ray.dir);
    const den = c - b * b;
    const s = den > 1e-6 ? (b * v3.dot(ray.dir, w0) - c * v3.dot(u, w0)) / den : 0;
    if (s >= L) {
      j.inDoor = false;
      h.body.holdQ = yawOnly(j.pc.home.q);
      return false;
    }
    h.target = v3.add(home, v3.scale(u, Math.max(0, s)));
    h.body.holdQ = j.pc.home.q.slice();
    this.world.wake();
    return true;
  }

  nearSocket(j, h, ray) {
    const R = this.hands.R();
    const snap = (j.d.snap ?? 0.3) * R;
    let away = v3.len(v3.sub(h.body.pos, j.pc.home.pos));
    if (j.d.out) away = Math.min(away, v3.len(v3.sub(h.body.pos, v3.add(j.pc.home.pos, j.d.out)))); // (away from its doorway's mouth too) // prettier-ignore
    if (!j.armed) {
      // Lane Hands-on H5: `armAway` (toy radii): armed only once both the
      // piece and the finger's line are that far from its place (small
      // pieces packed close, an atlas's organs, would click straight back).
      const far = j.d.armAway;
      if (far !== undefined) {
        const home = j.pc.home.pos;
        const t = ray ? Math.max(0, v3.dot(v3.sub(home, ray.origin), ray.dir)) : 0;
        const aim = ray ? v3.len(v3.sub(v3.add(ray.origin, v3.scale(ray.dir, t)), home)) : Infinity; // prettier-ignore
        if (away > far * R && aim > far * R) j.armed = true;
        return;
      }
      if (away > snap * 1.5) j.armed = true;
      return;
    }
    if (this.socketNear(j, h.body.pos, ray)) {
      this.dropHold(h);
      this.glide(j);
    }
  }

  glide(j) {
    const b = j.body;
    b.vel = [0, 0, 0];
    b.omega = [0, 0, 0];
    j.gliding = { t0: this.time, pos: b.pos.slice(), q: b.q.slice() };
    j.inDoor = false;
    // (Lane Hands-on H2: through its doorway, the mouth first unless it is
    // already in it.)
    if (j.d.out) {
      const R = this.hands.R();
      const home = j.pc.home.pos;
      const L = v3.len(j.d.out);
      const u = v3.scale(j.d.out, 1 / L);
      const rel = v3.sub(b.pos, home);
      const s = v3.dot(rel, u);
      const inside = v3.len(v3.sub(rel, v3.scale(u, s))) < 0.1 * R;
      j.gliding.door = v3.add(home, v3.scale(u, inside ? Math.max(0, Math.min(L, s)) : L));
    }
    j.armed = false;
    this.world.wake();
  }

  // ---- Latches and triggers (lane Hands-on H3) ----

  // Whether a joint with `latch` ("max", "min" or a value) sits on it.
  atLatch(j) {
    const L = this.latchAt(j);
    return L !== null && Math.abs(j.v - L) < 1e-3;
  }

  // Its latch's value, or null.
  latchAt(j) {
    const L = j.d.latch;
    return L === undefined ? null : L === "max" ? j.max : L === "min" ? j.min : L;
  }

  // A tap on the toy: each latched joint with a `trigger` lets go (a
  // crossbow's string snaps forward). True when one did.
  trigger() {
    let any = false;
    for (const j of this.list) {
      if (!j.latched || !j.d.trigger) continue;
      j.latched = false;
      j.letGo = true;
      j.awake = true;
      // Off its latch, so it doesn't catch again at once.
      const away = this.latchAt(j) <= j.min ? 1 : -1;
      j.v += away * 1e-2;
      j.w = away * 1;
      j.moving = true;
      this.cue(j, "free", 1);
      any = true;
    }
    if (any) {
      this.hands.moved = true;
      this.world.wake();
    }
    return any;
  }

  // ---- Seats (lane Hands-on H3) ----

  // A break with `reseat` (true, or { snap, seats: [{ pos, quat }] }): its
  // places, home first, each the piece's middle and turn there.
  seats(j) {
    const home = { pos: j.pc.home.pos, quat: j.pc.home.q };
    const more = typeof j.d.reseat === "object" ? j.d.reseat.seats || [] : [];
    return [home, ...more.map((s) => ({ pos: s.pos, quat: s.quat || home.quat }))];
  }

  // The seat a piece at `pos` (or the finger's ray) is near enough to click
  // into, or -1.
  seatNear(j, pos, ray) {
    const R = this.hands.R();
    const snap = ((typeof j.d.reseat === "object" && j.d.reseat.snap) || 0.3) * R;
    let best = -1;
    let bd = snap;
    this.seats(j).forEach((s, i) => {
      let d = v3.len(v3.sub(pos, s.pos));
      if (ray) {
        const t = Math.max(0, v3.dot(v3.sub(s.pos, ray.origin), ray.dir));
        d = Math.min(d, v3.len(v3.sub(v3.add(ray.origin, v3.scale(ray.dir, t)), s.pos)));
      }
      if (d < bd) {
        bd = d;
        best = i;
      }
    });
    return best;
  }

  nearSeat(j, h, ray) {
    const R = this.hands.R();
    const snap = ((typeof j.d.reseat === "object" && j.d.reseat.snap) || 0.3) * R;
    if (!j.armed) {
      const away = Math.min(...this.seats(j).map((s) => v3.len(v3.sub(h.body.pos, s.pos))));
      if (away > snap * 1.5) j.armed = true;
      return;
    }
    const seat = this.seatNear(j, h.body.pos, ray);
    if (seat >= 0) {
      this.dropHold(h);
      this.glideSeat(j, seat);
    }
  }

  glideSeat(j, seat) {
    const b = j.body;
    b.vel = [0, 0, 0];
    b.omega = [0, 0, 0];
    j.gliding = { t0: this.time, pos: b.pos.slice(), q: b.q.slice(), seat };
    j.armed = false;
    this.world.wake();
  }

  // Gliding into a seat; there it holds fast again, as unbroken.
  seatStep(j) {
    const G = j.gliding;
    const b = j.body;
    const s = this.seats(j)[G.seat];
    const f = Math.min(1, (this.time - G.t0) / GLIDE);
    const e = f * f * (3 - 2 * f);
    b.pos = G.pos.map((v, i) => v + (s.pos[i] - v) * e);
    b.q = quat.slerp(G.q, s.quat, e);
    b.vel = [0, 0, 0];
    b.omega = [0, 0, 0];
    b.prevPos = b.pos.slice();
    b.prevQ = b.q.slice();
    if (f < 1) return true;
    const home = j.pc.home;
    if (G.seat === 0) {
      b.goHome();
      j.seatT = null;
    } else {
      const q = quat.norm(quat.mul(s.quat, quat.conj(home.q)));
      j.seatT = tf(q, v3.sub(s.pos, quat.rotate(q, home.pos)));
    }
    b.seated = G.seat > 0;
    this.pin(j);
    j.broken = false;
    j.tug = tf();
    j.springBack = null;
    j.gliding = null;
    this.pose(j);
    this.cue(j, "socket", 1);
    return true;
  }

  // ---- Each step ----

  // One fixed step (seconds) before the world's. Returns true while
  // anything here moves.
  step(dt) {
    this.time += dt;
    if (!this.hands.moved && !this.hands.homing) this.refresh();
    let busy = false;
    if (this.upright) return this.rightStep(dt);
    const g = this.world.gravity;
    for (const j of this.list) {
      if (j.type === "socket") {
        if (j.gliding) busy = this.glideStep(j) || busy;
        continue;
      }
      if (j.type === "break") {
        if (j.gliding) {
          busy = this.seatStep(j) || busy;
          continue;
        }
        const back = !!j.springBack;
        if (back) {
          const f = Math.min(1, (this.time - j.springBack.t0) / 0.18);
          const T = j.springBack.from;
          j.tug = tf(quat.slerp(T.q, ID, f), v3.scale(T.t, 1 - f));
          if (f >= 1) {
            j.springBack = null;
            j.tug = tf();
          }
          busy = true;
        }
        if (!j.broken && (j.held || back || this.moves(j.parent))) {
          this.pose(j);
          busy = busy || !!j.held;
        }
        continue;
      }
      if (j.type === "piece") continue;
      busy = this.drivenStep(j, dt, g) || busy;
    }
    this.follow();
    if (busy) {
      this.hands.moved = true;
      this.world.wake();
    }
    return busy;
  }

  moves(j) {
    if (!j) return false;
    if (j.type === "piece") return !j.body.pinned;
    if (j.type === "break") return !j.broken ? !!(j.held || j.springBack) || this.moves(j.parent) : !j.body.pinned; // prettier-ignore
    return !!j.moving || this.moves(j.parent);
  }

  drivenStep(j, dt, g) {
    const d = j.d;
    const v0 = j.v;
    const R = this.hands.R();
    // Caught on its latch (a crossbow's string in its nut): held fast, the
    // finger can't move it; only its trigger frees it (lane Hands-on H3).
    if (j.latched) {
      j.w = 0;
      j.moving = false;
      if (this.moves(j.parent)) this.pose(j);
      return false;
    }
    if (j.held) {
      let target = j.target ?? j.v;
      if (j.stuck) {
        // Stuck fast (a sword in its stone): it wiggles as the finger pulls,
        // and comes free once pulled `stick` along its way.
        const pull = target - j.start;
        const stick = d.stick * R;
        const f = clamp(Math.abs(pull) / stick, 0, 1);
        j.wig = d.wiggle ? 0.05 * f * Math.sin(this.time * 38) : 0;
        if (Math.abs(pull) < stick || (d.stickWay && Math.sign(pull) !== Math.sign(d.stickWay))) {
          this.pose(j);
          for (const c of j.children) if (this.posed(c)) this.pose(c);
          j.moving = true;
          return true;
        }
        j.stuck = false;
        j.wig = 0;
        this.cue(j, "free", 1);
      }
      // The part catches the finger on a critically damped spring.
      const k = FOLLOW;
      const acc = k * k * (target - j.v) - 2 * k * j.w;
      j.w += acc * dt;
      j.v += j.w * dt;
    } else {
      if (j.stuck) {
        j.moving = false;
        return false;
      }
      // Nothing moves a part nobody has touched since ↺ (a part built off
      // its resting place stays as built).
      if (!j.awake) {
        if (this.moves(j.parent)) this.pose(j);
        return false;
      }
      let acc = 0;
      // Its weight: about a hinge, the turn gravity gives its middle; along a
      // slider, gravity along the line.
      // (A dial is balanced: no weight unless asked.)
      const gs = d.gravity === false ? 0 : d.gravity === true || (d.gravity === undefined && j.type !== "dial") ? 1 : d.gravity ?? 0; // prettier-ignore
      const P = j.parent ? this.full(j.parent) : tf();
      const gl = quat.rotate(quat.conj(P.q), g); // gravity in the parent's home frame
      if (gs && j.type === "slider") acc += gs * v3.dot(gl, j.axis);
      if (gs && j.type !== "slider") {
        const com = d.com || j.pc.home.pos;
        const r = perp(v3.sub(tfApply(this.delta(j), com), j.pivot), j.axis);
        const l2 = v3.dot(r, r);
        if (l2 > 1e-6) acc += (gs * v3.dot(v3.cross(r, gl), j.axis)) / l2;
      }
      if (d.spring) acc -= d.spring * (j.v - (d.rest ?? 0));
      const damp = d.damping ?? (j.type === "dial" ? 0 : 3);
      acc -= damp * j.w;
      // Clicks: near standing still, a dial settles into the nearest one.
      if (d.detents && Math.abs(j.w) < 3) {
        const step = TAU / d.detents;
        const near = Math.round(j.v / step) * step;
        acc -= 120 * (j.v - near) + 12 * j.w;
      }
      // Friction (a slider held in its stone, a stiff hinge): it stays put
      // unless pushed harder than this.
      const fr = (d.friction ?? 0) * (j.type === "slider" ? R : 1);
      if (fr > 0) {
        if (Math.abs(j.w) < fr * dt * 1.5 && Math.abs(acc) <= fr) {
          acc = 0;
          j.w = 0;
        } else acc -= Math.sign(j.w || acc) * fr;
      }
      j.w += acc * dt;
      // A dial's coast loses speed (`drag` per second).
      if (j.type === "dial") j.w *= Math.exp(-(d.drag ?? 0.8) * dt);
      j.v += j.w * dt;
    }
    // The stops. Lane Hands-on H5: `limits(at)` may narrow them as the
    // toy stands now ([min, max] within the joint's own; `at.joint(name)`
    // reads another's value; a piece another blocks: a triangle that can't
    // slide through its neighbor).
    let lo = j.min;
    let hi = j.max;
    if (d.limits) {
      const at = { joint: (n) => this.byName.get(n)?.v ?? null };
      const [a, b] = d.limits(at) || [];
      // (Never past where it already was: a narrowed stop holds it there.)
      if (a !== undefined) lo = Math.max(lo, Math.min(a, v0));
      if (b !== undefined) hi = Math.min(hi, Math.max(b, v0));
    }
    if (j.v < lo || j.v > hi) {
      const lim = j.v < lo ? lo : hi;
      const speed = Math.abs(j.w) * this.reach(j);
      j.v = lim;
      if (speed > 0.5 * R) this.cue(j, "stop", speed / R);
      j.w = j.held ? 0 : -j.w * (d.bounce ?? 0.2);
      if (Math.abs(j.w) * this.reach(j) < 0.3 * R) j.w = 0;
    }
    // It catches on its latch as it gets there or passes it (lane Hands-on H3).
    const L = this.latchAt(j);
    // (`catch`: within that of it, it catches: a finger seldom lands it
    // exactly on its latch.)
    // (Just let go by its trigger, it must leave that first.)
    const near = L !== null && Math.abs(j.v - L) < (d.catch ?? 1e-3);
    if (j.letGo && !near) j.letGo = false;
    if (L !== null && !j.letGo && (near || (v0 - L) * (j.v - L) < 0)) {
      j.v = L;
      j.latched = true;
      j.w = 0;
      this.cue(j, "latch", 1);
      this.pose(j);
      for (const c of j.children) if (this.posed(c)) this.pose(c);
      j.moving = false;
      return false;
    }
    // Clicks as it passes each detent.
    if (d.detents) {
      const step = TAU / d.detents;
      const a = Math.floor(v0 / step + 0.5);
      const b = Math.floor(j.v / step + 0.5);
      if (a !== b) this.cue(j, "detent", Math.abs(j.w) * this.reach(j) / R, b); // prettier-ignore
    }
    if (d.turn && j.v !== v0) {
      const cues = d.turn(j.v, j.v - v0, this.hands.info) || null;
      if (cues) this.play(Array.isArray(cues) ? cues : [cues]);
    }
    const moving = !!j.held || Math.abs(j.w) > STILL || Math.abs(j.v - v0) > 1e-6;
    if (!moving) j.w = 0;
    if (moving || j.moving || this.moves(j.parent)) {
      this.pose(j);
      for (const c of j.children) if (this.posed(c)) this.pose(c);
    }
    j.moving = moving;
    return moving;
  }

  // How far the part reaches from its axis (to turn a turn rate into a
  // speed): its pick size, at least.
  reach(j) {
    if (j.type === "slider") return 1;
    const r = perp(v3.sub(j.pc.home.pos, j.pivot), j.axis);
    return Math.max(v3.len(r), ...(j.pc.def.pick || [0.2]));
  }

  glideStep(j) {
    const G = j.gliding;
    const b = j.body;
    const f = Math.min(1, (this.time - G.t0) / (G.door ? 2 * GLIDE : GLIDE));
    const ease = (x) => x * x * (3 - 2 * x);
    if (G.door) {
      // To the mouth of its doorway, turning as built, then straight in.
      const e = ease(Math.min(1, 2 * f));
      const e2 = ease(Math.max(0, 2 * f - 1));
      const at = G.pos.map((v, i) => v + (G.door[i] - v) * e);
      b.pos = at.map((v, i) => v + (j.pc.home.pos[i] - v) * e2);
      b.q = quat.slerp(G.q, j.pc.home.q, e);
    } else {
      const e = ease(f);
      b.pos = G.pos.map((v, i) => v + (j.pc.home.pos[i] - v) * e);
      b.q = quat.slerp(G.q, j.pc.home.q, e);
    }
    b.vel = [0, 0, 0];
    b.omega = [0, 0, 0];
    b.prevPos = b.pos.slice();
    b.prevQ = b.q.slice();
    if (f < 1) return true;
    // Home: it locks in place, as built.
    b.goHome();
    this.pin(j);
    j.gliding = null;
    this.cue(j, "socket", 1);
    return true;
  }

  pin(j) {
    const b = j.body;
    b.pinned = true;
    const def = j.pc.def;
    if (def?.rest) {
      b.solid = def.rest;
      b.bound = boundOf(b);
    }
    b.invMass = 0;
    b.invI = [0, 0, 0];
  }

  // Level 1 (`hands.upright`): the toy turns back upright (only its tilt;
  // its turn about the upright stays), rocking as it goes.
  rightStep(dt) {
    const b = this.hands.body;
    if (b?.settled && (b.held || this.hands.press)) this.unsettle(b); // lane Hands-on H5
    if (!b || b.held) return false;
    const u = quat.rotate(quat.mul(b.q, quat.conj(b.home.q)), [0, 1, 0]);
    const ax = v3.cross(u, [0, 1, 0]);
    const s = v3.len(ax);
    const ang = Math.atan2(s, u[1]);
    // Lane Hands-on H5: `rest` (radians): back within it of upright, on the
    // floor and nearly still, it settles and holds there until the finger
    // touches it again (a toy on a round base, an owl gripping its branch,
    // would otherwise creep on and never come to rest).
    const rest = this.upright.rest;
    if (b.settled) return false;
    if (rest && ang < rest && b.touchTick >= this.world.tick - 1) {
      const R = this.hands.R();
      if (v3.len(b.vel) < 0.3 * R && v3.len(b.omega) < 1) {
        b.settled = { invMass: b.invMass, invI: b.invI.slice() };
        b.invMass = 0;
        b.invI = [0, 0, 0];
        b.vel = [0, 0, 0];
        b.omega = [0, 0, 0];
        return false;
      }
    }
    if (ang < 0.01 && v3.len(b.omega) < 0.05) return false;
    const n = s > 1e-9 ? v3.scale(ax, 1 / s) : [0, 0, 0];
    const k = this.upright.k;
    const c = this.upright.damping;
    const w = b.omega;
    const wy = w[1];
    for (let i = 0; i < 3; i++) b.omega[i] += (k * ang * n[i] - c * (w[i] - (i === 1 ? wy : 0))) * dt; // prettier-ignore
    this.world.wake();
    this.hands.moved = true;
    return true;
  }

  // Lane Hands-on H5: a settled toy (upright's `rest`) comes loose again.
  unsettle(b) {
    b.invMass = b.settled.invMass;
    b.invI = b.settled.invI;
    b.settled = null;
  }

  // ---- ↺ ----

  // During ↺ (e: 0..1 eased): driven parts turn or slide home along their
  // own way (a lid swings shut, not cuts across). Returns true when this
  // body is ours to pose.
  home(b, e) {
    const j = this.joint(b);
    if (!j) return false;
    if (j.type === "hinge" || j.type === "slider" || j.type === "dial") {
      if (j.homeFrom === undefined || e < (j.homeE ?? 1)) j.homeFrom = j.v;
      j.homeE = e;
      // A dial goes the short way round to a turn that looks the same.
      let to = j.homeV ?? 0;
      if (j.type === "dial" && !Number.isFinite(j.min)) to += TAU * Math.round((j.homeFrom - to) / TAU); // prettier-ignore
      j.v = j.homeFrom + (to - j.homeFrom) * e;
      j.w = 0;
      j.wig = 0;
      this.pose(j);
      return true;
    }
    if (j.type === "break" && !j.broken && j.seatT) {
      // Reseated elsewhere: it goes home from where it sat (lane Hands-on H3).
      const from = this.hands.homing?.from.find((f) => f.b === b);
      if (from) {
        b.pos = from.pos.map((v, i) => v + (j.pc.home.pos[i] - v) * e);
        b.q = quat.slerp(from.q, j.pc.home.q, e);
        return true;
      }
    }
    if (j.type === "break" && !j.broken) {
      j.tug = j.tug ? tf(quat.slerp(j.tug.q, ID, e), v3.scale(j.tug.t, 1 - e)) : tf();
      // Riding a loose piece home: where that piece is on its way.
      const from = j.parent && this.hands.homing?.from.find((f) => f.b === j.parent.body);
      if (from) {
        const pb = j.parent.body;
        const pos = from.pos.map((v, i) => v + (pb.home.pos[i] - v) * e);
        const dq = quat.mul(quat.slerp(from.q, pb.home.q, e), quat.conj(pb.home.q));
        const T = tfMul(tf(dq, v3.sub(pos, quat.rotate(dq, pb.home.pos))), j.tug);
        b.pos = tfApply(T, j.pc.home.pos);
        b.q = quat.norm(quat.mul(T.q, j.pc.home.q));
        return true;
      }
      this.pose(j);
      return true;
    }
    return false;
  }

  // ↺ is done: every part home, everything broken mended.
  reset() {
    for (const j of this.list) {
      j.held = null;
      if (j.type === "hinge" || j.type === "slider" || j.type === "dial") {
        j.v = j.homeV ?? 0;
        j.w = 0;
        j.wig = 0;
        j.moving = false;
        j.stuck = !!j.d.stick && Math.abs(j.v) < 1e-6;
        j.latched = this.atLatch(j); // (lane Hands-on H3)
        j.letGo = false;
        j.awake = false;
        j.homeFrom = undefined;
        j.homeE = undefined;
        this.pose(j);
        j.body.pinned = false;
        j.body.invMass = 0;
        j.body.invI = [0, 0, 0];
      }
      if (j.type === "break") {
        this.unglue(j);
        j.broken = false;
        j.tug = tf();
        j.springBack = null;
        j.seatT = null; // (lane Hands-on H3)
        j.gliding = null;
        j.armed = false;
        j.body.seated = false;
      }
      if (j.type === "socket") {
        j.gliding = null;
        j.armed = false;
      }
    }
  }

  // A hit from the world (Hands-on's onHit): a knock hard enough breaks a
  // piece off whatever it hangs on.
  hit(hit) {
    const R = this.hands.R();
    for (const j of this.list) {
      if (j.type !== "break" || j.broken || !j.d.knock || !j.parent) continue;
      if (hit.body !== j.parent.body && hit.other !== j.parent.body) continue;
      if (hit.speed / R < j.d.knock) continue;
      const b = j.body;
      const pb = j.parent.body;
      j.broken = true;
      this.unglue(j);
      this.hands.free(b);
      b.invMass = b.invMassFree || 1;
      b.invI = (b.invIFree || [1, 1, 1]).slice();
      b.vel = pb.vel.slice();
      b.omega = pb.omega.slice();
      this.cue(j, "snap", hit.speed / R);
    }
  }

  // While a piece hangs on a loose piece, its collision points ride on that
  // piece (so the pair lands as one); they go when it breaks off.
  glue(j) {
    const pb = j.parent?.body;
    if (!pb || j.gluedTo) return;
    const b = j.body;
    const pts = (b.points.length ? b.points : b.solid ? surfacePoints(b.solid, 1) : []).map((p) => pb.toLocal(b.toWorld(p))); // prettier-ignore
    j.gluedTo = { body: pb, from: pb.points.length, n: pts.length, radius: pb.radius };
    pb.points.push(...pts);
    pb.bound = boundOf(pb);
  }

  unglue(j) {
    const G = j.gluedTo;
    if (!G) return;
    G.body.points.splice(G.from, G.n);
    G.body.bound = boundOf(G.body);
    for (const o of this.list) if (o.gluedTo?.body === G.body && o.gluedTo.from > G.from) o.gluedTo.from -= G.n; // prettier-ignore
    j.gluedTo = null;
  }

  // Each frame, after the world's steps: unbroken pieces ride on loose
  // parents, which carry their collision points.
  follow() {
    for (const j of this.list) {
      if (j.type !== "break" || j.broken || !j.parent) continue;
      if (this.moves(j.parent)) {
        // Lane Hands-on H2: a piece riding another comes loose when that one
        // tips past `spill` radians (a scoop off a tipped cone).
        if (j.d.spill != null && this.tilt(j.parent) > j.d.spill) {
          this.spill(j);
          continue;
        }
        this.glue(j);
        this.pose(j);
      } else if (j.gluedTo && j.parent.body.pinned) this.unglue(j);
    }
  }

  // Lane Hands-on H2: how far a joint's piece has tipped from how it was
  // built (radians between its up and its up at home).
  tilt(j) {
    const up = quat.rotate(this.full(j).q, [0, 1, 0]);
    return Math.acos(Math.max(-1, Math.min(1, up[1])));
  }

  // It comes loose where it is, moving as the piece it rode was.
  spill(j) {
    const b = j.body;
    const pb = j.parent.body;
    j.broken = true;
    this.unglue(j);
    this.hands.free(b);
    b.invMass = b.invMassFree || 1;
    b.invI = (b.invIFree || [1, 1, 1]).slice();
    b.vel = pb.vel.slice();
    b.omega = pb.omega.slice();
    this.cue(j, "spill", v3.len(pb.vel) / this.hands.R());
  }

  // Parts that ride on a joint without being pieces (`also`): a recipe
  // adds them to the parts Hands-on sends (an aura that rises with the
  // sword, a dancer turned by the crank).
  parts(parts) {
    let out = this.swap(parts);
    for (const j of this.list) {
      if (!j.d.also || j.v === undefined) continue;
      out ||= {};
      j.d.also(j.v, out, this.hands.info, j); // (j: its speed w, held; lane Hands-on H1)
    }
    return out;
  }

  // A scan's piece that can't move cleanly (a tomato whose hidden sides
  // the capture never saw) is swapped, while it is off its place, for a
  // kit-built stand-in in the rig's add-on (`hands.swap`: { part: { kit,
  // fill } }): the scan's part hides, the add-on part `kit` rides where the
  // piece is, and `fill` (optional) shows in the place it left. Off: none.
  swap(parts) {
    const sw = this.def.swap;
    const motion = this.hands.player.motion;
    if (!sw) return parts;
    let addon = null;
    for (const pc of this.hands.pieces) {
      const s = sw[pc.part];
      if (!s) continue;
      const b = pc.body;
      if (b.pinned) continue; // in its place (a moved piece is pinned again once home)
      const dq = quat.mul(b.q, quat.conj(pc.home.q));
      const off = v3.sub(b.pos, pc.home.pos);
      (parts ||= {})[pc.part] = { visible: 0 };
      addon ||= {};
      addon[s.kit] = { visible: 1, quat: dq, offset: off };
      if (s.fill) addon[s.fill] = { visible: 1 };
    }
    motion.handsAddon = addon;
    return parts;
  }

  // ---- Sounds ----

  // An event: the joint's own `sound(ev)` picks a cue (null: silent), else
  // a quiet default for its kind.
  cue(j, kind, speed, n) {
    const ev = { kind, joint: j.name, speed, n, v: j.v, t: this.time };
    this.events.push(ev);
    if (this.events.length > 200) this.events.shift();
    const vol = Math.min(0.8, Math.max(0.15, speed / 6));
    let spec = j.d.sound ? j.d.sound(ev, vol) : undefined;
    if (spec === undefined) spec = DEFAULT_SOUND[kind]?.(vol) ?? null;
    if (spec) this.play([spec]);
  }

  play(specs) {
    const p = this.hands.player;
    if (!p.frozen) p.emit?.("cue", specs);
  }

  // For tests and clips: each joint's value and state.
  state() {
    return this.list.map((j) => ({ name: j.name, type: j.type, v: j.v ?? null, w: j.w ?? null, broken: !!j.broken, held: !!j.held, stuck: !!j.stuck, pinned: !!j.body.pinned, pos: j.body.pos.slice(), home: j.pc.home.pos.slice() })); // prettier-ignore
  }
}

const DEFAULT_SOUND = {
  stop: (vol) => ({ voice: "thud", vol }),
  detent: (vol) => ({ voice: "click", vol: 0.3 + 0.3 * Math.min(1, vol) }),
  snap: (vol) => ({ voice: "crack", vol: Math.max(0.4, vol) }),
  socket: () => ({ voice: "click", vol: 0.5 }),
  free: () => ({ voice: "scrape", vol: 0.4 }),
  latch: () => ({ voice: "click", vol: 0.5 }), // (lane Hands-on H3)
};

function depth(j) {
  let n = 0;
  for (let p = j.parent; p && n < 16; p = p.parent) n++;
  return n;
}

// A rotation's turn about the upright alone (as Hands-on holds a piece it
// carries; lane Hands-on H2's doorways hand the piece on so).
function yawOnly(q) {
  const f = quat.rotate(q, [1, 0, 0]);
  const a = Math.atan2(-f[2], f[0]);
  return quat.axisAngle([0, 1, 0], a);
}

src/physics/hands-on.js:
// Hands-on play (lane Physics): with the ✋ switch on, a drag on the toy
// picks up what is under the finger and a quick let-go tosses it; it lands,
// bounces and settles on the floor under the toy, inside an invisible play
// area, and soft toys squish when they land. ↺ sends everything home.
//
// Two ways a toy plays:
// - Level 1, every toy (scans included): the whole toy is one rigid body,
//   shaped by points on its outside (taken from its splats). Its pose moves
//   the toy's entity (Stage.setToyPose), so splats sort and taps land
//   where it lies; a squish is two uniforms (uSpBodyS, uSpBodyP).
// - Pieces: a kit recipe's `hands` (below) names pieces (its tokens) that
//   are bodies of their own; they stay put until picked up or knocked.
//
// A recipe's `hands`: { pieces(data) => [{ token, pos, quat, solid, points,
// mass, friction, restitution }], floor (y), area (half width), grip,
// gravity (in toy radii per second squared), sound(hit) => cue | null }.
// `handsOn: true | false` on a recipe starts the switch on, or keeps the
// toy out of Hands-on (a picture toy). `handsLevel1: true | (info) => bool`
// lets a picture toy or a still toy (turntable: false) play Level 1 (lane
// Hands-on H3). Pure JavaScript, no DOM.

import { World, Body, boundOf, quat, v3 } from "./world.js";
import { extrasFor } from "./fields.js"; // lane Hands engine A
import { makeJoints } from "./joints.js"; // lane Hands engine B
import { SoftParts, hasSoft } from "./soft.js"; // lane Hands engine C

// How much a toy squishes when it lands (0: not at all) and how much it
// bounces. Anything not listed is solid and bounces a little.
export const SOFT = {
  jelly: 1, "gummy-bear": 1, amoeba: 1, blob: 0.8, "balloon-dog": 0.6, "soap-bubbles": 0.8,
  "beach-ball": 0.5, "bouncy-ball": 0.55, jellyfish: 0.8, octopus: 0.6, pufferfish: 0.5,
  "red-blood-cell": 0.6, "white-blood-cell": 0.6, bacterium: 0.5, paramecium: 0.5,
  "animal-cell": 0.4, tardigrade: 0.4, brain: 0.4, lungs: 0.4, heart: 0.4, kidney: 0.3,
  "teddy-bear": 0.4, hoodie: 0.6, dodgeball: 0.4, "medicine-ball": 0.2, "tennis-ball": 0.3,
  "squash-ball": 0.4, "soccer-ball": 0.3, basketball: 0.25, volleyball: 0.3,
  "water-polo-ball": 0.3, "rubber-duck": 0.4, "rubber-duck-real": 0.4, donut: 0.3, pizza: 0.3,
  burger: 0.3, sushi: 0.2, taco: 0.2, cupcake: 0.3, "ice-cream": 0.3, pancakes: 0.3,
  croissant: 0.2, "croissant-real": 0.2, "birthday-cake": 0.2, "carrot-cake": 0.2,
  strawberry: 0.15, raspberry: 0.2, blackberry: 0.2, grape: 0.3, tomatoes: 0.2, banana: 0.15,
  cherries: 0.2, grapes: 0.2, snail: 0.4, frog: 0.4, starfish: 0.3, "baseball-cap": 0.3,
  "running-shoe": 0.2, kite: 0.2, macarons: 0.15, "paper-lantern": 0.2,
}; // prettier-ignore

export const BOUNCE = {
  "bouncy-ball": 0.85, "ping-pong-ball": 0.8, basketball: 0.75, "tennis-ball": 0.7,
  "golf-ball": 0.7, "beach-ball": 0.6, "soccer-ball": 0.65, volleyball: 0.65,
  "water-polo-ball": 0.6, dodgeball: 0.6, "lacrosse-ball": 0.65, "squash-ball": 0.35,
  "pool-ball": 0.5, marble: 0.5, baseball: 0.5, softball: 0.45, "cricket-ball": 0.5,
  pickleball: 0.5, "rugby-ball": 0.5, "american-football": 0.5, "bowling-ball": 0.15,
  "medicine-ball": 0.1, "hockey-puck": 0.2, "soap-bubbles": 0.5, "balloon-dog": 0.5,
}; // prettier-ignore

// Toys that are hands-on already: their own drags keep working, and the
// switch starts on for them.
export function ownHands(recipe) {
  return !!(recipe?.drag || recipe?.grab);
}

// Whether a recipe asks for Level 1 though it's a picture toy or a still one
// (lane Hands-on H3), live or not.
export function asksLevel1(recipe) {
  return !!recipe?.handsLevel1;
}

// Whether a toy plays in Hands-on at all (a picture toy keeps its pages).
export function canPlay(info) {
  const r = info?.recipe;
  if (!info || r?.handsOn === false) return false;
  // (A picture toy that asks for joints plays them: a picture frame swings
  // on its nail; lane Hands-on H3.)
  if (r?.hands?.joints) return true;
  // (A picture toy or a still one, turntable: false, that asks for Level 1
  // plays it: picked up, tossed and set down whole. `handsLevel1` may be a
  // function of the toy's info, false while the toy is a live tool someone
  // is working in (a converter with a file open, the Screen capturing);
  // lane Hands-on H3.)
  const l1 = typeof r?.handsLevel1 === "function" ? !!r.handsLevel1(info) : !!r?.handsLevel1;
  if (r?.pictures || r?.turntable === false) return l1;
  return true;
}

const PRESS_MOVE = 7; // CSS pixels before a press becomes a pick-up
const GRAVITY = 26; // toy radii per second squared
const HOME_SECS = 0.45;
// The grab (the owner's note of October 3, 2026: a touch must never fling).
const STEP = 1 / 60; // the world always steps this long, whatever the frame rate
const FOLLOW = 14; // the held point's spring (per second), critically damped
const PLACE_FOLLOW = 30; // a piece being placed (held level, no swing) follows closer
const NUDGE = 24; // CSS pixels: a drag shorter than this pushes the toy, never picks it up
const THROW_WINDOW = 0.1; // seconds of finger motion a let-go takes its speed from
const THROW_MAX = 4; // toy radii per second
const THROW_MIN = 0.4; // toy radii per second: slower than this is a still hold
const AIR_DRAG = 0.6; // per second, on a thrown thing
// Held, a thing hangs from the finger: it tilts and swings as the hand
// speeds up and slows down, and a gentle pull (per second) brings it back
// toward the way it stood. Picked up, it lifts this far (toy radii).
const HOLD_UPRIGHT = 1;
const HOLD_SWING_DAMPING = 1.2;
const PUSH_MAX = 2; // toy radii per second: the fastest a nudge pushes
const PICK_LIFT = 0.15;
const FLIP_HOLD = 0.5; // seconds a finger may rest after its flick before letting go (lane Hands-on H2)
const FLIP_PX = 400; // CSS pixels per second up the screen: a flick this fast flips a `flip` piece (lane Hands-on H2)
const FLIP_UP = 4; // toy radii per second: how fast a flipped piece rises

export class HandsOn {
  // player: the Player (stage, camera, toyInfo, ray, proc).
  constructor(player) {
    this.player = player;
    this.on = false;
    this.world = null;
    this.mode = null; // "toy" | "pieces"
    this.body = null; // Level 1: the toy's body
    this.pieces = []; // pieces mode: { body, token, home }
    this.hold = null; // { body, joint, plane, target }
    this.press = null; // { world, x, y }
    this.squish = null; // { amp, t0, axis, point, soft }
    this.homing = null; // { t0, from: [{ body, pos, q }] }
    this.moved = false; // anything off home
    this.time = 0;
    this.acc = 0; // time not yet stepped (less than one STEP)
    this.simTime = 0; // the world's clock (whole STEPs)
    this.lastResort = 0;
    this.sounds = []; // hits for the app to play: { speed, soft, piece }
  }

  // A new toy: everything back to how it was built.
  attach(info) {
    this.available = undefined; // (lane Hands-on H3)
    this.clear();
    this.info = info;
    // (A toy with its own drags that also asks for Level 1, a book whose
    // pages pull over, starts with the switch off: its pages pull either way.)
    const l1own = ownHands(info?.recipe) && asksLevel1(info?.recipe);
    this.on = canPlay(info) && !l1own && (ownHands(info?.recipe) || info?.recipe?.handsOn === true);
    this.extras?.dispose(); // lane Hands engine A: materials and fields
    this.extras = extrasFor(this, info);
  }

  clear() {
    this.world = null;
    this.mode = null;
    this.body = null;
    this.pieces = [];
    this.hold = null;
    this.press = null;
    this.squish = null;
    this.homing = null;
    this.moved = false;
    this.joints = null; // lane Hands engine B
    this.softParts?.stretchHome(); // lane Hands engine C
    this.softParts = null;
    this.player.stage.setToyPose?.(null);
    this.player.motion.handsTokens = null;
    this.player.motion.handsParts = null;
    this.player.motion.handsFix = null; // lane Hands engine A
    this.player.motion.handsAddon = null; // lane Hands engine B
  }

  // Pieces live in the recipe's own coordinates (a kit toy is centered and
  // scaled to fit); the whole toy lives in the world.
  units() {
    const tf = this.mode === "pieces" ? this.player.motion.ctx?.transform : null;
    return tf?.scale || 1;
  }

  R() {
    return this.info.radius / this.units();
  }

  ray(x, y) {
    return this.mode === "pieces" ? this.player.recipeRay(x, y) : this.player.stage.ray(x, y);
  }

  get own() {
    return ownHands(this.info?.recipe);
  }

  setOn(on) {
    this.on = !!on && canPlay(this.info);
    if (!this.on) this.reset();
  }

  // Whether a toy's own drags work (the laptop's trackpad, the gummy
  // bear's stretch): with the switch on, or on a toy Hands-on leaves alone.
  ownDrags() {
    return this.on || !canPlay(this.info) || (this.own && asksLevel1(this.info?.recipe));
  }

  // True while a drag on the toy should pick it (or a piece) up. (On a toy
  // with its own drags that asks for Level 1, a press its own drag doesn't
  // take, off the book's pages: see pressAt; lane Hands-on H3.)
  canGrab() {
    return this.on && (!this.own || asksLevel1(this.info?.recipe)) && canPlay(this.info);
  }

  // ---- The world ----

  // Built on the first pick-up, so opening a toy costs nothing.
  ensure() {
    if (this.world) return this.world;
    const info = this.info;
    const R = info.radius;
    const hands = info.recipe?.hands;
    if (hands?.pieces || hands?.joints || hasSoft(hands)) return this.buildPieces(hands); // (joints: lane Hands engine B; soft parts: lane Hands engine C)
    const hull = this.hull();
    const g = (hands?.gravity ?? GRAVITY) * R;
    const w = new World({ gravity: [0, -g, 0], substeps: 8, sleepSpeed: 0.03 * R, minHit: 0.6 * R, maxSpeed: 12 * R }); // prettier-ignore
    const floor = hull.floor;
    w.plane([0, 1, 0], floor, { friction: 0.7, restitution: 0.3 });
    const A = hull.reach * 1.05 + 0.4 * R;
    const c = hull.center;
    for (const [nx, nz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) // prettier-ignore
      w.plane([nx, 0, nz], nx * (c[0] - nx * A) + nz * (c[2] - nz * A), { friction: 0.3, restitution: 0.4 }); // prettier-ignore
    w.plane([0, -1, 0], -(floor + Math.max(4.5 * R, hull.top - floor + 2.5 * R)), { restitution: 0.2 }); // prettier-ignore
    const id = info.id;
    const soft = hands?.soft ?? SOFT[id] ?? 0; // (hands.soft: lane Hands-on H1)
    const bounce = BOUNCE[id] ?? 0.25 + 0.2 * soft;
    const h = hull.half;
    const m = 1;
    const opts = {
      pos: c.slice(),
      mass: m,
      inertia: [(m * (h[1] ** 2 + h[2] ** 2)) / 3, (m * (h[0] ** 2 + h[2] ** 2)) / 3, (m * (h[0] ** 2 + h[1] ** 2)) / 3], // prettier-ignore
      friction: 0.6,
      restitution: bounce,
      damping: 0.15,
      angDamping: 0.6,
    };
    // A ball rolls on one point; anything else rests on the points of its
    // outside.
    if (hull.round) opts.solid = { type: "sphere", r: hull.round };
    else opts.points = hull.points;
    this.body = w.add(new Body(opts));
    this.soft = soft;
    this.mode = "toy";
    this.world = w;
    this.extras?.build(w); // lane Hands engine A
    this.joints = makeJoints(this, w); // lane Hands engine B: hands.upright
    return w;
  }

  // Points on the toy's outside (world, about its middle), from a sample of
  // its splats: in each of 64 directions, the splat furthest out, ignoring
  // the last half percent (floaters).
  hull() {
    const info = this.info;
    const stage = this.player.stage;
    const res = stage.toy?.entity?.gsplat?.resource || stage.toy?.resource;
    const centers = res?.centers;
    const R = info.radius;
    const n = centers ? Math.floor(centers.length / 3) : 0;
    const count = Math.min(n, res?.numSplats || n);
    const sample = Math.min(count, 6000);
    const pts = [];
    if (sample > 8) {
      const step = count / sample;
      for (let i = 0; i < sample; i++) {
        const j = Math.floor(i * step) * 3;
        pts.push(stage.modelToWorld([centers[j], centers[j + 1], centers[j + 2]]));
      }
    } else {
      // No centers to read: the toy's box.
      const c = info.center;
      for (const sx of [-1, 1])
        for (const sy of [-1, 1])
          for (const sz of [-1, 1])
            pts.push([c[0] + sx * info.half[0], c[1] + sy * info.half[1], c[2] + sz * info.half[2]]); // prettier-ignore
    }
    // Its middle: halfway across the trimmed extent on each axis.
    const lo = [];
    const hi = [];
    for (let k = 0; k < 3; k++) {
      const a = pts.map((p) => p[k]).sort((x, y) => x - y);
      lo.push(a[Math.floor(a.length * 0.01)]);
      hi.push(a[Math.min(a.length - 1, Math.floor(a.length * 0.99))]);
    }
    const center = lo.map((v, k) => (v + hi[k]) / 2);
    const dirs = fibonacci(64);
    const out = [];
    for (const d of dirs) {
      const proj = pts.map((p) => (p[0] - center[0]) * d[0] + (p[1] - center[1]) * d[1] + (p[2] - center[2]) * d[2]); // prettier-ignore
      const sorted = proj.slice().sort((x, y) => x - y);
      const cut = sorted[Math.max(0, Math.floor(sorted.length * 0.995) - 1)];
      let best = 0;
      let bd = Infinity;
      for (let i = 0; i < proj.length; i++) {
        const e = Math.abs(proj[i] - cut);
        if (e < bd) {
          bd = e;
          best = i;
        }
      }
      out.push(v3.sub(pts[best], center));
    }
    // Round enough to roll (a ball)?
    const dist = out.map((p) => v3.len(p));
    const mean = dist.reduce((a, b) => a + b, 0) / dist.length;
    const spread = Math.max(...dist.map((d) => Math.abs(d - mean))) / mean;
    const floor = Math.min(...out.map((p) => p[1])) + center[1];
    return {
      center,
      points: out,
      floor,
      top: Math.max(...out.map((p) => p[1])) + center[1],
      reach: Math.max(...dist),
      half: hi.map((v, k) => Math.max(1e-3 * R, (v - lo[k]) / 2)),
      round: spread < 0.09 ? mean : 0,
    };
  }

  // The play area's walls in pieces mode, [x0, x1, z0, z1]: ±`area`, or
  // lane Hands-on H2's `walls` (toy radii) for a toy on a tray that isn't
  // square (the croissant's lid stays on its baking tray).
  walls() {
    const hands = this.info.recipe.hands;
    const R = this.R();
    if (hands.walls) return hands.walls.map((v) => v * R);
    const A = (hands.area ?? 1.6) * R;
    return [-A, A, -A, A];
  }

  // The walls a held piece's middle stays within: with `walls`, far
  // enough in that all of it does (by its `pick` box, as it is turned).
  inWalls(b) {
    const w = this.walls();
    const pc = this.info.recipe.hands.walls && this.pieces.find((p) => p.body === b);
    if (!pc?.def.pick) return w;
    const [px, py, pz] = pc.def.pick;
    const ax = quat.rotate(b.q, [1, 0, 0]);
    const ay = quat.rotate(b.q, [0, 1, 0]);
    const az = quat.rotate(b.q, [0, 0, 1]);
    const ex = Math.abs(ax[0]) * px + Math.abs(ay[0]) * py + Math.abs(az[0]) * pz;
    const ez = Math.abs(ax[2]) * px + Math.abs(ay[2]) * py + Math.abs(az[2]) * pz;
    const fit = (lo, hi, e) =>
      hi - lo > 2 * e ? [lo + e, hi - e] : [(lo + hi) / 2, (lo + hi) / 2];
    return [...fit(w[0], w[1], ex), ...fit(w[2], w[3], ez)];
  }

  buildPieces(hands) {
    const info = this.info;
    this.mode = "pieces";
    const R = this.R();
    const data = this.player.proc?.ctx?.kit?.data;
    const g = (hands.gravity ?? GRAVITY) * R;
    const w = new World({ gravity: [0, -g, 0], substeps: hands.substeps ?? 10, sleepSpeed: 0.02 * R, minHit: 0.35 * R, maxPush: 0.01 * R, maxSpeed: 10 * R }); // prettier-ignore
    // (A floor may depend on the build: a d20 sits lower than two d6s; lane Hands-on H1.)
    const floor = typeof hands.floor === "function" ? hands.floor(data, info) : hands.floor;
    w.plane([0, 1, 0], floor ?? 0, { friction: hands.friction ?? 0.9, restitution: 0.15, grip: hands.grip ?? 0 }); // prettier-ignore
    const [x0, x1, z0, z1] = this.walls();
    for (const [nx, nz, d] of [[1, 0, x0], [-1, 0, -x1], [0, 1, z0], [0, -1, -z1]]) // prettier-ignore
      w.plane([nx, 0, nz], d, { friction: 0.3, restitution: 0.3 });
    this.pieces = [];
    for (const p of hands.pieces?.(data, info) || []) {
      // Lane Hands-on H2: `shown` is where the recipe's drive shows the
      // piece at rest when that isn't where it was built (a kiwi's half,
      // built face up and shown closed): it starts and goes home there.
      const at = p.shown?.pos || p.pos;
      const atQ = p.shown?.quat || p.quat || [0, 0, 0, 1];
      const body = new Body({
        pos: at,
        quat: atQ,
        mass: p.mass ?? 1,
        solid: p.solid,
        points: p.points || [],
        radius: p.radius ?? 0,
        friction: p.friction ?? 0.8,
        restitution: p.restitution ?? 0.15,
        damping: p.damping ?? 0.3,
        angDamping: p.angDamping ?? 1.5,
      });
      w.add(body);
      if (p.strike) body.strike = true; // (lane Hands-on H3)
      this.pieces.push({ body, token: p.token, part: p.part, home: { pos: at.slice(), q: atQ.slice() }, built: { pos: p.pos.slice(), q: (p.quat || [0, 0, 0, 1]).slice() }, def: p }); // prettier-ignore
      // A piece on a stem (a cherry): pinned to its point, springing back
      // to how it hung.
      if (p.joint)
        w.joint(body, body.toLocal(p.joint), null, p.joint, { length: p.jointLength ?? 0 });
      if (p.spring) {
        body.restQ = body.q.slice();
        body.restK = p.spring;
      }
      if (p.hinge) body.hinge = { axis: v3.norm(p.hinge), q: body.q.slice() };
      // Lane Hands-on H5: `home: { k, damping }`: let go, it springs back to
      // where it was built, place and turn (an atom on its molecule).
      if (p.home) {
        body.restPos = body.pos.slice();
        body.restPosK = p.home.k ?? 60;
        body.restPosD = p.home.damping ?? 4;
        body.restQ = body.q.slice();
        body.restK = p.home.k ?? 60;
        body.restD = p.home.damping ?? 4;
      }
      // Lane Hands-on H1: `fixed: true` is a piece that never moves, a
      // stand or a wall for the others to land on (no part of its own).
      if (p.fixed) body.fixedPiece = true;
      body.invMassFree = body.invMass;
      body.invIFree = body.invI.slice();
      if (p.free) continue;
      // Pieces stay where they were built until picked up or knocked hard
      // (a heap of pebbles that was never balanced doesn't slump by itself).
      body.pinned = true;
      // While it lies where it was built it is ground for others, in its
      // full shape (`rest`, else its solid).
      if (p.rest) {
        body.solid = p.rest;
        body.bound = boundOf(body);
      }
      body.invMass = 0;
      body.invI = [0, 0, 0];
    }
    // Pairs that overlapped when one of them came loose pass through each
    // other until they have come apart (a heap built for looks has stones
    // sunk into each other: pushed apart, they would stand on edge).
    this.passing = new Set();
    const key = (a, b) => (a.id < b.id ? `${a.id}:${b.id}` : `${b.id}:${a.id}`);
    this.pairKey = key;
    // (A held piece passes through the others, unless it strikes: a drumstick
    // in the hand hits the drum; lane Hands-on H3.)
    w.pairs = (a, b) =>
      !(a.pinned && b.pinned) && (!a.held || a.strike) && (!b.held || b.strike) && !this.passing.has(key(a, b)); // prettier-ignore
    this.mode = "pieces";
    this.world = w;
    this.extras?.build(w); // lane Hands engine A
    this.joints = makeJoints(this, w); // lane Hands engine B: hinges, sliders, dials, sockets, breaks
    // Lane Hands engine C: ropes, cloth and stretch (src/physics/soft.js).
    this.softParts = hasSoft(hands) ? new SoftParts(this).build(hands, data, info) : null;
    return w;
  }

  free(body) {
    if (!body.pinned || body.fixedPiece) return; // (a fixed piece stays: lane Hands-on H1)
    body.pinned = false;
    const def = this.pieces.find((pc) => pc.body === body)?.def;
    if (def?.rest) {
      body.solid = def.solid;
      body.bound = boundOf(body);
    }
    body.invMass = body.invMassFree;
    body.invI = body.invIFree.slice();
    for (const pc of this.pieces) {
      const b = pc.body;
      // (Sunk in, not just resting on each other.)
      if (b !== body && b.pinned && this.world.touching(body, b, 0.04 * this.R())) this.passing.add(this.pairKey(body, b)); // prettier-ignore
    }
  }

  // ---- The finger ----

  // A press on the toy at world point `hit` (screen x, y). Returns true
  // when it is something Hands-on picks up (the drag is then ours).
  pressAt(hit, x, y) {
    if (!this.canGrab() || !hit) return false;
    // (Where the toy's own drag takes the press, a page, it pulls the page.)
    if (this.own && this.info.recipe.drag?.at?.(this.player.toRecipe(hit))) return false;
    if (this.extras?.pressAt(hit, x, y)) return true; // lane Hands engine A: a toy that flees the finger
    this.press = { hit: hit.slice(), x, y, t: this.time };
    return true;
  }

  // Lane Hands-on H3: a forgiving press. Where the pick buffer finds no
  // splat under the finger (between a desk lamp's arm and its beam, beside
  // a thin pen), the press still takes the toy when the finger's ray
  // crosses its body: in pieces mode a piece's `pick` ellipsoid (the
  // nearest along the ray), else the toy's box (trimmed to 0.85 of its
  // half sizes, as it stands now). A world point, or null.
  nearPress(x, y) {
    if (!this.canGrab() || !this.info) return null;
    const hands = this.info.recipe?.hands;
    const pieces = !!(hands?.pieces || hands?.joints);
    if (pieces) {
      this.ensure();
      if (this.mode !== "pieces") return null;
      const ray = this.ray(x, y);
      let best = Infinity;
      for (const pc of this.pieces) {
        const b = pc.body;
        const r = pc.def.pick || [b.bound, b.bound, b.bound];
        const t = rayEllipsoid(b, r, ray);
        if (t < best) best = t;
      }
      if (!Number.isFinite(best)) return null;
      return this.player.fromRecipe(v3.add(ray.origin, v3.scale(ray.dir, best)));
    }
    if (!this.info.center || !this.info.half) return null;
    const ray = this.player.stage.ray(x, y);
    const b = this.world && this.mode === "toy" ? this.body : null;
    const dq = b ? quat.mul(b.q, quat.conj(b.home.q)) : [0, 0, 0, 1];
    const toHome = (p) => (b ? v3.add(b.home.pos, quat.rotate(quat.conj(dq), v3.sub(p, b.pos))) : p); // prettier-ignore
    const o = toHome(ray.origin);
    const d = quat.rotate(quat.conj(dq), ray.dir);
    const c = this.info.center;
    const half = this.info.half.map((v) => 0.85 * v);
    let t0 = 0;
    let t1 = Infinity;
    for (let i = 0; i < 3; i++) {
      if (Math.abs(d[i]) < 1e-12) {
        if (Math.abs(o[i] - c[i]) > half[i]) return null;
        continue;
      }
      const a = (c[i] - half[i] - o[i]) / d[i];
      const e = (c[i] + half[i] - o[i]) / d[i];
      t0 = Math.max(t0, Math.min(a, e));
      t1 = Math.min(t1, Math.max(a, e));
    }
    if (t0 > t1) return null;
    const p = v3.add(o, v3.scale(d, t0));
    return b ? v3.add(b.pos, quat.rotate(dq, v3.sub(p, b.home.pos))) : p;
  }

  // The finger moved (screen x, y). The first move past a few pixels picks
  // the thing up; after that it follows.
  moveTo(x, y) {
    if (this.extras?.moveTo(x, y)) return; // lane Hands engine A: shakes, fleeing, wheels
    const pr = this.press;
    if (pr && !this.hold) {
      const d = Math.hypot(x - pr.x, y - pr.y);
      if (d < PRESS_MOVE) return;
      // A short drag on a whole toy is a nudge: the finger pushes it where
      // it touched, so it slides and turns a little. Further, it's picked
      // up (by the same spot, wherever the push left it).
      const pieces =
        !!(this.info?.recipe?.hands?.pieces || this.info?.recipe?.hands?.joints) ||
        hasSoft(this.info?.recipe?.hands);
      if (!pieces && d < NUDGE) {
        this.pushTo(pr, x, y);
        return;
      }
      const hit = pr.local && this.body ? this.body.toWorld(pr.local) : pr.hit;
      this.pickUp(hit, pr.x, pr.y);
    }
    const h = this.hold;
    if (!h) return;
    h.travel = Math.max(h.travel, Math.hypot(x - h.x0, y - h.y0));
    // Lane Hands-on H2: the finger's recent path on screen, for a flip.
    // (Only moves that move: a finger that stops after a flick keeps the
    // flick it made, however long the next event takes to come.)
    const sc = (h.screen ||= []);
    const last = sc[sc.length - 1];
    if (!last || Math.hypot(x - last.x, y - last.y) > 1) {
      sc.push({ t: this.simTime, x, y });
      while (sc[0].t < this.simTime - 2 * THROW_WINDOW) sc.shift();
    }
    const ray = this.ray(x, y);
    if (this.joints?.move(h, ray)) return; // lane Hands engine B: a joint's part follows
    if (h.place) {
      this.placeAt(h, ray);
      this.world.wake();
      return;
    }
    const n = h.plane.normal;
    const den = v3.dot(ray.dir, n);
    if (Math.abs(den) < 1e-4) return;
    const t = v3.dot(v3.sub(h.plane.point, ray.origin), n) / den;
    if (t < 0) return;
    let p = v3.add(ray.origin, v3.scale(ray.dir, t));
    // Keep the finger's point inside the play area, above the floor.
    const R = this.R();
    const fl = this.world.planes[0].d;
    // A toy resting on the floor can't be pressed into it: the finger's
    // point stays as high as it was when the toy stood there.
    p[1] = Math.max(p[1], fl + 0.05 * R, h.minY);
    p[1] = Math.min(p[1], fl + 5 * R);
    const lim = this.mode === "pieces" ? (this.info.recipe.hands.area ?? 1.6) * R : 1.6 * R;
    const c = this.body ? this.body.home.pos : [0, 0, 0];
    const [x0, x1, z0, z1] = this.mode === "pieces" ? this.walls() : [-lim, lim, -lim, lim];
    p[0] = Math.max(c[0] + x0, Math.min(c[0] + x1, p[0]));
    p[2] = Math.max(c[2] + z0, Math.min(c[2] + z1, p[2]));
    h.target = p;
    this.world.wake();
  }

  // A nudge: the finger's move (on the plane facing the view, through where
  // it pressed) is kept along the floor, for step() to push with.
  pushTo(pr, x, y) {
    const w = this.ensure();
    const b = this.body;
    if (!pr.local) {
      this.homing = null;
      pr.local = b.toLocal(pr.hit);
      pr.last = [pr.x, pr.y];
      pr.normal = this.ray(pr.x, pr.y).dir.slice();
    }
    const onPlane = (sx, sy) => {
      const ray = this.ray(sx, sy);
      const den = v3.dot(ray.dir, pr.normal);
      if (Math.abs(den) < 1e-4) return null;
      const t = v3.dot(v3.sub(pr.hit, ray.origin), pr.normal) / den;
      return t > 0 ? v3.add(ray.origin, v3.scale(ray.dir, t)) : null;
    };
    const a = onPlane(...pr.last);
    const c = onPlane(x, y);
    pr.last = [x, y];
    if (!a || !c) return;
    const d = v3.sub(c, a);
    d[1] = 0;
    pr.push = v3.add(pr.push ?? [0, 0, 0], d);
    this.moved = true;
    w.wake();
  }

  // The push: the touched point is pushed along the finger's way as fast as
  // the finger went (only pushed, never pulled), so where the finger is off
  // the middle the toy turns and tips a little too.
  pushStep(pr, dt) {
    const b = this.body;
    const d = pr.push;
    pr.push = null;
    const len = v3.len(d);
    if (!b || len < 1e-9) return;
    const n = v3.scale(d, 1 / len);
    const r = v3.sub(b.toWorld(pr.local), b.pos);
    const speed = Math.min(len / Math.max(dt, STEP), PUSH_MAX * this.R());
    const dv = speed - v3.dot(b.velAt(r), n);
    if (dv <= 0) return;
    b.applyVel(v3.scale(n, dv / b.weight(r, n)), r, 1);
  }

  pickUp(hit, x, y) {
    const w = this.ensure();
    this.unsqueeze(); // lane Hands-on H1
    this.homing = null;
    let body = this.body;
    if (this.mode === "pieces") {
      const world = hit;
      hit = this.player.toRecipe(hit);
      if (this.softPickUp(hit, world, x, y)) return; // lane Hands engine C
      body = this.pieceAt(hit);
      if (!body) {
        this.press = null;
        return;
      }
      if (this.joints?.grab(body, hit, x, y)) return; // lane Hands engine B
      this.free(body);
    }
    const ray = this.ray(x, y);
    // Pieces are picked and placed: held by the middle, turned level (only
    // their turn about the upright stays), hovering just above whatever is
    // under the finger, so letting go sets one down on a stack. (Lane
    // Hands-on H2: a piece whose def says `place: false` hangs and swings
    // in the hand instead, as every piece does with `hands.place: false`.)
    const pdef = this.pieces.find((pc) => pc.body === body)?.def;
    const place = this.mode === "pieces" && this.info.recipe.hands.place !== false && pdef?.place !== false; // prettier-ignore
    const la = place ? [0, 0, 0] : body.toLocal(hit);
    const at = place ? body.pos.slice() : hit;
    // A little give, so a wall or the floor wins over the finger instead
    // of the two fighting.
    const joint = w.joint(body, la, null, at, { compliance: 2e-6, damping: 0 });
    body.held = true;
    const def = this.pieces.find((pc) => pc.body === body)?.def;
    body.holdQ = place ? yawOnly(body.q) : def?.joint ? null : body.q.slice();
    // Lane Hands-on H2: a `flip` piece lying upside down is held upside down
    // (a pancake flipped once stays flipped in the hand).
    if (place && def?.flip && quat.rotate(body.q, [0, 1, 0])[1] < 0) body.holdQ = quat.mul(body.holdQ, quat.axisAngle([1, 0, 0], Math.PI)); // prettier-ignore
    // A piece being placed stays level; anything else hangs and swings.
    body.holdK = place ? 10 : HOLD_UPRIGHT;
    body.angDampingFree ??= body.angDamping;
    body.angDamping = place ? 7 : HOLD_SWING_DAMPING;
    // The held point follows the finger on a critically damped spring
    // (`follow`, `followV`); `trail` is the finger's recent path, for the
    // let-go's speed; `travel` how far (CSS pixels) the finger went.
    // (A toy that floats, on water or in air, can be pushed down below where
    // it stands: lane Hands-on H4.)
    const floats = this.extras?.water || this.extras?.air;
    const minY = this.mode === "toy" && !floats ? hit[1] - (body.pos[1] - body.home.pos[1]) : -Infinity; // prettier-ignore
    this.hold = { body, joint, place, plane: { point: hit.slice(), normal: ray.dir.slice() }, target: at.slice(), follow: at.slice(), followV: [0, 0, 0], trail: [], x0: x, y0: y, travel: 0, minY, raise: this.mode === "toy" ? PICK_LIFT * this.R() : 0 }; // prettier-ignore
    if (place) {
      // Lifted first, then it follows the finger.
      this.hold.lift = this.time;
      this.placeAt(this.hold, ray);
    }
    this.moved = true;
    this.press = null;
    w.wake();
  }

  // Lane Hands engine C: a press on a rope's or a cloth's node takes that
  // node (unless a piece is right there); a press on a stretchy toy away
  // from its pieces stretches it.
  softPickUp(hit, world, x, y) {
    const sp = this.softParts;
    if (!sp) return false;
    const node = sp.pick(hit);
    const onPiece = this.pieceAt(hit);
    let what = null;
    if (node && (node.d < 1 || (!onPiece && node.d < 1.6))) what = node;
    else if (!onPiece && sp.stretch && (sp.stretch.def.at?.(hit) ?? true)) what = "stretch";
    if (!what || !sp.grab(what, world)) return false;
    const at = what === "stretch" ? hit : what.node.x.slice();
    const ray = this.ray(x, y);
    this.hold = { soft: true, plane: { point: at.slice(), normal: ray.dir.slice() }, target: at.slice(), follow: at.slice(), followV: [0, 0, 0], trail: [], x0: x, y0: y, travel: 0, minY: -Infinity, raise: 0 }; // prettier-ignore
    this.moved = true;
    this.press = null;
    this.world.wake();
    return true;
  }

  // Where a held piece hovers: over the first thing the finger's ray meets
  // (another piece, as an ellipsoid of its `pick` radii, or the floor), its
  // underside a little above it.
  placeAt(h, ray) {
    const R = this.R();
    const b = h.body;
    const fl = this.world.planes[0].d;
    let best = Infinity;
    let top = fl;
    let n = [0, 1, 0];
    for (const pc of this.pieces) {
      const o = pc.body;
      if (o === b) continue;
      const r = pc.def.pick || [o.bound, o.bound, o.bound];
      const t = rayEllipsoid(o, r, ray);
      if (t < best) {
        best = t;
        const p = v3.add(ray.origin, v3.scale(ray.dir, t));
        top = p[1];
        n = p;
      }
    }
    const [x0, x1, z0, z1] = this.inWalls(b);
    const tf = ray.dir[1] < -1e-4 ? (fl - ray.origin[1]) / ray.dir[1] : Infinity;
    const pf = tf < Infinity ? v3.add(ray.origin, v3.scale(ray.dir, tf)) : null;
    const inside = pf && pf[0] >= x0 && pf[0] <= x1 && pf[2] >= z0 && pf[2] <= z1;
    let p;
    if (tf < best && inside) {
      p = pf;
      top = fl;
    } else if (best < Infinity) p = n;
    else {
      // Over nothing (the finger is up in the air): it hangs where the
      // finger's line passes the piece's own upright.
      const c = b.pos;
      const d = [ray.dir[0], 0, ray.dir[2]];
      const dd = v3.dot(d, d) || 1;
      const t = -((ray.origin[0] - c[0]) * d[0] + (ray.origin[2] - c[2]) * d[2]) / dd;
      p = v3.add(ray.origin, v3.scale(ray.dir, t));
      h.target = [Math.max(x0, Math.min(x1, p[0])), Math.max(fl + 0.1 * R, Math.min(fl + 5 * R, p[1])), Math.max(z0, Math.min(z1, p[2]))]; // prettier-ignore
      return;
    }
    const def = this.pieces.find((pc) => pc.body === b)?.def;
    const below = def?.pick ? def.pick[1] : b.bound;
    // What is right under it there: straight down from above, at its
    // middle and four points round its footprint.
    // (Lane Hands-on H2: `hands.foot`, the share of its pick radius looked
    // under, so a wide piece set beside a stack sits on its edge instead of
    // being lowered into it.)
    const foot = def?.pick ? (this.info.recipe.hands.foot ?? 0.6) * Math.min(def.pick[0], def.pick[2]) : 0.5 * b.bound; // prettier-ignore
    // A recipe may snap it onto the piece below (a brick onto the studs).
    const snap = this.info.recipe.hands.snap;
    const under = (at) => {
      let y = fl;
      let who = null;
      const spots = [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]; // prettier-ignore
      for (const [dx, dz] of spots) {
        const o = [at[0] + dx * foot, fl + 6 * R, at[2] + dz * foot];
        for (const pc of this.pieces) {
          if (pc.body === b) continue;
          const r = pc.def.pick || [pc.body.bound, pc.body.bound, pc.body.bound];
          const t = rayEllipsoid(pc.body, r, { origin: o, dir: [0, -1, 0] });
          if (t < Infinity && o[1] - t > y) {
            y = o[1] - t;
            who = pc;
          }
        }
      }
      return { y, who };
    };
    let u = under(p);
    // A recipe's `center` (0..1) draws it toward the middle of the piece
    // under it (a hand sets a stone on a stone, not on its edge).
    const pull = this.info.recipe.hands.center ?? 0;
    if (pull && u.who) {
      const c = u.who.body.pos;
      p = [p[0] + (c[0] - p[0]) * pull, p[1], p[2] + (c[2] - p[2]) * pull];
      u = under(p);
    }
    if (snap && u.who) {
      const me = this.pieces.find((pc) => pc.body === b);
      const r = snap({ held: me, under: u.who, at: p.slice() });
      if (r) {
        p = r.at;
        if (r.quat) b.holdQ = r.quat;
        u = under(p);
      }
    }
    top = u.y;
    const y = top + below + (this.info.recipe.hands.lift ?? 0.06 * R);
    h.target = [Math.max(x0, Math.min(x1, p[0])), Math.min(fl + 5 * R, y), Math.max(z0, Math.min(z1, p[2]))]; // prettier-ignore
  }

  // The piece under a point: the one whose shape (the piece's `pick`
  // radii, an ellipsoid about its middle, else its reach) it is nearest
  // to, measured in that shape's own size.
  pieceAt(p) {
    let best = null;
    let bd = Infinity;
    const data = this.player.proc?.ctx?.kit?.data;
    for (const pc of this.pieces) {
      const b = pc.body;
      // Lane Hands-on H5: `when(data)` false: not to be picked up now (an
      // atlas's organs while its skin is on).
      if (pc.def.when && !pc.def.when(data)) continue;
      if (b.fixedPiece) continue; // (never picked up: lane Hands-on H1)
      const l = b.toLocal(p);
      const r = pc.def.pick || [b.bound, b.bound, b.bound];
      const d = Math.hypot(l[0] / r[0], l[1] / r[1], l[2] / r[2]);
      if (d < bd) {
        bd = d;
        best = b;
      }
    }
    return bd < 1.6 ? best : null;
  }

  // Lane Hands-on H1: `hands.press` ({ amount, after }): a press held
  // still on a whole toy for `after` seconds (0.15) squeezes it down by
  // `amount` (0.25) and plays its sound (a hit with `press: true`); let go,
  // it springs back with the landing squish's wobble. A drag still picks it
  // up as before.
  pressStep() {
    const pd = this.info?.recipe?.hands?.press;
    const pr = this.press;
    if (!pd || !pr || this.hold || pr.push || pr.local || pr.squeezed) return;
    if (this.time - pr.t < (pd.after ?? 0.15)) return;
    this.ensure();
    if (this.mode !== "toy") return;
    pr.squeezed = true;
    const b = this.body;
    this.squish = { amp: pd.amount ?? 0.25, t0: this.time, axis: [0, 1, 0], point: [b.pos[0], this.world.planes[0].d, b.pos[2]], held: true }; // prettier-ignore
    this.moved = true;
    this.sounds.push({ speed: 3, soft: this.soft ?? 0, piece: false, press: true });
  }

  // The squeeze let go: it springs back.
  unsqueeze() {
    if (!this.squish?.held) return;
    this.squish.held = false;
    this.squish.t0 = this.time;
  }

  // Lets go: whatever it was holding flies on with the finger's speed.
  release() {
    if (this.extras?.release()) return true; // lane Hands engine A
    this.unsqueeze(); // lane Hands-on H1
    const h = this.hold;
    this.press = null;
    if (!h) return false;
    if (this.joints?.release(h)) return true; // lane Hands engine B
    if (h.soft) {
      this.softParts.release(this.throwSpeed(h)); // lane Hands engine C
      this.hold = null;
      return true;
    }
    this.world.removeJoint(h.joint);
    h.body.held = false;
    h.body.holdQ = null;
    h.body.angDamping = h.body.angDampingFree ?? h.body.angDamping;
    // It flies on with the finger's speed over the last moment, not with
    // whatever the body's own speed was in the last step.
    const R = this.R();
    h.body.vel = this.throwSpeed(h);
    h.body.damping = Math.max(h.body.damping, AIR_DRAG);
    // A piece being placed is set down, not thrown.
    if (h.place) {
      if (this.flip(h)) return true; // lane Hands-on H2: a pancake flipped
      this.extras?.thrown(h); // lane Hands engine A
      // Set down from where it hovers at least, so a quick let-go never
      // starts it inside the piece below (it may still be catching up).
      if (h.body.pos[1] < h.target[1]) h.body.pos[1] = h.target[1];
      h.body.vel = [0, 0, 0];
      h.body.omega = [0, 0, 0];
      this.hold = null;
      this.world.wake();
      return true;
    }
    // A thrown thing turns a little the way it flies (a hanging piece, the
    // cherries, keeps its own swing).
    const fwd = v3.cross([0, 1, 0], h.body.vel);
    // It keeps the swing it had in the hand.
    const hung = this.pieces.find((pc) => pc.body === h.body)?.def?.joint;
    if (!hung)
      h.body.omega = v3.add(h.body.omega, v3.scale(fwd, 0.25 / Math.max(h.body.bound, 0.2 * R)));
    const wmax = 14;
    const ws = v3.len(h.body.omega);
    if (ws > wmax) h.body.omega = v3.scale(h.body.omega, wmax / ws);
    this.extras?.thrown(h); // lane Hands engine A: the material's weight and spin
    this.hold = null;
    this.world.wake();
    return true;
  }

  // Lane Hands-on H2: a piece whose def says `flip: true`, let go from a
  // quick flick up the screen (faster up than across), is tossed straight
  // up with half a turn about the level line across the view, timed to come
  // down upside down where it rose from: a pancake flipped in the pan.
  flip(h) {
    const b = h.body;
    const def = this.pieces.find((pc) => pc.body === b)?.def;
    if (!def?.flip || h.travel < NUDGE) return false;
    const s = h.screen || []; // (its last 2 × THROW_WINDOW of moves; they come once a frame)
    if (s.length < 2) return false;
    // A flick is let go of as it ends, not after a long hold.
    if (this.simTime - s[s.length - 1].t > FLIP_HOLD) return false;
    const dt = s[s.length - 1].t - s[0].t;
    if (dt < 1e-6) return false;
    const vx = (s[s.length - 1].x - s[0].x) / dt;
    const vy = (s[0].y - s[s.length - 1].y) / dt; // CSS pixels per second, up
    if (vy < FLIP_PX || vy < Math.abs(vx)) return false;
    const R = this.R();
    const up = FLIP_UP * R;
    const g = Math.max(1e-6, -this.world.gravity[1]);
    if (b.pos[1] < h.target[1]) b.pos[1] = h.target[1]; // (from where it hovers, as a set-down)
    // It comes down where it was before the flick (the finger's flick up
    // the screen carries the hovering piece off along the floor), on
    // whatever is under that spot (a piece's pick ellipsoid, or the
    // floor), drawn toward that piece's middle as a set-down is.
    const was = h.trail[0]?.p || b.pos;
    let at = [was[0], was[2]];
    let ground = this.world.planes[0].d;
    let onto = null;
    for (const pc of this.pieces) {
      if (pc.body === b) continue;
      const r = pc.def.pick || [pc.body.bound, pc.body.bound, pc.body.bound];
      const o = [at[0], b.pos[1] + 6 * R, at[1]];
      const d = rayEllipsoid(pc.body, r, { origin: o, dir: [0, -1, 0] });
      if (d < Infinity && o[1] - d > ground) {
        ground = o[1] - d;
        onto = pc.body;
      }
    }
    const pull = this.info.recipe.hands.center ?? 0;
    if (onto) at = at.map((v, i) => v + ((i ? onto.pos[2] : onto.pos[0]) - v) * pull);
    const drop = Math.max(0, b.pos[1] - ground - (def.pick ? def.pick[1] : b.bound));
    const t = (up + Math.sqrt(up * up + 2 * g * drop)) / g; // up, then down onto it
    let axis = v3.cross(this.ray(h.x0, h.y0).dir, [0, 1, 0]);
    axis = v3.len(axis) > 1e-9 ? v3.norm(axis) : [1, 0, 0];
    // Half a turn by the time it lands, its spin slowed by angDamping on the way.
    const k = b.angDamping;
    const w = k > 1e-6 ? (Math.PI * k) / (1 - Math.exp(-k * t)) : Math.PI / t;
    b.vel = [(at[0] - b.pos[0]) / t, up, (at[1] - b.pos[2]) / t];
    b.omega = v3.scale(axis, w);
    this.extras?.thrown(h); // lane Hands engine A
    this.hold = null;
    this.world.wake();
    return true;
  }

  // The let-go's speed: the finger's over the last THROW_WINDOW (a line fit
  // through its samples, so one jittery sample doesn't count), nothing for
  // a nudge or a still hold, and never faster than THROW_MAX.
  throwSpeed(h) {
    const R = this.R();
    const s = h.trail.filter((e) => e.t >= this.simTime - THROW_WINDOW - 1e-9);
    if (h.travel < NUDGE || s.length < 3) return [0, 0, 0];
    const n = s.length;
    const tm = s.reduce((a, e) => a + e.t, 0) / n;
    let den = 0;
    for (const e of s) den += (e.t - tm) ** 2;
    if (den < 1e-12) return [0, 0, 0];
    const v = [0, 1, 2].map((i) => {
      const pm = s.reduce((a, e) => a + e.p[i], 0) / n;
      let num = 0;
      for (const e of s) num += (e.t - tm) * (e.p[i] - pm);
      return num / den;
    });
    const sp = v3.len(v);
    if (sp < THROW_MIN * R) return [0, 0, 0];
    return sp > THROW_MAX * R ? v3.scale(v, (THROW_MAX * R) / sp) : v;
  }

  get holding() {
    return !!this.hold;
  }

  // A tap on the toy: a latched joint with a `trigger` lets go (lane
  // Hands-on H3). True when one did.
  trigger() {
    return !!this.joints?.trigger();
  }

  // ↺: everything glides home.
  reset() {
    this.press = null;
    if (this.hold) this.release();
    const soft = this.softParts?.reset(); // lane Hands engine C
    if (!this.world || !this.moved) return !!soft;
    const bodies = this.mode === "toy" ? [this.body] : this.pieces.map((p) => p.body);
    this.homing = { t0: this.time, from: bodies.map((b) => ({ b, pos: b.pos.slice(), q: b.q.slice() })) }; // prettier-ignore
    this.squish = null;
    return true;
  }

  // ---- Each frame ----

  // Advances the world by dt and puts the result on the toy. Returns true
  // while anything moves.
  step(dt) {
    this.time += dt;
    // A toy that asks for Level 1 only while it isn't a live tool (lane
    // Hands-on H3): when it becomes one (a file opened), the switch goes off
    // and the toy glides home; either way the app is told, to show or hide ✋.
    if (this.info) {
      const can = canPlay(this.info);
      if (this.available !== undefined && can !== this.available) {
        if (!can && this.on) this.setOn(false);
        this.player.emit?.("hands-available", can);
      }
      this.available = can;
    }
    const extra = this.extras?.step(dt) || false; // lane Hands engine A
    this.pressStep(); // lane Hands-on H1: a held press squeezes the toy
    const w = this.world;
    if (!w) return extra;
    let busy = extra;
    const h = this.hold;
    if (h) busy = true;
    if (this.press?.push) {
      this.pushStep(this.press, dt);
      busy = true;
    }
    if (this.homing) {
      const f = Math.min(1, (this.time - this.homing.t0) / HOME_SECS);
      const e = f * f * (3 - 2 * f);
      for (const { b, pos, q } of this.homing.from) {
        if (this.joints?.home(b, e)) continue; // lane Hands engine B: along its joint
        b.pos = pos.map((v, i) => v + (b.home.pos[i] - v) * e);
        b.q = quat.slerp(q, b.home.q, e);
        b.vel = [0, 0, 0];
        b.omega = [0, 0, 0];
      }
      busy = true;
      if (f >= 1) {
        for (const { b } of this.homing.from) {
          b.goHome();
          if (this.mode === "pieces" && !b.pinned) {
            b.pinned = true;
            const def = this.pieces.find((pc) => pc.body === b)?.def;
            if (def?.rest) {
              b.solid = def.rest;
              b.bound = boundOf(b);
            }
            b.invMass = 0;
            b.invI = [0, 0, 0];
          }
        }
        this.homing = null;
        this.moved = false;
        this.joints?.reset(); // lane Hands engine B: parts home, breaks mended
        this.passing?.clear();
        w.asleep = true;
      }
    } else {
      // Fixed steps of STEP (a slow frame catches up, up to 0.1 s), so the
      // same drag does the same thing at any frame rate.
      this.acc = Math.min(this.acc + dt, 0.1);
      while (this.acc >= STEP - 1e-9) {
        this.acc -= STEP;
        this.simTime += STEP;
        if (h && !h.ctl) this.followStep(h);
        if (w.step(STEP)) busy = true;
        if (this.joints?.step(STEP)) busy = true; // lane Hands engine B
        if (this.softParts?.step(STEP, this.simTime)) busy = true; // lane Hands engine C
      }
    }
    if (this.homing && this.softParts?.step(dt, this.time)) busy = true;
    if (this.softParts) for (const e of this.softParts.takeEvents()) this.sounds.push({ ...e, soft: 1, piece: true }); // prettier-ignore
    if (this.passing?.size) {
      const byId = new Map(this.pieces.map((pc) => [pc.body.id, pc.body]));
      for (const k of this.passing) {
        const [a, b] = k.split(":").map((v) => byId.get(Number(v)));
        if (!a || !b || !w.touching(a, b)) this.passing.delete(k);
      }
    }
    for (const hit of w.takeHits()) this.onHit(hit);
    if (this.squish) {
      const s = this.squish;
      const t = this.time - s.t0;
      if (s.held) busy = true;
      else if (t > 1.2) this.squish = null;
      else busy = true;
    }
    this.apply();
    return busy || !w.asleep;
  }

  // One STEP of the held point after the finger: a critically damped
  // spring (no overshoot), and a sample of the finger's path.
  followStep(h) {
    // (Stepped exactly, so it's steady at any stiffness.)
    const k = h.place ? PLACE_FOLLOW : FOLLOW;
    const decay = Math.exp(-k * STEP);
    for (let i = 0; i < 3; i++) {
      const to = h.target[i] + (i === 1 && !h.place ? h.raise : 0); // lifted as it's picked up
      const e = h.follow[i] - to;
      const v = h.followV[i];
      const c = v + k * e;
      h.follow[i] = to + (e + c * STEP) * decay;
      h.followV[i] = (v - k * c * STEP) * decay;
    }
    if (h.soft)
      this.softParts.drag(h.follow); // lane Hands engine C
    else h.joint.lb = h.follow.slice();
    h.trail.push({ t: this.simTime, p: h.target.slice() });
    while (h.trail.length && h.trail[0].t < this.simTime - 2 * THROW_WINDOW) h.trail.shift();
  }

  onHit(hit) {
    this.extras?.onHit(hit); // lane Hands engine A: projectiles stick in targets
    const R = this.R();
    this.joints?.hit(hit); // lane Hands engine B: a knock breaks a piece off
    const speed = hit.speed / R;
    // A free piece that hits a pinned one knocks it loose.
    // (Not by the piece in the hand: it brushes past others as it goes.)
    // Lane Hands-on H5: `hands.knock: false`: pieces leave their places only
    // when picked (a solid's faces: one set down doesn't knock the rest off).
    const knock = this.info?.recipe?.hands?.knock !== false;
    if (knock && this.mode === "pieces" && !hit.body?.held && !hit.other?.held) {
      if (hit.other?.pinned && speed > 2.5) this.free(hit.other);
      if (hit.body?.pinned && speed > 2.5) this.free(hit.body);
    }
    if (this.mode === "toy" && this.soft > 0 && speed > 0.8) {
      const amp = Math.min(0.45, this.soft * 0.08 * speed);
      if (!this.squish || amp > this.squishAmp()) {
        this.squish = { amp, t0: this.time, axis: hit.n.slice(), point: hit.point.slice() };
      }
    }
    // (What it hit and where, for a recipe's sound: lane Hands-on H3.)
    // `name` and `against` are the two pieces' names (their `name`, part or
    // token), so a drum's stick on its skin can sound the drum.
    this.sounds.push({ speed, soft: this.soft ?? 0, piece: this.mode === "pieces", body: hit.body, other: hit.other, name: this.nameOf(hit.body), against: this.nameOf(hit.other), point: hit.point?.slice() }); // prettier-ignore
  }

  // A piece's name, for sounds (lane Hands-on H3): null for the floor.
  nameOf(body) {
    if (!body) return null;
    const p = this.pieces.find((q) => q.body === body);
    return p ? (p.def?.name ?? p.part ?? p.token ?? null) : null;
  }

  squishAmp() {
    const s = this.squish;
    if (!s) return 0;
    const t = this.time - s.t0;
    if (s.held) return s.amp * Math.min(1, t / 0.08); // squeezed, while the finger stays
    return s.amp * Math.exp(-4.5 * t) * Math.cos(12 * t);
  }

  // Puts the bodies' poses on the toy: the entity for Level 1, tokens for
  // pieces.
  apply() {
    const player = this.player;
    if (this.mode === "toy") {
      const b = this.body;
      const c = b.home.pos;
      const dq = quat.mul(b.q, quat.conj(b.home.q));
      const t = v3.sub(b.pos, c);
      const home = !this.moved && !this.homing;
      player.stage.setToyPose?.(home ? null : { pivot: c, q: dq, t });
      // Lane Any pose: the shader works every effect out in the toy's own
      // frame now (src/effects-pose.js), parts and tokens included, so the
      // kit's uniforms are no longer posed here (poseKitUniforms).
      player.motion.handsFix = null;
      return;
    }
    if (this.mode === "pieces") {
      const out = [];
      for (const pc of this.pieces) {
        const b = pc.body;
        // (A reseated piece is pinned in its seat and still shown there: lane
        // Hands-on H3.)
        if (b.pinned && !b.seated && !this.homing) continue;
        // (From where its splats were built; lane Hands-on H2's `shown`. A
        // joint's own piece has no `built`: its home.)
        const bt = pc.built || pc.home;
        const dq = quat.mul(b.q, quat.conj(bt.q));
        const token = { base: bt.pos, offset: v3.sub(b.pos, bt.pos), quat: dq };
        if (pc.token !== undefined) out.push({ index: pc.token, token });
        // Lane Hands-on H2: other tokens that ride with it (`ride`: an
        // index, or { token, visible }), a banana's skin strips.
        for (const r of pc.def.ride || []) {
          if (r.part) continue; // (a riding part: below)
          out.push(typeof r === "number" ? { index: r, token } : { index: r.token, token: { ...token, visible: r.visible ?? 1 } }); // prettier-ignore
        }
      }
      // Lane Hands engine C: what the ropes, cloth and stretch move.
      const so = this.softParts?.output();
      if (so) out.push(...so.tokens);
      player.motion.handsTokens = out.length ? out : null;
      // Pieces that are a recipe's parts (turned about the part's pivot).
      let parts = null;
      for (const pc of this.pieces) {
        if (!pc.part) continue;
        const b = pc.body;
        const bt = pc.built || pc.home;
        const dq = quat.mul(b.q, quat.conj(bt.q));
        const pv = pc.def.pivot || bt.pos;
        const off = v3.sub(v3.sub(b.pos, pv), quat.rotate(dq, v3.sub(bt.pos, pv)));
        (parts ||= {})[pc.part] = { quat: dq, offset: off };
        // Lane Hands-on H2: `offHome` is merged in while it is off its place
        // (a candle pulled out of the cake goes out: { visible: 0 }).
        if (pc.def.offHome && !b.pinned) Object.assign(parts[pc.part], pc.def.offHome);
        // Other parts that ride with it ({ part, pivot, upside }), and what
        // is merged into them while it lies upside down (a pancake's syrup,
        // flipped under it, is hidden: { visible: 0 }).
        const upside = quat.rotate(b.q, [0, 1, 0])[1] < 0;
        for (const r of pc.def.ride || []) {
          if (!r.part) continue;
          const pr = r.pivot || pv;
          parts[r.part] = { quat: dq, offset: v3.sub(v3.sub(b.pos, pr), quat.rotate(dq, v3.sub(bt.pos, pr))) }; // prettier-ignore
          if (r.upside && upside) Object.assign(parts[r.part], r.upside);
        }
      }
      if (this.joints) parts = this.joints.parts(parts); // lane Hands engine B
      if (so) parts = Object.assign(parts || {}, so.parts); // lane Hands engine C
      player.motion.handsParts = this.moved || this.homing || so ? parts : null;
      // Sort the moved pieces again now and then (and once they rest).
      const asleep = this.world.asleep;
      // (Lane Hands-on H2: `hands.resort`, seconds, for a toy whose pieces
      // turn fast in front of its own splats, a sunflower's nodding head.)
      const every = this.info.recipe.hands.resort ?? 0.25;
      // (Lane Hands-on H2: pieces that are parts are sorted too, by the
      // player's part pass: a flipped pancake drew in its old order, the
      // one under it showing through it.)
      const moving =
        out.length > 0 || (!!(this.moved || this.homing) && !!player.motion.handsParts);
      if (moving && (this.time - this.lastResort > every || (asleep && !this.restSorted))) {
        this.lastResort = this.time;
        this.restSorted = asleep;
        player.motion.handsResort = true;
      }
      // (Lane Hands-on H2: once more when the last moved piece is home, so
      // a slice clicked back in isn't drawn in the order it had outside.)
      if (!moving && this.hadOut) player.motion.handsResort = true;
      this.hadOut = moving;
      if (!asleep) this.restSorted = false;
    }
  }

  // Where the view should drift (world offset), so a tossed toy stays in
  // sight on a narrow phone; null when it is home.
  follow() {
    if (this.mode !== "toy" || (!this.moved && !this.homing)) return null;
    const d = v3.sub(this.body.pos, this.body.home.pos);
    // (A toy may drift the view less, so its roll reads: hands.view.)
    const k = this.info?.recipe?.hands?.view ?? 0.8;
    return [d[0] * k, d[1] * 0.5, d[2] * k];
  }

  // The squish, as the shader wants it (model space): { axis, amount,
  // pivot } or null.
  squishUniforms() {
    if (this.mode !== "toy" || !this.squish) return null;
    const s = this.squish;
    const amount = this.squishAmp();
    const stage = this.player.stage;
    const pivot = stage.worldToModel(s.point);
    const o = stage.worldToModel([0, 0, 0]);
    const a = stage.worldToModel(s.axis);
    const axis = v3.norm(v3.sub(a, o));
    return { axis, amount, pivot };
  }

  takeSounds() {
    const s = this.sounds;
    this.sounds = [];
    return s;
  }

  // For tests and clips: where the toy (or each piece) is.
  state() {
    const bodies = this.mode === "toy" ? [this.body] : this.pieces.map((p) => p.body);
    return {
      on: this.on,
      mode: this.mode,
      moved: this.moved,
      holding: !!this.hold,
      asleep: this.world ? this.world.asleep : true,
      soft: this.softParts?.state() ?? null, // lane Hands engine C
      bodies: bodies.filter(Boolean).map((b) => ({ pos: b.pos.slice(), q: b.q.slice(), home: b.home.pos.slice(), pinned: !!b.pinned })), // prettier-ignore
    };
  }
}

// A rotation's turn about the upright alone (a piece picked up level).
function yawOnly(q) {
  const f = quat.rotate(q, [1, 0, 0]);
  const a = Math.atan2(-f[2], f[0]);
  return quat.axisAngle([0, 1, 0], a);
}

// Where a ray first meets body o's ellipsoid of radii r (Infinity: never).
function rayEllipsoid(o, r, ray) {
  const lo = o.toLocal(ray.origin);
  const ld = quat.rotate(quat.conj(o.q), ray.dir);
  const p = [lo[0] / r[0], lo[1] / r[1], lo[2] / r[2]];
  const d = [ld[0] / r[0], ld[1] / r[1], ld[2] / r[2]];
  const a = v3.dot(d, d);
  const bb = 2 * v3.dot(p, d);
  const c = v3.dot(p, p) - 1;
  const disc = bb * bb - 4 * a * c;
  if (disc < 0) return Infinity;
  const t = (-bb - Math.sqrt(disc)) / (2 * a);
  return t > 0 ? t : Infinity;
}

// n directions spread evenly over the sphere.
function fibonacci(n) {
  const out = [];
  const ga = Math.PI * (3 - Math.sqrt(5));
  for (let i = 0; i < n; i++) {
    const y = 1 - (2 * (i + 0.5)) / n;
    const r = Math.sqrt(1 - y * y);
    out.push([Math.cos(ga * i) * r, y, Math.sin(ga * i) * r]);
  }
  return out;
}

